CREATE OR REPLACE FUNCTION private.archive_cancelled_registration_orphan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare batch_record public.registration_batches%rowtype;
begin
  if new.status <> 'cancelled' or old.status = 'cancelled' or new.registration_batch_id is null then return new; end if;
  select * into batch_record from public.registration_batches where id=new.registration_batch_id for update;
  if batch_record.provisional_customer_id is null or batch_record.provisional_customer_id<>batch_record.customer_id then return new; end if;
  if exists(select 1 from public.registration_requests r where r.registration_batch_id=batch_record.id and r.status<>'cancelled') then return new; end if;
  if exists(select 1 from public.payments p where p.customer_id=batch_record.customer_id and p.payment_status='completed') then return new; end if;
  if exists(select 1 from public.registration_requests r where r.customer_id=batch_record.customer_id and r.registration_batch_id is distinct from batch_record.id) then return new; end if;
  if exists(select 1 from public.kiosks k where k.customer_id=batch_record.customer_id and not exists(
    select 1 from public.registration_batch_items i where i.batch_id=batch_record.id and i.kiosk_id=k.id
  )) then return new; end if;
  update public.customers set status='inactive',archived_at=coalesce(archived_at,now()),
    archived_reason='cancelled_unpaid_registration:'||batch_record.id where id=batch_record.customer_id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_active_admin()
 RETURNS user_roles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập.' using errcode = '42501';
  end if;

  select *
  into actor
  from public.user_roles ur
  where ur.user_id = auth.uid()
    and ur.is_active = true
    and lower(ur.role) = 'admin';

  if not found then
    raise exception 'Chỉ Admin đang hoạt động được thực hiện thao tác này.'
      using errcode = '42501';
  end if;
  return actor;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_audit_access()
 RETURNS user_roles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.user_roles%rowtype;
begin
  if not public.has_user_permission('logs') then
    raise exception 'Không có quyền xem audit log.' using errcode = '42501';
  end if;
  select up.user_id, up.username, coalesce(up.display_name, up.username),
    case when up.is_system_admin then 'admin' else 'staff' end, true,
    up.created_at, up.updated_at
  into actor from public.user_profiles up where up.user_id = auth.uid();
  return actor;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_payment_permission()
 RETURNS user_roles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.user_roles%rowtype;
begin
  if not public.has_user_permission('payments') then
    raise exception 'Không có quyền xử lý thanh toán.' using errcode = '42501';
  end if;
  select up.user_id, up.username, coalesce(up.display_name, up.username),
    case when up.is_system_admin then 'admin' else 'staff' end, true,
    up.created_at, up.updated_at
  into actor from public.user_profiles up where up.user_id = auth.uid();
  return actor;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_registration_permission()
 RETURNS user_roles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.user_roles%rowtype;
begin
  if not public.has_user_permission('registration-requests') then
    raise exception 'Không có quyền xử lý hồ sơ đăng ký.' using errcode = '42501';
  end if;
  select up.user_id, up.username, coalesce(up.display_name, up.username),
    case when up.is_system_admin then 'admin' else 'staff' end, true,
    up.created_at, up.updated_at
  into actor
  from public.user_profiles up
  where up.user_id = auth.uid();
  if not found then
    raise exception 'Không tìm thấy hồ sơ người dùng.' using errcode = '42501';
  end if;
  return actor;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_ttc_staff(permission_input text DEFAULT 'admin-ttc'::text)
 RETURNS user_roles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập.' using errcode = '42501';
  end if;

  select *
  into actor
  from public.user_roles ur
  where ur.user_id = auth.uid()
    and ur.is_active = true
    and (
      lower(ur.role) = 'admin'
      or exists (
        select 1
        from public.role_permissions rp
        where lower(rp.role) = lower(ur.role)
          and permission_input = any(rp.permissions)
      )
    );

  if not found then
    raise exception 'Không có quyền quản trị TTC.' using errcode = '42501';
  end if;

  return actor;
end;
$function$

CREATE OR REPLACE FUNCTION private.audit_promotion_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare action_value text;
begin
  action_value:=case when tg_op='INSERT' then 'create_promotion' when old.is_active and not new.is_active then 'pause_promotion' when not old.is_active and new.is_active then 'reactivate_promotion' else 'update_promotion' end;
  perform private.write_ttc_audit('Promotion',action_value,'promotions',new.id::text,case when tg_op='UPDATE' then to_jsonb(old) else null end,to_jsonb(new),case action_value when 'create_promotion' then 'Created promotion' when 'pause_promotion' then 'Paused promotion' when 'reactivate_promotion' then 'Reactivated promotion' else 'Updated promotion' end);
  return new;
end;$function$

CREATE OR REPLACE FUNCTION private.claim_payos_active_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.purpose<>'crm_payment' then return new; end if;
  begin new.expires_at:=coalesce(new.expires_at,to_timestamp((new.provider_payload->>'expiresAt')::bigint)); exception when others then null; end;
  update public.payos_orders set status='expired',active_slot=null,processed_at=coalesce(processed_at,now()),updated_at=now()
  where payment_id=new.payment_id and purpose='crm_payment' and status='pending' and active_slot is true
    and expires_at is not null and expires_at<=now();
  new.active_slot:=true;
  return new;
end;$function$

CREATE OR REPLACE FUNCTION private.complete_payment(payment_id_input bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payment_record public.payments%rowtype;
  actor text;
  confirmation_date date;
  effective_start_date date;
  calculated_end_date date;
begin
  select *
  into payment_record
  from public.payments
  where id = payment_id_input
    and payment_status = 'pending'
  for update;

  if not found then
    raise exception 'Không tìm thấy thanh toán chờ xác nhận.';
  end if;

  actor := coalesce(auth.uid()::text, 'system');
  confirmation_date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  effective_start_date := greatest(
    coalesce(payment_record.start_date, confirmation_date),
    confirmation_date
  );

  if payment_record.months is not null and payment_record.months > 0 then
    calculated_end_date := (
      effective_start_date + make_interval(months => payment_record.months)
    )::date;
  else
    calculated_end_date := effective_start_date
      + greatest(
          coalesce(payment_record.end_date - payment_record.start_date, 0),
          0
        );
  end if;

  update public.payments
  set
    payment_status = 'completed',
    confirmed_by = actor,
    confirmed_at = now(),
    start_date = effective_start_date,
    end_date = calculated_end_date
  where id = payment_record.id;

  insert into public.logs(
    table_name, record_id, action, old_value, new_value,
    old_data, new_data, created_by, created_at
  )
  values(
    'payments',
    payment_record.id,
    'confirm_payment',
    jsonb_build_object(
      'payment_status', payment_record.payment_status,
      'start_date', payment_record.start_date,
      'end_date', payment_record.end_date
    ),
    jsonb_build_object(
      'payment_status', 'completed',
      'confirmed_by', actor,
      'confirmed_at', now(),
      'start_date', effective_start_date,
      'end_date', calculated_end_date
    ),
    jsonb_build_object(
      'payment_status', payment_record.payment_status,
      'start_date', payment_record.start_date,
      'end_date', payment_record.end_date
    ),
    jsonb_build_object(
      'payment_status', 'completed',
      'confirmed_by', actor,
      'confirmed_at', now(),
      'start_date', effective_start_date,
      'end_date', calculated_end_date
    ),
    actor,
    now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.confirm_crm_payment_from_payos(payment_id_input bigint, reason_input text DEFAULT 'PayOS paid'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  package_record public.business_types%rowtype;
  confirmation_timestamp timestamptz := pg_catalog.now();
  confirmation_date date := (pg_catalog.now() at time zone 'Asia/Ho_Chi_Minh')::date;
  effective_start_date date;
  calculated_end_date date;
  expected_total numeric;
begin
  select * into payment_record from public.payments where id = payment_id_input for update;
  if not found then raise exception 'Không tìm thấy thanh toán.'; end if;
  if lower(payment_record.payment_status) <> 'pending' then raise exception 'Chỉ thanh toán Pending mới được xác nhận.'; end if;
  if payment_record.transaction_type <> 'standard' then raise exception 'Giao dịch điều chỉnh không dùng xác nhận PayOS.'; end if;
  before_record := payment_record;

  select * into customer_record from public.customers where id = payment_record.customer_id for update;
  if not found then raise exception 'Khách hàng của thanh toán không tồn tại.'; end if;
  select * into kiosk_record from public.kiosks where id = payment_record.kiosk_id for update;
  if not found then raise exception 'Kiosk của thanh toán không tồn tại.'; end if;
  if kiosk_record.customer_id <> customer_record.id then raise exception 'Kiosk không thuộc khách hàng của thanh toán.'; end if;
  select * into package_record from public.business_types where id = kiosk_record.business_type_id and is_active = true;
  if not found then raise exception 'Gói dịch vụ không tồn tại hoặc đã ngừng hoạt động.'; end if;
  if payment_record.months is null or payment_record.months < 1 then raise exception 'Số tháng thanh toán không hợp lệ.'; end if;
  if payment_record.price_per_month is null or payment_record.price_per_month < 0
    or payment_record.discount is null or payment_record.discount < 0
    or payment_record.total_amount is null or payment_record.total_amount <= 0 then
    raise exception 'Giá trị tài chính của thanh toán không hợp lệ.';
  end if;
  expected_total := payment_record.price_per_month * payment_record.months - payment_record.discount;
  if payment_record.total_amount <> expected_total then raise exception 'Tổng tiền không khớp giá, số tháng và giảm giá.'; end if;

  effective_start_date := case
    when kiosk_record.end_date is not null and kiosk_record.end_date >= confirmation_date
      then kiosk_record.end_date + 1
    else confirmation_date
  end;
  calculated_end_date := (
    effective_start_date
    + pg_catalog.make_interval(months => payment_record.months + payment_record.bonus_months)
    - interval '1 day'
  )::date;

  perform pg_catalog.set_config('app.payment_workflow_action', 'confirm', true);
  update public.payments
  set payment_status = 'completed', confirmed_by = auth.uid()::text, confirmed_at = confirmation_timestamp,
      start_date = effective_start_date, end_date = calculated_end_date
  where id = payment_record.id
  returning * into payment_record;

  update public.kiosks
  set status = 'active', start_date=coalesce(start_date,effective_start_date), end_date = calculated_end_date
  where id = kiosk_record.id;

  update public.customers
  set status = case when lower(coalesce(status, '')) = 'pending' then 'active' else status end,
      total_kiosks = (select count(*) from public.kiosks k where k.customer_id = customer_record.id)
  where id = customer_record.id;

  perform private.write_ttc_audit(
    'Payment', case when payment_record.payment_intent_key like '%renewal:%' then 'renewal_paid' else 'confirm_payos' end, 'payments', payment_record.id::text,
    to_jsonb(before_record), to_jsonb(payment_record)||jsonb_build_object('kiosk_name',kiosk_record.facebook_name,'old_expiry_date',kiosk_record.end_date), reason_input
  );
  return jsonb_build_object(
    'payment', to_jsonb(payment_record),
    'kiosk', (select to_jsonb(k) from public.kiosks k where k.id = kiosk_record.id),
    'customer', (select to_jsonb(c) from public.customers c where c.id = customer_record.id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.confirm_registration_batch_from_payos(payment_id_input bigint, reason_input text DEFAULT 'PayOS paid'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payment_record public.payments%rowtype; batch_record public.registration_batches%rowtype; item_record record; confirmation_timestamp timestamptz:=pg_catalog.now(); confirmation_date date:=(pg_catalog.now() at time zone 'Asia/Ho_Chi_Minh')::date; calculated_end date; item_count integer:=0;
begin
  select * into payment_record from public.payments where id=payment_id_input for update;
  if not found or payment_record.registration_batch_id is null then raise exception 'Không tìm thấy thanh toán lô đăng ký.' using errcode='P0002'; end if;
  select * into batch_record from public.registration_batches where id=payment_record.registration_batch_id for update;
  if not found or batch_record.payment_id<>payment_record.id then raise exception 'Liên kết thanh toán lô đăng ký không hợp lệ.' using errcode='22023'; end if;
  if payment_record.payment_status<>'pending' or batch_record.status<>'pending' then raise exception 'Lô đăng ký không còn Pending.' using errcode='22023'; end if;
  if payment_record.total_amount<>batch_record.total_amount or batch_record.total_amount<>(select coalesce(sum(total_amount),0) from public.registration_batch_items where batch_id=batch_record.id) then raise exception 'Tổng tiền lô đăng ký không khớp.' using errcode='22023'; end if;
  perform 1 from public.registration_batch_items i join public.kiosks k on k.id=i.kiosk_id join public.registration_requests r on r.id=i.registration_request_id where i.batch_id=batch_record.id order by i.id for update of i,k,r;
  if exists(select 1 from public.registration_batch_items i join public.registration_requests r on r.id=i.registration_request_id where i.batch_id=batch_record.id and r.status not in ('pending','awaiting_payment')) then raise exception 'Hồ sơ đăng ký đã bị đóng.' using errcode='22023'; end if;
  for item_record in select i.*,k.facebook_name from public.registration_batch_items i join public.kiosks k on k.id=i.kiosk_id where i.batch_id=batch_record.id order by i.id loop
    calculated_end:=(confirmation_date+pg_catalog.make_interval(months=>item_record.effective_service_months)-interval '1 day')::date;
    update public.registration_batch_items set start_date=confirmation_date,end_date=calculated_end where id=item_record.id;
    update public.kiosks set status='active',start_date=confirmation_date,end_date=calculated_end where id=item_record.kiosk_id;
    update public.registration_requests set status='approved',requested_start_date=confirmation_date,requested_end_date=calculated_end,reviewed_at=coalesce(reviewed_at,confirmation_timestamp) where id=item_record.registration_request_id;
    item_count:=item_count+1;
  end loop;
  if item_count<1 then raise exception 'Lô đăng ký không có Kiosk.' using errcode='22023'; end if;
  perform pg_catalog.set_config('app.payment_workflow_action','confirm',true);
  update public.payments set payment_status='completed',confirmed_by=null,confirmed_at=confirmation_timestamp where id=payment_record.id returning * into payment_record;
  update public.registration_batches set status='approved',approved_at=confirmation_timestamp,updated_at=confirmation_timestamp where id=batch_record.id returning * into batch_record;
  update public.customers set status=case when pg_catalog.lower(coalesce(status,''))='pending' then 'active' else status end,total_kiosks=(select count(*) from public.kiosks k where k.customer_id=batch_record.customer_id) where id=batch_record.customer_id;
  perform private.write_ttc_audit('Payment','confirm_payos_batch','registration_batches',batch_record.id::text,null,jsonb_build_object('payment_id',payment_record.id,'amount',payment_record.total_amount,'kiosk_count',item_count,'kiosk_name',(select string_agg(k.facebook_name,', ' order by i.id) from public.registration_batch_items i join public.kiosks k on k.id=i.kiosk_id where i.batch_id=batch_record.id)),reason_input);
  return jsonb_build_object('payment',to_jsonb(payment_record),'batch',to_jsonb(batch_record),'items',(select jsonb_agg(jsonb_build_object('id',k.id,'name',k.facebook_name,'startDate',i.start_date,'endDate',i.end_date,'status',k.status) order by i.id) from public.registration_batch_items i join public.kiosks k on k.id=i.kiosk_id where i.batch_id=batch_record.id));
end;$function$

CREATE OR REPLACE FUNCTION private.ensure_wallet(wallet_user_id_input uuid)
 RETURNS wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  wallet_record public.wallets%rowtype;
begin
  insert into public.wallets(user_id)
  values (wallet_user_id_input)
  on conflict (user_id) do nothing;

  select *
  into wallet_record
  from public.wallets
  where user_id = wallet_user_id_input
  for update;

  if not found then
    raise exception 'Không tìm thấy ví xu.' using errcode = '23503';
  end if;

  return wallet_record;
end;
$function$

CREATE OR REPLACE FUNCTION private.evaluate_registration_promotion(promotion_code_input text, customer_id_input bigint, items_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_code text := pg_catalog.upper(pg_catalog.btrim(coalesce(promotion_code_input, '')));
  promotion_record public.promotions%rowtype;
  item jsonb;
  subtotal bigint := 0;
  eligible_total bigint := 0;
  discount_total bigint := 0;
  kiosk_count integer := 0;
  total_bonus integer := 0;
  eligible boolean;
  item_total bigint;
  item_months integer;
  evaluated_items jsonb := '[]'::jsonb;
begin
  if pg_catalog.jsonb_typeof(items_input) <> 'array' then
    raise exception 'Danh sách Kiosk không hợp lệ.' using errcode = '22023';
  end if;

  for item in select value from pg_catalog.jsonb_array_elements(items_input) loop
    item_total := coalesce((item->>'totalAmount')::numeric::bigint, 0);
    if item_total < 0 then
      raise exception 'Giá trị Kiosk không hợp lệ.' using errcode = '22023';
    end if;
    subtotal := subtotal + item_total;
    kiosk_count := kiosk_count + 1;
  end loop;

  if normalized_code = '' then
    return pg_catalog.jsonb_build_object(
      'valid', true,
      'code', null,
      'subtotal', subtotal,
      'eligibleSubtotal', 0,
      'discountAmount', 0,
      'finalAmount', subtotal,
      'items', items_input,
      'message', ''
    );
  end if;

  select * into promotion_record
  from public.promotions
  where code = normalized_code;

  if not found then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã giảm giá không tồn tại.');
  end if;
  if not promotion_record.is_active then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã giảm giá đang tạm ngưng.');
  end if;
  if promotion_record.starts_at is not null and pg_catalog.now() < promotion_record.starts_at then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã này chưa bắt đầu.');
  end if;
  if promotion_record.ends_at is not null and pg_catalog.now() > promotion_record.ends_at then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã giảm giá đã hết hạn.');
  end if;
  if promotion_record.minimum_order_amount is not null and subtotal < promotion_record.minimum_order_amount then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Đơn hàng chưa đạt giá trị tối thiểu.');
  end if;
  if promotion_record.minimum_kiosk_count is not null and kiosk_count < promotion_record.minimum_kiosk_count then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã này yêu cầu đăng ký ít nhất ' || promotion_record.minimum_kiosk_count || ' Kiosk.');
  end if;
  if promotion_record.usage_limit_total is not null
    and (select pg_catalog.count(*) from public.promotion_usages u where u.promotion_id = promotion_record.id) >= promotion_record.usage_limit_total then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã đã hết lượt sử dụng.');
  end if;
  if customer_id_input is not null
    and promotion_record.usage_limit_per_customer is not null
    and (
      select pg_catalog.count(*)
      from public.promotion_usages u
      where u.promotion_id = promotion_record.id
        and u.customer_id = customer_id_input
    ) >= promotion_record.usage_limit_per_customer then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Bạn đã sử dụng hết số lượt của mã này.');
  end if;

  for item in select value from pg_catalog.jsonb_array_elements(items_input) loop
    item_total := coalesce((item->>'totalAmount')::numeric::bigint, 0);
    item_months := coalesce((item->>'months')::integer, 0);
    eligible := (promotion_record.minimum_months is null or item_months >= promotion_record.minimum_months)
      and (
        promotion_record.scope_type = 'all'
        or (
          promotion_record.scope_type = 'category'
          and exists (
            select 1 from public.promotion_categories s
            where s.promotion_id = promotion_record.id
              and s.category_id = (item->>'categoryId')::bigint
          )
        )
        or (
          promotion_record.scope_type = 'business_type'
          and exists (
            select 1 from public.promotion_business_types s
            where s.promotion_id = promotion_record.id
              and s.business_type_id = (item->>'businessTypeId')::bigint
          )
        )
      );
    if eligible then
      eligible_total := eligible_total + item_total;
    end if;
    evaluated_items := evaluated_items || pg_catalog.jsonb_build_array(
      item || pg_catalog.jsonb_build_object(
        'eligible', eligible,
        'bonusMonths', case when eligible and promotion_record.discount_type = 'bonus_months' then promotion_record.discount_value else 0 end,
        'effectiveMonths', item_months + case when eligible and promotion_record.discount_type = 'bonus_months' then promotion_record.discount_value else 0 end
      )
    );
    if eligible and promotion_record.discount_type = 'bonus_months' then
      total_bonus := total_bonus + promotion_record.discount_value;
    end if;
  end loop;

  if eligible_total = 0 then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã chỉ áp dụng cho một số ngành nghề hoặc thời hạn đăng ký.');
  end if;
  if promotion_record.discount_type = 'percentage' then
    discount_total := pg_catalog.floor(eligible_total * promotion_record.discount_value / 100.0)::bigint;
    if promotion_record.max_discount_amount is not null then
      discount_total := least(discount_total, promotion_record.max_discount_amount);
    end if;
  elsif promotion_record.discount_type = 'fixed_amount' then
    discount_total := least(eligible_total, promotion_record.discount_value);
  end if;
  if subtotal - discount_total <= 0 then
    return pg_catalog.jsonb_build_object('valid', false, 'code', normalized_code, 'message', 'Mã làm tổng thanh toán bằng 0 và chưa được hỗ trợ.');
  end if;

  return pg_catalog.jsonb_build_object(
    'valid', true,
    'code', normalized_code,
    'promotionId', promotion_record.id,
    'discountType', promotion_record.discount_type,
    'discountValue', promotion_record.discount_value,
    'subtotal', subtotal,
    'eligibleSubtotal', eligible_total,
    'discountAmount', discount_total,
    'finalAmount', subtotal - discount_total,
    'totalBonusMonths', total_bonus,
    'items', evaluated_items,
    'message', 'Áp dụng mã ' || normalized_code || ' thành công.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.expense_employee_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare person public.employees%rowtype;
begin
  if tg_op='UPDATE' and new.employee_id is not distinct from old.employee_id then
    new.employee_name_snapshot:=old.employee_name_snapshot;
    return new;
  end if;
  if new.employee_id is null then new.employee_name_snapshot:=null; return new; end if;
  select * into person from public.employees where id=new.employee_id for share;
  if person.id is null or person.archived_at is not null or person.employment_status<>'active' then
    raise exception 'Chỉ chọn nhân viên đang làm và chưa lưu trữ cho liên kết mới.';
  end if;
  new.employee_name_snapshot:=person.full_name;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.finalize_registration_promotion_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare batch_record public.registration_batches%rowtype; promotion_record public.promotions%rowtype;
begin
  if new.payment_status <> 'completed' or old.payment_status = 'completed' or new.registration_batch_id is null then return new; end if;
  select * into batch_record from public.registration_batches where id=new.registration_batch_id for update;
  if batch_record.promotion_id is null then return new; end if;
  select * into promotion_record from public.promotions where id=batch_record.promotion_id for update;
  if promotion_record.usage_limit_total is not null and (select count(*) from public.promotion_usages where promotion_id=promotion_record.id) >= promotion_record.usage_limit_total then raise exception 'Mã đã hết lượt sử dụng.' using errcode='P0001'; end if;
  if promotion_record.usage_limit_per_customer is not null and (select count(*) from public.promotion_usages where promotion_id=promotion_record.id and customer_id=batch_record.customer_id) >= promotion_record.usage_limit_per_customer then raise exception 'Khách hàng đã hết lượt sử dụng mã.' using errcode='P0001'; end if;
  insert into public.promotion_usages(promotion_id,customer_id,registration_batch_id,payment_id,code_snapshot,discount_type_snapshot,discount_value_snapshot,subtotal_before_discount,eligible_subtotal,discount_amount,final_amount,total_bonus_months)
  values(promotion_record.id,batch_record.customer_id,batch_record.id,new.id,batch_record.promotion_code,batch_record.promotion_snapshot->>'discountType',(batch_record.promotion_snapshot->>'discountValue')::bigint,batch_record.subtotal_before_discount,batch_record.eligible_subtotal,batch_record.discount_amount,batch_record.total_amount,coalesce((batch_record.promotion_snapshot->>'totalBonusMonths')::integer,0)) on conflict (registration_batch_id) do nothing;
  return new;
end;$function$

CREATE OR REPLACE FUNCTION private.finalize_renewal_promotion_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare promo public.promotions%rowtype; s jsonb:=new.promotion_snapshot;
begin
 if new.payment_status<>'completed' or old.payment_status='completed' or new.registration_batch_id is not null or s->>'promotionId' is null then return new; end if;
 select * into promo from public.promotions where id=(s->>'promotionId')::bigint for update;
 if not found then raise exception 'Không tìm thấy mã ưu đãi đã chốt.'; end if;
 if promo.usage_limit_total is not null and (select count(*) from public.promotion_usages where promotion_id=promo.id)>=promo.usage_limit_total then raise exception 'Mã đã hết lượt sử dụng.'; end if;
 if promo.usage_limit_per_customer is not null and (select count(*) from public.promotion_usages where promotion_id=promo.id and customer_id=new.customer_id)>=promo.usage_limit_per_customer then raise exception 'Khách hàng đã hết lượt mã.'; end if;
 insert into public.promotion_usages(promotion_id,customer_id,payment_id,code_snapshot,discount_type_snapshot,discount_value_snapshot,subtotal_before_discount,eligible_subtotal,discount_amount,final_amount,total_bonus_months)
 values(promo.id,new.customer_id,new.id,s->>'code',s->>'discountType',(s->>'discountValue')::bigint,(s->>'subtotal')::bigint,(s->>'eligibleSubtotal')::bigint,new.discount,new.total_amount,new.bonus_months)
 on conflict(payment_id) do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.mark_payos_review(order_id_input bigint, reason_input text, event_id_input bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.payos_orders%rowtype;
begin
  update public.payos_orders set reconciliation_required=true,reconciliation_reason=reason_input,updated_at=now()
  where id=order_id_input and not reconciliation_required returning * into o;
  if found then
    perform private.write_ttc_audit('Payment','payment_review_required','payos_orders',o.id::text,null,
      jsonb_build_object('payment_id',o.payment_id,'order_code',o.order_code,'amount',o.amount,'review_reason',reason_input),
      'Giao dịch PayOS cần đối soát; chưa tự động kích hoạt hoặc gia hạn');
  end if;
  if event_id_input is not null then
    update public.payos_webhook_events set status='failed',error=reason_input,processed_at=now() where id=event_id_input;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.materialize_registration_checkout_v3(request_ids_input bigint[], phone_input text, promotion_code_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_phone text := pg_catalog.regexp_replace(coalesce(phone_input, ''), '[^0-9+]', '', 'g');
  normalized_code text := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(promotion_code_input, ''))), '');
  request_count integer;
  request_record public.registration_requests%rowtype;
  batch_record public.registration_batches%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  package_record public.business_types%rowtype;
  payment_record public.payments%rowtype;
  first_kiosk_id bigint;
  authoritative_total numeric := 0;
  item_total numeric;
  group_member_base_url text;
  result_items jsonb := '[]'::jsonb;
  evaluation_items jsonb := '[]'::jsonb;
  evaluation jsonb;
  batch_key text;
begin
  request_count := coalesce(pg_catalog.array_length(request_ids_input, 1), 0);
  if request_count < 1 or request_count > 20 then
    raise exception 'Lô đăng ký phải có từ 1 đến 20 Kiosk.' using errcode = '22023';
  end if;
  if normalized_phone = '' then
    raise exception 'Số điện thoại xác nhận không hợp lệ.' using errcode = '22023';
  end if;
  if (
    select pg_catalog.count(distinct value)
    from pg_catalog.unnest(request_ids_input) value
  ) <> request_count then
    raise exception 'Danh sách yêu cầu đăng ký bị trùng.' using errcode = '22023';
  end if;

  -- Serialize customer matching across different registration batches too.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('registration-phone:'||normalized_phone,0));
  batch_key := 'registration-checkout-v3:' || (
    select pg_catalog.string_agg(value::text, ',' order by value)
    from pg_catalog.unnest(request_ids_input) value
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(batch_key, 0));

  perform 1
  from public.registration_requests
  where id = any(request_ids_input)
  order by id
  for update;

  select pg_catalog.count(*)
  into request_count
  from public.registration_requests
  where id = any(request_ids_input);

  if request_count <> pg_catalog.array_length(request_ids_input, 1) then
    raise exception 'Không tìm thấy đầy đủ yêu cầu đăng ký.' using errcode = 'P0002';
  end if;
  if exists (
    select 1
    from public.registration_requests
    where id = any(request_ids_input)
      and pg_catalog.regexp_replace(coalesce(phone, ''), '[^0-9+]', '', 'g') <> normalized_phone
  ) then
    raise exception 'Số điện thoại không khớp lô đăng ký.' using errcode = '42501';
  end if;
  if exists (
    select 1
    from public.registration_requests
    where id = any(request_ids_input)
      and status <> 'awaiting_payment'
  ) then
    raise exception 'Lô đăng ký không còn ở trạng thái chờ thanh toán.' using errcode = '22023';
  end if;

  select b.*
  into batch_record
  from public.registration_batches b
  join public.registration_requests r on r.registration_batch_id = b.id
  where r.id = any(request_ids_input)
  order by b.id
  limit 1
  for update of b;

  if found then
    if exists (
      select 1
      from public.registration_requests
      where id = any(request_ids_input)
        and registration_batch_id is distinct from batch_record.id
    ) then
      raise exception 'Yêu cầu đã thuộc lô đăng ký khác.' using errcode = '23505';
    end if;
    if batch_record.status <> 'pending' then
      raise exception 'Lô đăng ký không còn chờ thanh toán.' using errcode = '22023';
    end if;
    select *
    into payment_record
    from public.payments
    where id = batch_record.payment_id
    for update;
    if not found or payment_record.payment_status <> 'pending' then
      raise exception 'Thanh toán đăng ký không còn chờ xử lý.' using errcode = '22023';
    end if;
    if batch_record.promotion_snapshot is null
      or batch_record.promotion_code is distinct from normalized_code then
      raise exception 'Mã ưu đãi của lô thanh toán đã được khóa.' using errcode = '22023';
    end if;
    return pg_catalog.jsonb_build_object(
      'batch', pg_catalog.to_jsonb(batch_record),
      'payment', pg_catalog.to_jsonb(payment_record),
      'promotion', batch_record.promotion_snapshot,
      'items', (
        select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'requestId', i.registration_request_id,
          'kioskId', i.kiosk_id,
          'name', k.facebook_name,
          'months', i.months,
          'paidMonths', i.paid_months,
          'bonusMonths', i.bonus_months,
          'effectiveMonths', i.effective_service_months,
          'pricePerMonth', i.price_per_month,
          'discount', i.discount,
          'totalAmount', i.total_amount,
          'promotionEligible', i.promotion_eligible
        ) order by i.id), '[]'::jsonb)
        from public.registration_batch_items i
        join public.kiosks k on k.id = i.kiosk_id
        where i.batch_id = batch_record.id
      ),
      'reused', true
    );
  end if;

  select *
  into customer_record
  from public.customers
  where pg_catalog.regexp_replace(coalesce(phone, ''), '[^0-9+]', '', 'g') = normalized_phone
  order by id
  limit 1
  for update;

  if not found then
    select *
    into request_record
    from public.registration_requests
    where id = any(request_ids_input)
    order by id
    limit 1;
    insert into public.customers(
      facebook_name, facebook_id, facebook_link, phone, address,
      status, total_kiosks, total_paid, note
    ) values (
      request_record.facebook_name,
      nullif(request_record.facebook_id, ''),
      request_record.facebook_link,
      request_record.phone,
      request_record.address,
      'pending', 0, 0, request_record.note
    ) returning * into customer_record;
  end if;

  insert into public.registration_batches(customer_id, phone, status, total_amount)
  values (customer_record.id, normalized_phone, 'pending', 0)
  returning * into batch_record;

  select case
    when nullif(pg_catalog.btrim(s.value), '') ~ '^[0-9]+$'
      then 'https://www.facebook.com/groups/' || pg_catalog.btrim(s.value) || '/user/'
    else null
  end
  into group_member_base_url
  from public.settings s
  where s.key = 'facebook_group_id';

  for request_record in
    select *
    from public.registration_requests
    where id = any(request_ids_input)
    order by id
    for update
  loop
    select *
    into package_record
    from public.business_types
    where id = request_record.business_type_id
      and is_active = true
    for share;

    if not found or package_record.price_per_month is null or package_record.price_per_month < 0 then
      raise exception 'Loại hình kinh doanh không tồn tại, không hoạt động hoặc thiếu giá.' using errcode = '22023';
    end if;
    if request_record.months is null
      or request_record.months < 1
      or coalesce(request_record.discount, 0) <> 0 then
      raise exception 'Thời hạn không hợp lệ hoặc đăng ký công khai chứa giảm giá không được phép.' using errcode = '22023';
    end if;

    item_total := package_record.price_per_month * request_record.months;
    if item_total <= 0 or request_record.total_amount is distinct from item_total then
      raise exception 'Tổng tiền Kiosk không khớp giá hiện hành.' using errcode = '22023';
    end if;

    if request_record.kiosk_id is not null then
      select * into kiosk_record
      from public.kiosks
      where id = request_record.kiosk_id
      for update;
    else
      kiosk_record := null;
    end if;

    if kiosk_record.id is null then
      insert into public.kiosks(
        customer_id, facebook_name, facebook_id, facebook_link, facebook_group_link,
        category_id, business_type_id, service_name, start_date, end_date,
        status, auto_approve, total_paid, kiosk_total_paid, last_payment_date,
        note, is_primary
      ) values (
        customer_record.id,
        request_record.facebook_name,
        nullif(request_record.facebook_id, ''),
        request_record.facebook_link,
        case
          when group_member_base_url is null or nullif(request_record.facebook_id, '') is null then null
          else group_member_base_url || request_record.facebook_id || '/'
        end,
        package_record.category_id,
        package_record.id,
        package_record.name,
        null, null, 'pending', false, 0, 0, null,
        request_record.note,
        not exists (
          select 1 from public.kiosks k
          where k.customer_id = customer_record.id and k.is_primary
        )
      ) returning * into kiosk_record;
    elsif kiosk_record.customer_id <> customer_record.id then
      raise exception 'Kiosk không thuộc khách hàng của lô đăng ký.' using errcode = '23505';
    end if;

    first_kiosk_id := coalesce(first_kiosk_id, kiosk_record.id);

    insert into public.registration_batch_items(
      batch_id, registration_request_id, kiosk_id, business_type_id,
      months, paid_months, bonus_months, effective_service_months,
      price_per_month, discount, total_amount, promotion_eligible
    ) values (
      batch_record.id, request_record.id, kiosk_record.id, package_record.id,
      request_record.months, request_record.months, 0, request_record.months,
      package_record.price_per_month, 0, item_total, false
    );

    update public.registration_requests
    set customer_id = customer_record.id,
        kiosk_id = kiosk_record.id,
        registration_batch_id = batch_record.id,
        metadata = coalesce(metadata, '{}'::jsonb) || pg_catalog.jsonb_build_object(
          'materialized_for_checkout_v3_at', pg_catalog.now(),
          'promotion_code', normalized_code
        )
    where id = request_record.id;

    authoritative_total := authoritative_total + item_total;
  end loop;

  if authoritative_total <= 0 then
    raise exception 'Tổng tiền lô đăng ký không hợp lệ.' using errcode = '22023';
  end if;

  insert into public.payments(
    customer_id, kiosk_id, start_date, end_date, months, price_per_month,
    discount, total_amount, payment_method, payment_status, transaction_type,
    note, payment_intent_key, registration_batch_id
  ) values (
    customer_record.id, first_kiosk_id, null, null, 1, authoritative_total,
    0, authoritative_total, 'transfer', 'pending', 'standard',
    'Public registration checkout v3 batch #' || batch_record.id,
    'registration-batch:' || batch_record.id,
    batch_record.id
  ) returning * into payment_record;

  update public.registration_batches
  set payment_id = payment_record.id,
      total_amount = authoritative_total,
      updated_at = pg_catalog.now()
  where id = batch_record.id
  returning * into batch_record;

  update public.registration_requests
  set payment_id = payment_record.id
  where registration_batch_id = batch_record.id;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'itemId', i.id,
    'kioskId', i.kiosk_id,
    'months', i.months,
    'totalAmount', i.total_amount,
    'businessTypeId', i.business_type_id,
    'categoryId', bt.category_id
  ) order by i.id)
  into evaluation_items
  from public.registration_batch_items i
  join public.business_types bt on bt.id = i.business_type_id
  where i.batch_id = batch_record.id;

  evaluation := private.evaluate_registration_promotion(
    normalized_code,
    customer_record.id,
    evaluation_items
  );
  if not coalesce((evaluation->>'valid')::boolean, false) then
    raise exception '%', evaluation->>'message' using errcode = 'P0001';
  end if;

  update public.registration_batches
  set promotion_id = nullif(evaluation->>'promotionId', '')::bigint,
      promotion_code = evaluation->>'code',
      promotion_snapshot = evaluation,
      subtotal_before_discount = (evaluation->>'subtotal')::bigint,
      eligible_subtotal = (evaluation->>'eligibleSubtotal')::bigint,
      discount_amount = (evaluation->>'discountAmount')::bigint,
      total_amount = (evaluation->>'finalAmount')::bigint,
      updated_at = pg_catalog.now()
  where id = batch_record.id
  returning * into batch_record;

  perform pg_catalog.set_config('app.payment_workflow_action', 'edit', true);
  update public.payments
  set price_per_month = (evaluation->>'subtotal')::bigint,
      discount = (evaluation->>'discountAmount')::bigint,
      discount_reason = case when normalized_code is null then null else 'Promotion ' || normalized_code end,
      total_amount = (evaluation->>'finalAmount')::bigint
  where id = payment_record.id
  returning * into payment_record;

  update public.registration_batch_items i
  set promotion_eligible = coalesce((x.value->>'eligible')::boolean, false),
      bonus_months = coalesce((x.value->>'bonusMonths')::integer, 0),
      effective_service_months = coalesce((x.value->>'effectiveMonths')::integer, i.months)
  from pg_catalog.jsonb_array_elements(evaluation->'items') x
  where i.id = (x.value->>'itemId')::bigint;

  if (evaluation->>'discountAmount')::bigint > 0 then
    with eligible_items as (
      select i.id,
        i.total_amount,
        pg_catalog.floor(
          (evaluation->>'discountAmount')::numeric * i.total_amount
          / (evaluation->>'eligibleSubtotal')::numeric
        )::bigint as base_discount
      from public.registration_batch_items i
      where i.batch_id = batch_record.id and i.promotion_eligible
    ), ranked as (
      select e.*,
        pg_catalog.row_number() over (order by e.id) as allocation_rank,
        (evaluation->>'discountAmount')::bigint
          - pg_catalog.sum(e.base_discount) over () as remainder
      from eligible_items e
    )
    update public.registration_batch_items i
    set discount = r.base_discount + case when r.allocation_rank <= r.remainder then 1 else 0 end,
        total_amount = i.total_amount - (
          r.base_discount + case when r.allocation_rank <= r.remainder then 1 else 0 end
        )
    from ranked r
    where i.id = r.id;
  end if;

  if batch_record.total_amount is distinct from (
    select coalesce(pg_catalog.sum(i.total_amount), 0)
    from public.registration_batch_items i
    where i.batch_id = batch_record.id
  ) then
    raise exception 'Phân bổ ưu đãi không khớp tổng thanh toán.' using errcode = '23514';
  end if;

  update public.customers c
  set total_kiosks = (
    select pg_catalog.count(*) from public.kiosks k where k.customer_id = c.id
  )
  where c.id = customer_record.id;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'requestId', i.registration_request_id,
    'kioskId', i.kiosk_id,
    'name', k.facebook_name,
    'months', i.months,
    'paidMonths', i.paid_months,
    'bonusMonths', i.bonus_months,
    'effectiveMonths', i.effective_service_months,
    'pricePerMonth', i.price_per_month,
    'discount', i.discount,
    'totalAmount', i.total_amount,
    'promotionEligible', i.promotion_eligible
  ) order by i.id), '[]'::jsonb)
  into result_items
  from public.registration_batch_items i
  join public.kiosks k on k.id = i.kiosk_id
  where i.batch_id = batch_record.id;

  perform private.write_ttc_audit('Registration','registration_pending','registration_batches',batch_record.id::text,null,pg_catalog.jsonb_build_object('payment_id',payment_record.id,'kiosk_name',(select string_agg(k.facebook_name,', ' order by i.id) from public.registration_batch_items i join public.kiosks k on k.id=i.kiosk_id where i.batch_id=batch_record.id),'amount',payment_record.total_amount,'kiosk_count',request_count),'Đăng ký Kiosk – Chờ thanh toán');
  return pg_catalog.jsonb_build_object(
    'batch', pg_catalog.to_jsonb(batch_record),
    'payment', pg_catalog.to_jsonb(payment_record),
    'promotion', evaluation,
    'items', result_items,
    'reused', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.normalize_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  resolved_actor public.user_roles%rowtype;
  request_actor_id uuid := auth.uid();
begin
  if request_actor_id is not null then
    new.actor_id := request_actor_id;
  end if;

  if new.actor_id is not null then
    select *
    into resolved_actor
    from public.user_roles ur
    where ur.user_id = new.actor_id;

    new.actor_type := 'staff';
    new.actor_name := coalesce(
      resolved_actor.display_name,
      resolved_actor.username,
      nullif(trim(new.actor_name), ''),
      'Nhân viên'
    );
    new.actor_role := coalesce(
      resolved_actor.role,
      nullif(trim(new.actor_role), ''),
      'staff'
    );
  elsif lower(coalesce(new.actor_role, '')) in ('anon', 'public')
    or new.actor_type = 'public' then
    new.actor_type := 'public';
    new.actor_name := 'Public User';
    new.actor_role := 'public';
  elsif new.actor_type = 'database_trigger' then
    new.actor_name := 'Database Trigger';
    new.actor_role := 'system';
  else
    new.actor_type := 'system';
    new.actor_name := 'System';
    new.actor_role := 'system';
  end if;

  new.module := coalesce(nullif(trim(new.module), ''), 'System');
  new.entity := coalesce(nullif(trim(new.entity), ''), new.module);
  new.record_id := coalesce(
    nullif(trim(new.record_id), ''),
    new.after->>'id',
    new.before->>'id',
    new.after->'payment'->>'id',
    new.before->'payment'->>'id',
    new.after->>'customer_id',
    new.before->>'customer_id'
  );
  new.action := coalesce(nullif(trim(new.action), ''), 'unknown');
  new.reason := coalesce(nullif(trim(new.reason), ''), 'Không cung cấp lý do');
  new.created_at := coalesce(new.created_at, pg_catalog.now());
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.post_wallet_ledger(wallet_user_id_input uuid, amount_input numeric, transaction_type_input text, related_table_input text DEFAULT NULL::text, related_id_input text DEFAULT NULL::text, idempotency_key_input text DEFAULT NULL::text, description_input text DEFAULT NULL::text, reason_input text DEFAULT NULL::text, metadata_input jsonb DEFAULT '{}'::jsonb, actor_id_input uuid DEFAULT auth.uid(), actor_type_input text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  wallet_record public.wallets%rowtype;
  ledger_record public.wallet_ledger%rowtype;
  normalized_amount numeric(14, 2) := amount_input;
  normalized_key text := nullif(trim(idempotency_key_input), '');
  before_balance numeric(14, 2);
  after_balance numeric(14, 2);
begin
  if wallet_user_id_input is null then
    raise exception 'User ví là bắt buộc.' using errcode = '22023';
  end if;
  if normalized_amount is null or normalized_amount = 0 then
    raise exception 'Số xu giao dịch phải khác 0.' using errcode = '22023';
  end if;
  if transaction_type_input not in (
    'earn_task',
    'spend_campaign',
    'bonus_signup',
    'admin_adjustment',
    'refund_campaign',
    'spend_kiosk',
    'refund_kiosk'
  ) then
    raise exception 'Loại giao dịch ví không hợp lệ.' using errcode = '22023';
  end if;
  if actor_type_input not in ('user', 'staff', 'system') then
    raise exception 'Loại actor ví không hợp lệ.' using errcode = '22023';
  end if;

  if normalized_key is not null then
    select *
    into ledger_record
    from public.wallet_ledger
    where wallet_user_id = wallet_user_id_input
      and idempotency_key = normalized_key;
    if found then
      return jsonb_build_object(
        'wallet', (
          select to_jsonb(w)
          from public.wallets w
          where w.user_id = wallet_user_id_input
        ),
        'ledger', to_jsonb(ledger_record),
        'already_processed', true
      );
    end if;
  end if;

  wallet_record := private.ensure_wallet(wallet_user_id_input);
  before_balance := wallet_record.balance;
  after_balance := before_balance + normalized_amount;
  if after_balance < 0 then
    raise exception 'Số dư xu không đủ.' using errcode = '23514';
  end if;

  update public.wallets
  set
    balance = after_balance,
    total_earned = total_earned + case when normalized_amount > 0 then normalized_amount else 0 end,
    total_spent = total_spent + case when normalized_amount < 0 then abs(normalized_amount) else 0 end,
    updated_at = now()
  where user_id = wallet_user_id_input
  returning * into wallet_record;

  insert into public.wallet_ledger(
    wallet_user_id,
    actor_id,
    actor_type,
    transaction_type,
    amount,
    balance_before,
    balance_after,
    related_table,
    related_id,
    idempotency_key,
    description,
    reason,
    metadata
  )
  values(
    wallet_user_id_input,
    actor_id_input,
    actor_type_input,
    transaction_type_input,
    normalized_amount,
    before_balance,
    after_balance,
    nullif(trim(related_table_input), ''),
    nullif(trim(related_id_input), ''),
    normalized_key,
    nullif(trim(description_input), ''),
    nullif(trim(reason_input), ''),
    coalesce(metadata_input, '{}'::jsonb)
  )
  returning * into ledger_record;

  perform private.write_ttc_audit(
    'Wallet',
    'post_ledger',
    'wallet_ledger',
    ledger_record.id::text,
    jsonb_build_object('balance', before_balance),
    jsonb_build_object(
      'wallet_user_id', wallet_user_id_input,
      'amount', normalized_amount,
      'balance_after', after_balance,
      'transaction_type', transaction_type_input,
      'related_table', related_table_input,
      'related_id', related_id_input
    ),
    reason_input
  );

  return jsonb_build_object(
    'wallet', to_jsonb(wallet_record),
    'ledger', to_jsonb(ledger_record),
    'already_processed', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_registration_batch_for_payos(request_ids_input bigint[], phone_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_phone text := pg_catalog.regexp_replace(coalesce(phone_input, ''), '[^0-9+]', '', 'g');
  request_count integer;
  request_record public.registration_requests%rowtype;
  batch_record public.registration_batches%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  package_record public.business_types%rowtype;
  payment_record public.payments%rowtype;
  first_kiosk_id bigint;
  authoritative_total numeric := 0;
  item_total numeric;
  group_member_base_url text;
  result_items jsonb := '[]'::jsonb;
  batch_key text;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'Chỉ API server được chuẩn bị thanh toán đăng ký.' using errcode = '42501';
  end if;
  request_count := coalesce(pg_catalog.array_length(request_ids_input, 1), 0);
  if request_count < 1 or request_count > 20 then raise exception 'Lô đăng ký phải có từ 1 đến 20 Kiosk.' using errcode = '22023'; end if;
  if normalized_phone = '' then raise exception 'Số điện thoại xác nhận không hợp lệ.' using errcode = '22023'; end if;
  if (select count(distinct value) from pg_catalog.unnest(request_ids_input) value) <> request_count then
    raise exception 'Danh sách yêu cầu đăng ký bị trùng.' using errcode = '22023';
  end if;
  batch_key := 'registration-batch:' || (select pg_catalog.string_agg(value::text, ',' order by value) from pg_catalog.unnest(request_ids_input) value);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(batch_key, 0));

  perform 1 from public.registration_requests where id = any(request_ids_input) order by id for update;
  select count(*) into request_count from public.registration_requests where id = any(request_ids_input);
  if request_count <> pg_catalog.array_length(request_ids_input, 1) then raise exception 'Không tìm thấy đầy đủ yêu cầu đăng ký.' using errcode = 'P0002'; end if;
  if exists (select 1 from public.registration_requests where id = any(request_ids_input)
    and pg_catalog.regexp_replace(coalesce(phone, ''), '[^0-9+]', '', 'g') <> normalized_phone) then
    raise exception 'Số điện thoại không khớp lô đăng ký.' using errcode = '42501';
  end if;
  if exists (select 1 from public.registration_requests where id = any(request_ids_input)
    and pg_catalog.lower(coalesce(status, 'pending')) not in ('awaiting_payment', 'pending', 'approved')) then
    raise exception 'Lô đăng ký không còn có thể thanh toán.' using errcode = '22023';
  end if;

  select b.* into batch_record from public.registration_batches b
  join public.registration_requests r on r.registration_batch_id = b.id
  where r.id = any(request_ids_input) order by b.id limit 1 for update of b;
  if found then
    if exists (select 1 from public.registration_requests where id = any(request_ids_input)
      and registration_batch_id is distinct from batch_record.id) then
      raise exception 'Yêu cầu đã thuộc lô đăng ký khác.' using errcode = '23505';
    end if;
    select * into payment_record from public.payments where id = batch_record.payment_id for update;
    return jsonb_build_object(
      'batch', to_jsonb(batch_record), 'payment', to_jsonb(payment_record),
      'items', (select coalesce(jsonb_agg(jsonb_build_object(
        'requestId', i.registration_request_id, 'kioskId', i.kiosk_id,
        'name', k.facebook_name, 'months', i.months,
        'pricePerMonth', i.price_per_month, 'discount', i.discount,
        'totalAmount', i.total_amount)), '[]'::jsonb)
        from public.registration_batch_items i join public.kiosks k on k.id = i.kiosk_id
        where i.batch_id = batch_record.id), 'reused', true);
  end if;

  select * into customer_record from public.customers
  where pg_catalog.regexp_replace(coalesce(phone, ''), '[^0-9+]', '', 'g') = normalized_phone
  order by id limit 1 for update;
  if not found then
    select * into request_record from public.registration_requests where id = any(request_ids_input) order by id limit 1;
    insert into public.customers(facebook_name, facebook_id, facebook_link, phone, address, status, total_kiosks, total_paid, note)
    values(request_record.facebook_name, nullif(request_record.facebook_id, ''), request_record.facebook_link,
      request_record.phone, request_record.address, 'pending', 0, 0, request_record.note)
    returning * into customer_record;
  end if;
  insert into public.registration_batches(customer_id, phone, status, total_amount)
  values(customer_record.id, normalized_phone, 'pending', 0) returning * into batch_record;
  select case when nullif(trim(s.value), '') ~ '^[0-9]+$'
    then 'https://www.facebook.com/groups/' || trim(s.value) || '/user/' else null end
  into group_member_base_url from public.settings s where s.key = 'facebook_group_id';

  for request_record in select * from public.registration_requests where id = any(request_ids_input) order by id for update loop
    select * into package_record from public.business_types
    where id = request_record.business_type_id and is_active = true for share;
    if not found or package_record.price_per_month is null or package_record.price_per_month < 0 then
      raise exception 'Loại hình kinh doanh không tồn tại, không hoạt động hoặc thiếu giá.' using errcode = '22023';
    end if;
    if request_record.months is null or request_record.months < 1 or coalesce(request_record.discount, 0) <> 0 then
      raise exception 'Thời hạn không hợp lệ hoặc đăng ký công khai chứa giảm giá không được phép.' using errcode = '22023';
    end if;
    item_total := package_record.price_per_month * request_record.months;
    if item_total <= 0 or request_record.total_amount is distinct from item_total then
      raise exception 'Tổng tiền Kiosk không khớp giá hiện hành.' using errcode = '22023';
    end if;
    if request_record.kiosk_id is not null then
      select * into kiosk_record from public.kiosks where id = request_record.kiosk_id for update;
    else kiosk_record := null;
    end if;
    if kiosk_record.id is null then
      insert into public.kiosks(customer_id, facebook_name, facebook_id, facebook_link, facebook_group_link,
        category_id, business_type_id, service_name, start_date, end_date, status, auto_approve,
        total_paid, kiosk_total_paid, last_payment_date, note, is_primary)
      values(customer_record.id, request_record.facebook_name, nullif(request_record.facebook_id, ''),
        request_record.facebook_link, case when group_member_base_url is null or nullif(request_record.facebook_id, '') is null
          then null else group_member_base_url || request_record.facebook_id || '/' end,
        package_record.category_id, package_record.id, package_record.name, null, null, 'pending', false,
        0, 0, null, request_record.note,
        not exists(select 1 from public.kiosks k where k.customer_id = customer_record.id and k.is_primary))
      returning * into kiosk_record;
    elsif kiosk_record.customer_id <> customer_record.id then
      raise exception 'Kiosk không thuộc khách hàng của lô đăng ký.' using errcode = '23505';
    end if;
    first_kiosk_id := coalesce(first_kiosk_id, kiosk_record.id);
    insert into public.registration_batch_items(
      batch_id, registration_request_id, kiosk_id, business_type_id,
      months, paid_months, bonus_months, effective_service_months,
      price_per_month, discount, total_amount, promotion_eligible
    ) values (
      batch_record.id, request_record.id, kiosk_record.id, package_record.id,
      request_record.months, request_record.months, 0, request_record.months,
      package_record.price_per_month, coalesce(request_record.discount, 0), item_total, false
    );
    update public.registration_requests
    set customer_id = customer_record.id, kiosk_id = kiosk_record.id,
        registration_batch_id = batch_record.id,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('materialized_for_batch_payos_at', pg_catalog.now())
    where id = request_record.id;
    authoritative_total := authoritative_total + item_total;
    result_items := result_items || jsonb_build_array(jsonb_build_object(
      'requestId', request_record.id, 'kioskId', kiosk_record.id, 'name', kiosk_record.facebook_name,
      'months', request_record.months, 'pricePerMonth', package_record.price_per_month,
      'discount', coalesce(request_record.discount, 0), 'totalAmount', item_total));
  end loop;
  if authoritative_total <= 0 then raise exception 'Tổng tiền lô đăng ký không hợp lệ.' using errcode = '22023'; end if;
  insert into public.payments(customer_id, kiosk_id, start_date, end_date, months, price_per_month,
    discount, total_amount, payment_method, payment_status, transaction_type, note,
    payment_intent_key, registration_batch_id)
  values(customer_record.id, first_kiosk_id, null, null, 1, authoritative_total, 0, authoritative_total,
    'transfer', 'pending', 'standard', 'Public registration batch #' || batch_record.id,
    'registration-batch:' || batch_record.id, batch_record.id) returning * into payment_record;
  update public.registration_batches set payment_id = payment_record.id, total_amount = authoritative_total,
    updated_at = pg_catalog.now() where id = batch_record.id returning * into batch_record;
  update public.registration_requests set payment_id = payment_record.id where registration_batch_id = batch_record.id;
  update public.customers c set total_kiosks = (select count(*) from public.kiosks k where k.customer_id = c.id)
  where c.id = customer_record.id;
  return jsonb_build_object('batch', to_jsonb(batch_record), 'payment', to_jsonb(payment_record),
    'items', result_items, 'reused', false);
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_renewal_payment(kiosk_id_input bigint, months_input integer, promotion_code_input text, discount_input numeric, discount_reason_input text, note_input text, public_input boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k public.kiosks%rowtype; bt public.business_types%rowtype; p public.payments%rowtype;
 evaluation jsonb; code_value text:=nullif(upper(btrim(promotion_code_input)),''); discount_value numeric:=coalesce(discount_input,0);
 intent_key text; actor public.user_roles%rowtype;
begin
  if months_input is null or months_input<1 or months_input>120 then raise exception 'Số tháng không hợp lệ.' using errcode='22023'; end if;
  -- All renewal entrypoints share the same kiosk lock before selecting a pending payment.
  perform pg_advisory_xact_lock(hashtextextended('renewal:'||kiosk_id_input::text,0));
  select * into k from public.kiosks where id=kiosk_id_input for update;
  if not found or not exists(select 1 from public.registered_kiosks where id=kiosk_id_input)
    or lower(k.status) not in ('active','warning','expired') then
    raise exception 'Kiosk chưa đủ điều kiện gia hạn.' using errcode='22023';
  end if;
  if code_value is not null and discount_value<>0 then raise exception 'Không cộng dồn mã giảm giá và giảm giá thủ công.' using errcode='22023'; end if;
  select * into p from public.payments where kiosk_id=k.id and payment_status='pending'
    and registration_batch_id is null and registration_request_id is null
    and (payment_intent_key like '%renewal:%' or note='Public PayOS Kiosk renewal') order by id limit 1 for update;
  if found then
    if p.months<>months_input or p.promotion_snapshot->>'code' is distinct from code_value
      or (code_value is null and p.discount<>discount_value) then
      raise exception 'Đã có yêu cầu gia hạn chờ thanh toán với gói hoặc ưu đãi khác. Liên hệ Admin để hủy yêu cầu cũ.' using errcode='P0001';
    end if;
    return jsonb_build_object('payment',to_jsonb(p),'kiosk_name',k.facebook_name,'reused',true);
  end if;
  select * into bt from public.business_types where id=k.business_type_id and is_active;
  if not found or bt.price_per_month<=0 then raise exception 'Giá gia hạn không hợp lệ.' using errcode='22023'; end if;
  evaluation:=private.evaluate_registration_promotion(code_value,k.customer_id,jsonb_build_array(jsonb_build_object(
    'itemId',k.id,'kioskId',k.id,'months',months_input,'totalAmount',bt.price_per_month*months_input,'businessTypeId',bt.id,'categoryId',bt.category_id)));
  if not coalesce((evaluation->>'valid')::boolean,false) then raise exception '%',evaluation->>'message' using errcode='P0001'; end if;
  if code_value is not null then discount_value:=(evaluation->>'discountAmount')::numeric; end if;
  if discount_value<0 or discount_value>=bt.price_per_month*months_input then raise exception 'Giảm giá không hợp lệ.' using errcode='22023'; end if;
  if code_value is null and discount_value>0 and nullif(btrim(discount_reason_input),'') is null then raise exception 'Cần lý do giảm giá.' using errcode='22023'; end if;
  intent_key:=case when public_input then 'public-renewal:' else 'admin-renewal:' end||k.id::text||':'||months_input::text;
  insert into public.payments(customer_id,kiosk_id,months,price_per_month,discount,discount_reason,total_amount,payment_method,payment_status,note,payment_intent_key,promotion_snapshot,bonus_months)
  values(k.customer_id,k.id,months_input,bt.price_per_month,discount_value,case when code_value is null then discount_reason_input else 'Promotion '||code_value end,
    bt.price_per_month*months_input-discount_value,'transfer','pending',case when public_input then 'Public PayOS Kiosk renewal' else note_input end,intent_key,
    evaluation,coalesce((evaluation->>'totalBonusMonths')::integer,0)) returning * into p;
  perform private.write_ttc_audit('Renewal','renewal_pending','payments',p.id::text,null,
    to_jsonb(p)||jsonb_build_object('kiosk_name',k.facebook_name),'Gia hạn Kiosk – Chờ thanh toán');
  return jsonb_build_object('payment',to_jsonb(p),'kiosk_name',k.facebook_name,'reused',false);
end $function$

CREATE OR REPLACE FUNCTION private.prevent_duplicate_pending_registration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  identity_key text;
begin
  identity_key := coalesce(
    nullif(pg_catalog.regexp_replace(coalesce(new.facebook_id, ''), '[^0-9]', '', 'g'), ''),
    pg_catalog.lower(pg_catalog.regexp_replace(coalesce(new.facebook_link, ''), '[?#].*$', ''))
  );
  if identity_key is null or identity_key = '' then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('registration:' || identity_key, 0)
  );

  if exists (
    select 1
    from public.registration_requests r
    where r.id <> coalesce(new.id, 0)
      and new.status in ('pending', 'awaiting_payment')
      and (
        r.status = 'pending'
        or (new.status = 'awaiting_payment' and r.status = 'awaiting_payment')
      )
      and coalesce(
        nullif(pg_catalog.regexp_replace(coalesce(r.facebook_id, ''), '[^0-9]', '', 'g'), ''),
        pg_catalog.lower(pg_catalog.regexp_replace(coalesce(r.facebook_link, ''), '[?#].*$', ''))
      ) = identity_key
  ) then
    raise exception 'Kiosk này đã có yêu cầu đăng ký đang xử lý.' using errcode = '23505';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_payment_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  workflow_action text := coalesce(
    pg_catalog.current_setting('app.payment_workflow_action', true),
    ''
  );
begin
  if tg_op = 'DELETE' then
    raise exception 'Thanh toán không bao giờ được xóa cứng.' using errcode = '23514';
  end if;

  if tg_op = 'INSERT' then
    if pg_catalog.lower(coalesce(new.payment_status, '')) <> 'pending'
      and workflow_action <> 'adjustment' then
      raise exception 'Thanh toán mới phải bắt đầu ở trạng thái Pending.' using errcode = '23514';
    end if;
    return new;
  end if;

  if (new.promotion_snapshot,new.bonus_months) is distinct from (old.promotion_snapshot,old.bonus_months) then
    raise exception 'Ưu đãi đã được chốt theo thanh toán, không được sửa trực tiếp.' using errcode='23514';
  end if;
  if pg_catalog.lower(old.payment_status) = 'completed' then
    if workflow_action = 'historical_correction' then
      -- Future columns are protected by default. Only these four explicitly
      -- audited historical fields may differ inside the dedicated RPC.
      if (
        pg_catalog.to_jsonb(new)
          - array['start_date', 'end_date', 'months', 'total_amount']::text[]
      ) is distinct from (
        pg_catalog.to_jsonb(old)
          - array['start_date', 'end_date', 'months', 'total_amount']::text[]
      ) then
        raise exception 'Sửa dữ liệu lịch sử chỉ được đổi ngày, số tháng và số tiền.'
          using errcode = '42501';
      end if;
      return new;
    end if;

    if new.id is distinct from old.id
      or new.created_at is distinct from old.created_at
      or new.customer_id is distinct from old.customer_id
      or new.kiosk_id is distinct from old.kiosk_id
      or new.start_date is distinct from old.start_date
      or new.end_date is distinct from old.end_date
      or new.months is distinct from old.months
      or new.price_per_month is distinct from old.price_per_month
      or new.discount is distinct from old.discount
      or new.discount_reason is distinct from old.discount_reason
      or new.total_amount is distinct from old.total_amount
      or new.payment_method is distinct from old.payment_method
      or new.payment_status is distinct from old.payment_status
      or new.confirmed_at is distinct from old.confirmed_at
      or new.confirmed_by is distinct from old.confirmed_by
      or new.transaction_type is distinct from old.transaction_type
      or new.adjusts_payment_id is distinct from old.adjusts_payment_id
      or new.adjustment_reason is distinct from old.adjustment_reason
      or new.service_month_delta is distinct from old.service_month_delta then
      raise exception 'Không được sửa trường tài chính của thanh toán Completed. Hãy tạo giao dịch điều chỉnh.'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if pg_catalog.lower(old.payment_status) in ('rejected', 'cancelled') then
    if new is distinct from old then
      raise exception 'Thanh toán Rejected/Cancelled là trạng thái kết thúc.' using errcode = '23514';
    end if;
    return new;
  end if;

  if pg_catalog.lower(old.payment_status) <> 'pending' then
    raise exception 'Trạng thái thanh toán hiện tại không hợp lệ.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'completed' and workflow_action <> 'confirm' then
    raise exception 'Chỉ confirm_payment() được hoàn thành thanh toán.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'rejected' and workflow_action <> 'reject' then
    raise exception 'Chỉ reject_payment() được từ chối thanh toán.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'cancelled' and workflow_action <> 'cancel' then
    raise exception 'Chỉ cancel_payment() được hủy thanh toán.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) not in ('pending', 'completed', 'rejected', 'cancelled') then
    raise exception 'Trạng thái thanh toán không hợp lệ.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'pending'
    and workflow_action <> 'edit'
    and (
      new.customer_id is distinct from old.customer_id
      or new.kiosk_id is distinct from old.kiosk_id
      or new.start_date is distinct from old.start_date
      or new.end_date is distinct from old.end_date
      or new.months is distinct from old.months
      or new.price_per_month is distinct from old.price_per_month
      or new.discount is distinct from old.discount
      or new.discount_reason is distinct from old.discount_reason
      or new.total_amount is distinct from old.total_amount
      or new.payment_method is distinct from old.payment_method
    ) then
    raise exception 'Trường tài chính của thanh toán Pending phải được sửa qua update_pending_payment().'
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.registration_request_payment(request_record registration_requests)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  resolved_payment_id bigint;
  candidate_count integer;
begin
  if request_record.payment_id is not null then
    return request_record.payment_id;
  end if;

  select count(*), min(p.id)
  into candidate_count, resolved_payment_id
  from public.payments p
  where p.kiosk_id = request_record.kiosk_id
    and p.customer_id = request_record.customer_id
    and lower(p.payment_status) = 'pending'
    and coalesce(p.transaction_type, 'standard') = 'standard'
    and (request_record.months is null or p.months = request_record.months)
    and (request_record.total_amount is null or p.total_amount = request_record.total_amount);

  if candidate_count <> 1 then
    raise exception 'Không xác định được duy nhất thanh toán Pending của đơn đăng ký.'
      using errcode = 'P0001';
  end if;

  return resolved_payment_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.reserve_crm_payos_order(payment_id_input bigint, order_code_input bigint, amount_input numeric, description_input text, checkout_url_input text, qr_code_input text, payment_link_id_input text, provider_payload_input jsonb)
 RETURNS payos_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payment_record public.payments%rowtype; order_record public.payos_orders%rowtype; old_order public.payos_orders%rowtype;
declare expiry timestamptz;
begin
  select * into payment_record from public.payments where id=payment_id_input for update;
  if not found or payment_record.payment_status<>'pending' or payment_record.total_amount<>amount_input then raise exception 'Thanh toán Pending không hợp lệ.' using errcode='22023'; end if;
  if exists(select 1 from public.payos_orders where payment_id=payment_id_input and
    (reconciliation_required or (status<>'paid' and provider_payload->'_status'->>'status'='PAID'))) then
    raise exception 'Thanh toán cần đối soát hoặc đang chờ webhook; không tạo thêm mã.' using errcode='P0001';
  end if;
  select * into order_record from public.payos_orders where order_code=order_code_input for update;
  if found then
    if order_record.payment_id is distinct from payment_id_input or order_record.purpose<>'crm_payment' or order_record.amount<>amount_input
      or (order_record.payment_link_id is not null and nullif(payment_link_id_input,'') is not null and order_record.payment_link_id<>payment_link_id_input) then
      raise exception 'Không được đổi liên kết PayOS order.' using errcode='22023';
    end if;
    if order_record.status<>'pending' then return order_record; end if;
    update public.payos_orders set checkout_url=coalesce(nullif(checkout_url_input,''),checkout_url),qr_code=coalesce(nullif(qr_code_input,''),qr_code),
      payment_link_id=coalesce(nullif(payment_link_id_input,''),payment_link_id),provider_payload=provider_payload||coalesce(provider_payload_input,'{}'::jsonb),updated_at=now()
      where id=order_record.id returning * into order_record;
    return order_record;
  end if;
  begin expiry := to_timestamp((provider_payload_input->>'expiresAt')::bigint); exception when others then expiry := null; end;
  select * into old_order from public.payos_orders where payment_id=payment_id_input and purpose='crm_payment' and status='pending' and active_slot is true order by id desc limit 1 for update;
  if found and old_order.order_code<>order_code_input then
    if old_order.expires_at is null or old_order.expires_at>now() then raise exception 'Thanh toán đã có một mã PayOS còn hiệu lực.' using errcode='23505'; end if;
    update public.payos_orders set status='expired',active_slot=null,processed_at=coalesce(processed_at,now()),updated_at=now() where id=old_order.id;
  end if;
  insert into public.payos_orders(order_code,purpose,payment_id,amount,description,checkout_url,qr_code,payment_link_id,provider_payload,created_by,expires_at,active_slot)
  values(order_code_input,'crm_payment',payment_id_input,amount_input,nullif(trim(description_input),''),nullif(trim(checkout_url_input),''),nullif(trim(qr_code_input),''),nullif(trim(payment_link_id_input),''),coalesce(provider_payload_input,'{}'::jsonb),auth.uid(),expiry,true)
  on conflict(order_code) do update set checkout_url=excluded.checkout_url,qr_code=excluded.qr_code,payment_link_id=excluded.payment_link_id,
    provider_payload=excluded.provider_payload,expires_at=coalesce(excluded.expires_at,public.payos_orders.expires_at),updated_at=now()
  where public.payos_orders.status='pending' returning * into order_record;
  if old_order.id is not null and old_order.id<>order_record.id then update public.payos_orders set superseded_by_order_id=order_record.id where id=old_order.id; end if;
  return order_record;
end;$function$

