CREATE OR REPLACE FUNCTION public.admin_cancel_awaiting_registration(request_id_input bigint, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request_record public.registration_requests%rowtype;
  batch_record public.registration_batches%rowtype;
  payment_record public.payments%rowtype;
  cancelled_at timestamptz := pg_catalog.now();
  affected_requests bigint[];
begin
  perform private.assert_registration_permission();
  if nullif(pg_catalog.btrim(reason_input), '') is null then
    raise exception 'Cần nhập lý do hủy.' using errcode = '22023';
  end if;

  select * into request_record
  from public.registration_requests
  where id = request_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy hồ sơ đăng ký.' using errcode = 'P0002';
  end if;
  if request_record.status = 'cancelled' then
    return pg_catalog.jsonb_build_object('already_cancelled', true, 'request_id', request_record.id);
  end if;
  if request_record.status <> 'awaiting_payment' then
    raise exception 'Chỉ hồ sơ chờ thanh toán mới có thể hủy.' using errcode = '22023';
  end if;

  if request_record.registration_batch_id is not null then
    select * into batch_record
    from public.registration_batches
    where id = request_record.registration_batch_id
    for update;
    select * into payment_record
    from public.payments
    where id = batch_record.payment_id
    for update;

    if payment_record.payment_status = 'completed'
      or exists (
        select 1 from public.payos_orders o
        where o.payment_id = payment_record.id and o.status = 'paid'
      )
      or exists (
        select 1
        from public.registration_batch_items i
        join public.kiosks k on k.id = i.kiosk_id
        where i.batch_id = batch_record.id and k.status = 'active'
      ) then
      raise exception 'Hồ sơ đã có thanh toán hoàn tất hoặc Kiosk hoạt động.' using errcode = '23505';
    end if;

    select pg_catalog.array_agg(i.registration_request_id order by i.registration_request_id)
    into affected_requests
    from public.registration_batch_items i
    where i.batch_id = batch_record.id;

    update public.payos_orders
    set status = 'cancelled', active_slot = false,
        processed_at = coalesce(processed_at, cancelled_at), updated_at = cancelled_at,
        provider_payload = coalesce(provider_payload, '{}'::jsonb)
          || pg_catalog.jsonb_build_object('admin_logical_cancel', true)
    where payment_id = payment_record.id and status = 'pending';

    if payment_record.payment_status = 'pending' then
      perform pg_catalog.set_config('app.payment_workflow_action', 'cancel', true);
      update public.payments
      set payment_status = 'cancelled',
          note = pg_catalog.concat_ws(E'\n', nullif(note, ''), 'Admin cancelled: ' || pg_catalog.btrim(reason_input))
      where id = payment_record.id;
    end if;
    update public.registration_batches
    set status = 'cancelled', updated_at = cancelled_at
    where id = batch_record.id;

    update public.kiosks k
    set status = 'inactive'
    where k.status = 'pending'
      and exists (
        select 1 from public.registration_batch_items i
        where i.batch_id = batch_record.id and i.kiosk_id = k.id
      )
      and not exists (
        select 1 from public.payments completed_payment
        where completed_payment.kiosk_id = k.id
          and completed_payment.payment_status = 'completed'
      );
  else
    affected_requests := array[request_record.id];
  end if;

  update public.registration_requests
  set status = 'cancelled',
      reviewed_at = cancelled_at,
      reviewed_by = auth.uid(),
      rejection_reason = pg_catalog.btrim(reason_input),
      metadata = coalesce(metadata, '{}'::jsonb) || pg_catalog.jsonb_build_object(
        'cancelled_source', 'admin', 'cancelled_at', cancelled_at
      )
  where id = any(affected_requests);

  perform private.write_ttc_audit(
    'Registration', 'admin_cancel', 'registration_requests', request_id_input::text,
    pg_catalog.to_jsonb(request_record),
    pg_catalog.jsonb_build_object(
      'status', 'cancelled',
      'batch_id', request_record.registration_batch_id,
      'affected_request_ids', affected_requests
    ),
    pg_catalog.btrim(reason_input)
  );

  return pg_catalog.jsonb_build_object(
    'already_cancelled', false,
    'request_id', request_id_input,
    'batch_id', request_record.registration_batch_id,
    'affected_request_ids', affected_requests
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_complete_awaiting_registration(request_id_input bigint, note_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request_record public.registration_requests%rowtype;
  batch_record public.registration_batches%rowtype;
  payment_record public.payments%rowtype;
  prepared jsonb;
  item_record record;
  completed_at timestamptz := pg_catalog.now();
  completed_on date := (pg_catalog.now() at time zone 'Asia/Ho_Chi_Minh')::date;
  calculated_end date;
  item_count integer := 0;
begin
  perform private.assert_registration_permission();

  select * into request_record
  from public.registration_requests
  where id = request_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy hồ sơ đăng ký.' using errcode = 'P0002';
  end if;

  if request_record.status = 'approved' and request_record.payment_id is not null
    and exists (
      select 1 from public.payments p
      where p.id = request_record.payment_id and p.payment_status = 'completed'
    ) then
    return pg_catalog.jsonb_build_object(
      'already_completed', true,
      'request_id', request_record.id,
      'payment_id', request_record.payment_id,
      'batch_id', request_record.registration_batch_id
    );
  end if;
  if request_record.status <> 'awaiting_payment' then
    raise exception 'Hồ sơ không còn chờ thanh toán.' using errcode = '22023';
  end if;

  if request_record.registration_batch_id is null then
    prepared := private.materialize_registration_checkout_v3(
      array[request_record.id], request_record.phone, null
    );
    request_record.registration_batch_id := (prepared->'batch'->>'id')::bigint;
  end if;

  select * into batch_record
  from public.registration_batches
  where id = request_record.registration_batch_id
  for update;
  select * into payment_record
  from public.payments
  where id = batch_record.payment_id
  for update;

  if batch_record.status <> 'pending' or payment_record.payment_status <> 'pending' then
    raise exception 'Lô hoặc thanh toán không còn chờ xử lý.' using errcode = '22023';
  end if;
  if exists (
    select 1 from public.payos_orders o
    where o.payment_id = payment_record.id and o.status = 'paid'
  ) then
    raise exception 'PayOS đã ghi nhận thanh toán; không thể xác nhận ngoài PayOS.' using errcode = '23505';
  end if;

  perform 1
  from public.registration_batch_items i
  join public.kiosks k on k.id = i.kiosk_id
  join public.registration_requests r on r.id = i.registration_request_id
  where i.batch_id = batch_record.id
  order by i.id
  for update of i, k, r;

  update public.payos_orders
  set status = 'cancelled',
      active_slot = false,
      processed_at = coalesce(processed_at, completed_at),
      updated_at = completed_at,
      provider_payload = coalesce(provider_payload, '{}'::jsonb)
        || pg_catalog.jsonb_build_object('admin_logical_cancel', true)
  where payment_id = payment_record.id and status = 'pending';

  for item_record in
    select i.*
    from public.registration_batch_items i
    where i.batch_id = batch_record.id
    order by i.id
  loop
    calculated_end := (
      completed_on
      + pg_catalog.make_interval(months => item_record.effective_service_months)
      - interval '1 day'
    )::date;
    update public.registration_batch_items
    set start_date = completed_on, end_date = calculated_end
    where id = item_record.id;
    update public.kiosks
    set status = 'active', start_date = completed_on, end_date = calculated_end
    where id = item_record.kiosk_id;
    update public.registration_requests
    set status = 'approved',
        requested_start_date = completed_on,
        requested_end_date = calculated_end,
        reviewed_at = completed_at,
        reviewed_by = auth.uid(),
        metadata = coalesce(metadata, '{}'::jsonb) || pg_catalog.jsonb_build_object(
          'completed_source', 'admin_external',
          'completed_at', completed_at
        )
    where id = item_record.registration_request_id;
    item_count := item_count + 1;
  end loop;

  if item_count < 1 then
    raise exception 'Lô đăng ký không có Kiosk.' using errcode = '23514';
  end if;

  perform pg_catalog.set_config('app.payment_workflow_action', 'confirm', true);
  update public.payments
  set payment_method = 'external',
      payment_status = 'completed',
      confirmed_by = auth.uid()::text,
      confirmed_at = completed_at,
      note = pg_catalog.concat_ws(E'\n', nullif(note, ''),
        'Admin external payment: ' || coalesce(nullif(pg_catalog.btrim(note_input), ''), 'confirmed'))
  where id = payment_record.id
  returning * into payment_record;

  update public.registration_batches
  set status = 'approved', approved_at = completed_at, updated_at = completed_at
  where id = batch_record.id
  returning * into batch_record;

  update public.customers
  set status = case when pg_catalog.lower(coalesce(status, '')) = 'pending' then 'active' else status end,
      total_kiosks = (
        select pg_catalog.count(*) from public.kiosks k where k.customer_id = batch_record.customer_id
      )
  where id = batch_record.customer_id;

  perform private.write_ttc_audit(
    'Registration', 'manual_accept', 'registration_batches', batch_record.id::text,
    null,
    pg_catalog.jsonb_build_object(
      'request_id', request_id_input,
      'payment_id', payment_record.id,
      'amount', payment_record.total_amount,
      'payment_method', 'external',
      'kiosk_count', item_count
    ),
    coalesce(nullif(pg_catalog.btrim(note_input), ''), 'Admin confirmed external payment')
  );

  return pg_catalog.jsonb_build_object(
    'already_completed', false,
    'request_id', request_id_input,
    'batch_id', batch_record.id,
    'payment_id', payment_record.id,
    'amount', payment_record.total_amount,
    'kiosk_count', item_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_ttc_campaign_for_user(owner_user_id_input uuid, interaction_type_input text, target_url_input text, target_quantity_input integer, idempotency_key_input text, target_facebook_id_input text DEFAULT NULL::text, target_label_input text DEFAULT NULL::text, comment_options_input jsonb DEFAULT '[]'::jsonb, metadata_input jsonb DEFAULT '{}'::jsonb, admin_reason_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  profile_record public.user_profiles%rowtype;
  type_record public.ttc_interaction_types%rowtype;
  campaign_record public.ttc_campaigns%rowtype;
  ledger_result jsonb;
  task_index integer;
  normalized_key text := nullif(trim(idempotency_key_input), '');
  total_cost numeric(14, 2);
begin
  actor := private.assert_ttc_staff('admin-ttc');

  if owner_user_id_input is null then
    raise exception 'User owner là bắt buộc.' using errcode = '22023';
  end if;
  if normalized_key is null then
    raise exception 'idempotency_key là bắt buộc.' using errcode = '22023';
  end if;

  select *
  into campaign_record
  from public.ttc_campaigns
  where owner_user_id = owner_user_id_input
    and idempotency_key = normalized_key;
  if found then
    return jsonb_build_object('campaign', to_jsonb(campaign_record), 'already_processed', true);
  end if;

  select *
  into profile_record
  from public.user_profiles
  where user_id = owner_user_id_input
    and status = 'active';
  if not found then
    raise exception 'User owner chưa có hồ sơ active để tạo tăng tương tác.' using errcode = '42501';
  end if;

  select *
  into type_record
  from public.ttc_interaction_types
  where code = interaction_type_input
    and is_active = true;
  if not found then
    raise exception 'Loại tương tác TTC không hợp lệ hoặc đã tắt.' using errcode = '22023';
  end if;
  if target_quantity_input < type_record.min_quantity or target_quantity_input > type_record.max_quantity then
    raise exception 'Số lượng nhiệm vụ không nằm trong giới hạn cấu hình.' using errcode = '22023';
  end if;
  if nullif(trim(target_url_input), '') is null then
    raise exception 'Link mục tiêu là bắt buộc.' using errcode = '22023';
  end if;
  if target_facebook_id_input is not null and target_facebook_id_input !~ '^[0-9]+$' then
    raise exception 'Facebook ID mục tiêu chỉ được chứa chữ số.' using errcode = '22023';
  end if;

  total_cost := type_record.unit_cost * target_quantity_input;

  insert into public.ttc_campaigns(
    owner_user_id,
    interaction_type_code,
    target_url,
    target_facebook_id,
    target_label,
    comment_options,
    target_quantity,
    unit_cost,
    worker_reward,
    reserved_amount,
    status,
    created_by_admin,
    admin_reason,
    idempotency_key,
    metadata
  )
  values(
    owner_user_id_input,
    type_record.code,
    trim(target_url_input),
    nullif(trim(target_facebook_id_input), ''),
    nullif(trim(target_label_input), ''),
    coalesce(comment_options_input, '[]'::jsonb),
    target_quantity_input,
    type_record.unit_cost,
    type_record.worker_reward,
    total_cost,
    'queued',
    actor.user_id,
    nullif(trim(admin_reason_input), ''),
    normalized_key,
    coalesce(metadata_input, '{}'::jsonb)
      || jsonb_build_object(
        'created_by_admin', actor.user_id,
        'platform', type_record.config->>'platform',
        'action', type_record.config->>'action'
      )
  )
  returning * into campaign_record;

  ledger_result := private.post_wallet_ledger(
    owner_user_id_input,
    -total_cost,
    'spend_campaign',
    'ttc_campaigns',
    campaign_record.id::text,
    'admin_ttc_campaign:create:' || normalized_key,
    'Admin tạo tăng tương tác TTC #' || campaign_record.id,
    coalesce(nullif(trim(admin_reason_input), ''), 'Admin tạo tăng tương tác TTC'),
    jsonb_build_object(
      'campaign_id', campaign_record.id,
      'interaction_type', type_record.code,
      'platform', type_record.config->>'platform',
      'action', type_record.config->>'action'
    ),
    actor.user_id,
    'staff'
  );

  for task_index in 1..target_quantity_input loop
    insert into public.ttc_tasks(campaign_id, sequence_no)
    values (campaign_record.id, task_index);
  end loop;

  perform private.write_ttc_audit(
    'TTC',
    'admin_create_campaign',
    'ttc_campaigns',
    campaign_record.id::text,
    null,
    to_jsonb(campaign_record),
    coalesce(nullif(trim(admin_reason_input), ''), 'Admin tạo tăng tương tác TTC')
  );

  return jsonb_build_object(
    'campaign', to_jsonb(campaign_record),
    'wallet', ledger_result->'wallet',
    'task_count', target_quantity_input,
    'already_processed', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_unused_promotion(promotion_id_input bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare promotion_record public.promotions%rowtype;
begin
  if not (select public.is_active_promotion_admin()) then
    raise exception 'Bạn không có quyền quản lý mã giảm giá.' using errcode = '42501';
  end if;

  select p.* into promotion_record
  from public.promotions as p
  where p.id = promotion_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy chương trình khuyến mãi.' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.promotion_usages as pu where pu.promotion_id = promotion_record.id)
    or exists (
      select 1 from public.registration_batches as b
      where b.promotion_id = promotion_record.id
         or b.promotion_snapshot->>'promotionId' = promotion_record.id::text
    )
    or exists (
      select 1
      from public.payments as pay
      join public.registration_batches as b
        on b.id = pay.registration_batch_id or b.payment_id = pay.id
      where (b.promotion_id = promotion_record.id
          or b.promotion_snapshot->>'promotionId' = promotion_record.id::text)
        and pay.payment_status = 'completed'
    ) then
    raise exception E'Không thể xóa chương trình đã phát sinh giao dịch.\nBạn có thể tạm ngưng chương trình này để ngừng sử dụng.' using errcode = 'P0001';
  end if;

  perform private.write_ttc_audit('Promotion','delete_promotion','promotions',promotion_record.id::text,to_jsonb(promotion_record),null,'Deleted unused promotion');
  delete from public.promotions as p where p.id = promotion_record.id;
  return jsonb_build_object('deleted',true,'id',promotion_record.id,'code',promotion_record.code,'name',promotion_record.name);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_manual_renew_kiosk(kiosk_id_input bigint, months_input integer, start_date_input date, base_amount_input numeric, discount_input numeric DEFAULT 0, discount_reason_input text DEFAULT NULL::text, payment_method_input text DEFAULT NULL::text, note_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  kiosk_record public.kiosks%rowtype;
  customer_record public.customers%rowtype;
  payment_record public.payments%rowtype;
  confirmation_date date := (pg_catalog.now() at time zone 'Asia/Ho_Chi_Minh')::date;
  confirmation_timestamp timestamptz := pg_catalog.now();
  effective_start_date date;
  calculated_end_date date;
  normalized_discount numeric := coalesce(discount_input, 0);
  actual_amount numeric;
  normalized_method text := lower(trim(coalesce(payment_method_input, '')));
begin
  actor := private.assert_payment_permission();
  if lower(actor.role) <> 'admin' then
    raise exception 'Chỉ Admin được xác nhận gia hạn thủ công.' using errcode = '42501';
  end if;

  if months_input is null or months_input < 1 then
    raise exception 'Số tháng phải là số nguyên lớn hơn 0.' using errcode = '22023';
  end if;
  if base_amount_input is null or base_amount_input < 0 then
    raise exception 'Giá gốc không hợp lệ.' using errcode = '22023';
  end if;
  if normalized_discount < 0 or normalized_discount > base_amount_input then
    raise exception 'Giảm giá phải từ 0 đến giá gốc.' using errcode = '22023';
  end if;
  if normalized_discount > 0 and nullif(trim(discount_reason_input), '') is null then
    raise exception 'Lý do giảm giá là bắt buộc khi có giảm giá.' using errcode = '22023';
  end if;
  if normalized_method not in ('transfer', 'cash', 'other') then
    raise exception 'Phương thức thanh toán không hợp lệ.' using errcode = '22023';
  end if;

  select * into kiosk_record
  from public.kiosks
  where id = kiosk_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy Kiosk.' using errcode = 'P0002';
  end if;
  if kiosk_record.customer_id is null then
    raise exception 'Kiosk thiếu khách hàng.' using errcode = '22023';
  end if;

  select * into customer_record
  from public.customers
  where id = kiosk_record.customer_id
  for update;
  if not found then
    raise exception 'Khách hàng của Kiosk không tồn tại.' using errcode = 'P0002';
  end if;

  -- start_date_input remains in the public signature for client compatibility,
  -- but the locked Kiosk row and confirmation date are authoritative.
  effective_start_date := case
    when kiosk_record.end_date is not null and kiosk_record.end_date >= confirmation_date
      then kiosk_record.end_date + 1
    else confirmation_date
  end;
  calculated_end_date := (
    effective_start_date
    + pg_catalog.make_interval(months => months_input)
    - interval '1 day'
  )::date;

  actual_amount := base_amount_input - normalized_discount;
  insert into public.payments(
    customer_id, kiosk_id, start_date, end_date, months, price_per_month,
    discount, discount_reason, total_amount, payment_method, payment_status,
    confirmed_by, confirmed_at, note, transaction_type, service_month_delta
  ) values (
    customer_record.id, kiosk_record.id, effective_start_date, calculated_end_date,
    months_input, base_amount_input / months_input, normalized_discount,
    nullif(trim(discount_reason_input), ''), actual_amount, normalized_method, 'pending',
    null, null, nullif(trim(note_input), ''), 'standard', 0
  ) returning * into payment_record;

  perform pg_catalog.set_config('app.payment_workflow_action', 'confirm', true);
  update public.payments
  set payment_status = 'completed',
      confirmed_by = actor.user_id::text,
      confirmed_at = confirmation_timestamp
  where id = payment_record.id
  returning * into payment_record;

  update public.kiosks
  set status = 'active',
      end_date = calculated_end_date
  where id = kiosk_record.id;

  update public.customers
  set status = case when lower(coalesce(status, '')) = 'pending' then 'active' else status end,
      total_kiosks = (select count(*) from public.kiosks k where k.customer_id = customer_record.id)
  where id = customer_record.id;

  perform private.write_payment_audit(
    'admin_manual_renewal',
    jsonb_build_object('kiosk', to_jsonb(kiosk_record)),
    jsonb_build_object(
      'payment', to_jsonb(payment_record),
      'kiosk_id', kiosk_record.id,
      'original_activation_date', kiosk_record.start_date,
      'old_expiry_date', kiosk_record.end_date,
      'requested_start_date', start_date_input,
      'renewal_period_start', effective_start_date,
      'renewal_period_end', calculated_end_date,
      'months', months_input,
      'base_amount', base_amount_input,
      'discount', normalized_discount,
      'actual_amount', actual_amount,
      'payment_source', 'admin_manual'
    ),
    coalesce(nullif(trim(note_input), ''), 'Admin xác nhận đã thanh toán và gia hạn Kiosk'),
    actor
  );

  return jsonb_build_object(
    'payment', to_jsonb(payment_record),
    'kiosk', (select to_jsonb(k) from public.kiosks k where k.id = kiosk_record.id),
    'period', jsonb_build_object('start_date', effective_start_date, 'end_date', calculated_end_date),
    'payment_source', 'admin_manual'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_manual_renew_kiosk(kiosk_id_input bigint, months_input integer, start_date_input date, base_amount_input numeric, discount_input numeric, discount_reason_input text, payment_method_input text, note_input text, promotion_code_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.user_roles%rowtype; prepared jsonb; result jsonb; payment_id_value bigint;
begin
 actor:=private.assert_payment_permission();
 if lower(actor.role)<>'admin' then raise exception 'Chỉ Admin được xác nhận gia hạn thủ công.' using errcode='42501'; end if;
 if payment_method_input not in ('transfer','cash','other') then raise exception 'Phương thức thanh toán không hợp lệ.'; end if;
 if nullif(btrim(promotion_code_input),'') is null then
   return public.admin_manual_renew_kiosk(kiosk_id_input,months_input,start_date_input,base_amount_input,discount_input,discount_reason_input,payment_method_input,note_input);
 end if;
 prepared:=private.prepare_renewal_payment(kiosk_id_input,months_input,promotion_code_input,discount_input,discount_reason_input,note_input,false);
 payment_id_value:=(prepared->'payment'->>'id')::bigint;
 if exists(select 1 from public.payos_orders where payment_id=payment_id_value and reconciliation_required) then raise exception 'Thanh toán cần đối soát trước khi xác nhận.'; end if;
 perform set_config('app.payment_workflow_action','edit',true);
 update public.payments set payment_method=payment_method_input where id=payment_id_value;
 result:=private.confirm_crm_payment_from_payos(payment_id_value,'Admin xác nhận đã nhận tiền: '||coalesce(note_input,''));
 update public.payos_orders set active_slot=null where payment_id=payment_id_value and active_slot is true;
 return result||jsonb_build_object('period',jsonb_build_object('start_date',result->'payment'->'start_date','end_date',result->'payment'->'end_date'),'payment_source','admin_manual');
end $function$

CREATE OR REPLACE FUNCTION public.admin_post_wallet_ledger(wallet_user_id_input uuid, amount_input numeric, transaction_type_input text DEFAULT 'admin_adjustment'::text, related_table_input text DEFAULT NULL::text, related_id_input text DEFAULT NULL::text, idempotency_key_input text DEFAULT NULL::text, description_input text DEFAULT NULL::text, reason_input text DEFAULT NULL::text, metadata_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
begin
  actor := private.assert_ttc_staff('admin-ttc');
  if nullif(trim(reason_input), '') is null then
    raise exception 'Lý do cộng/trừ xu là bắt buộc.' using errcode = '22023';
  end if;
  if transaction_type_input <> 'admin_adjustment' then
    raise exception 'Admin chỉ được dùng loại admin_adjustment qua RPC này.' using errcode = '22023';
  end if;

  return private.post_wallet_ledger(
    wallet_user_id_input,
    amount_input,
    transaction_type_input,
    related_table_input,
    related_id_input,
    idempotency_key_input,
    description_input,
    reason_input,
    metadata_input,
    actor.user_id,
    'staff'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_promotion(promotion_id_input bigint, promotion_input jsonb, category_ids_input bigint[] DEFAULT '{}'::bigint[], business_type_ids_input bigint[] DEFAULT '{}'::bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  saved public.promotions%rowtype;
  scope_value text := coalesce(promotion_input->>'scope_type', 'all');
begin
  if not exists (
    select 1
    from public.user_roles as ur
    where ur.user_id = (select auth.uid())
      and pg_catalog.lower(ur.role) = 'admin'
      and ur.is_active
  ) then
    raise exception 'Bạn không có quyền quản lý mã giảm giá.' using errcode = '42501';
  end if;

  if scope_value = 'category'
    and coalesce(pg_catalog.array_length(category_ids_input, 1), 0) = 0 then
    raise exception 'Vui lòng chọn ít nhất một danh mục.' using errcode = '22023';
  end if;

  if scope_value = 'business_type'
    and coalesce(pg_catalog.array_length(business_type_ids_input, 1), 0) = 0 then
    raise exception 'Vui lòng chọn ít nhất một loại hình kinh doanh.' using errcode = '22023';
  end if;

  if scope_value = 'category' and exists (
    select 1
    from pg_catalog.unnest(category_ids_input) as category_scope(category_id)
    left join public.categories as c on c.id = category_scope.category_id
    where c.id is null
  ) then
    raise exception 'Danh mục áp dụng không hợp lệ.' using errcode = '22023';
  end if;

  if scope_value = 'business_type' and exists (
    select 1
    from pg_catalog.unnest(business_type_ids_input) as business_type_scope(business_type_id)
    left join public.business_types as bt on bt.id = business_type_scope.business_type_id
    where bt.id is null
  ) then
    raise exception 'Loại hình kinh doanh áp dụng không hợp lệ.' using errcode = '22023';
  end if;

  if promotion_id_input is null then
    insert into public.promotions as p (
      code, name, description, discount_type, discount_value,
      max_discount_amount, minimum_order_amount, minimum_kiosk_count,
      minimum_months, starts_at, ends_at, usage_limit_total,
      usage_limit_per_customer, scope_type, is_active, created_by
    ) values (
      promotion_input->>'code',
      promotion_input->>'name',
      promotion_input->>'description',
      promotion_input->>'discount_type',
      (promotion_input->>'discount_value')::bigint,
      nullif(promotion_input->>'max_discount_amount', '')::bigint,
      nullif(promotion_input->>'minimum_order_amount', '')::bigint,
      nullif(promotion_input->>'minimum_kiosk_count', '')::integer,
      nullif(promotion_input->>'minimum_months', '')::integer,
      nullif(promotion_input->>'starts_at', '')::timestamptz,
      nullif(promotion_input->>'ends_at', '')::timestamptz,
      nullif(promotion_input->>'usage_limit_total', '')::integer,
      nullif(promotion_input->>'usage_limit_per_customer', '')::integer,
      scope_value,
      coalesce((promotion_input->>'is_active')::boolean, true),
      (select auth.uid())
    ) returning p.* into saved;
  else
    update public.promotions as p
    set
      name = promotion_input->>'name',
      description = promotion_input->>'description',
      discount_type = promotion_input->>'discount_type',
      discount_value = (promotion_input->>'discount_value')::bigint,
      max_discount_amount = nullif(promotion_input->>'max_discount_amount', '')::bigint,
      minimum_order_amount = nullif(promotion_input->>'minimum_order_amount', '')::bigint,
      minimum_kiosk_count = nullif(promotion_input->>'minimum_kiosk_count', '')::integer,
      minimum_months = nullif(promotion_input->>'minimum_months', '')::integer,
      starts_at = nullif(promotion_input->>'starts_at', '')::timestamptz,
      ends_at = nullif(promotion_input->>'ends_at', '')::timestamptz,
      usage_limit_total = nullif(promotion_input->>'usage_limit_total', '')::integer,
      usage_limit_per_customer = nullif(promotion_input->>'usage_limit_per_customer', '')::integer,
      scope_type = scope_value
    where p.id = promotion_id_input
    returning p.* into saved;

    if not found then
      raise exception 'Không tìm thấy chương trình khuyến mãi.' using errcode = 'P0002';
    end if;
  end if;

  delete from public.promotion_categories as pc
  where pc.promotion_id = saved.id;

  delete from public.promotion_business_types as pbt
  where pbt.promotion_id = saved.id;

  if scope_value = 'category' then
    insert into public.promotion_categories (promotion_id, category_id)
    select distinct saved.id, category_scope.category_id
    from pg_catalog.unnest(category_ids_input) as category_scope(category_id);
  end if;

  if scope_value = 'business_type' then
    insert into public.promotion_business_types (promotion_id, business_type_id)
    select distinct saved.id, business_type_scope.business_type_id
    from pg_catalog.unnest(business_type_ids_input) as business_type_scope(business_type_id);
  end if;

  return to_jsonb(saved);
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_registration_request(request_id_input bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  request_record public.registration_requests%rowtype;
  before_record public.registration_requests%rowtype;
  payment_id_value bigint;
  payment_record public.payments%rowtype;
begin
  actor := private.assert_registration_permission();

  update public.registration_requests
  set
    payment_id = payment_id_value,
    status = 'approved',
    reviewed_at = pg_catalog.now(),
    reviewed_by = actor.user_id,
    rejection_reason = null
  where id = request_record.id
  returning * into request_record;

  insert into public.audit_logs(
    actor_id, actor_name, actor_type, actor_role, module, entity,
    record_id, action, before, after, reason
  )
  values(
    actor.user_id,
    coalesce(actor.display_name, actor.username, 'System'),
    'staff',
    actor.role,
    'Registration',
    'registration_requests',
    request_record.id::text,
    'approve_profile_pending_payment',
    to_jsonb(before_record),
    to_jsonb(request_record),
    'Duyệt hồ sơ đăng ký, giữ thanh toán Pending để khách chuyển khoản/PayOS'
  );

  return jsonb_build_object(
    'request', to_jsonb(request_record),
    'payment', to_jsonb(payment_record)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_expense(p_id bigint, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  actor public.user_profiles%rowtype;
  before_expense public.expenses%rowtype;
  saved_expense public.expenses%rowtype;
  normalized_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if not public.has_user_permission('expenses') then
    raise exception 'Không có quyền quản lý chi phí.' using errcode = '42501';
  end if;
  select * into actor from public.user_profiles where user_id = auth.uid();
  select * into before_expense from public.expenses where id = p_id and archived_at is null for update;
  if before_expense.id is null then raise exception 'Khoản chi không tồn tại hoặc đã hủy.'; end if;
  update public.expenses set archived_at = now(), archived_by = auth.uid()
  where id = p_id returning * into saved_expense;
  insert into public.audit_logs(actor_id, actor_name, actor_role, actor_type, module, entity, record_id, action, before, after, reason)
  values (
    auth.uid(), coalesce(actor.display_name, actor.username, 'Quản trị viên'),
    case when actor.is_system_admin then 'system_admin' else 'staff' end, 'staff',
    'Expense', 'expenses', saved_expense.id::text, 'archive_expense',
    to_jsonb(before_expense), to_jsonb(saved_expense), coalesce(normalized_reason, 'Hủy khoản chi')
  );
  return to_jsonb(saved_expense);
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_expense_category(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare saved public.expense_categories%rowtype;
begin
  if not public.has_user_permission('expenses') then raise exception 'Không có quyền quản lý chi phí.' using errcode='42501'; end if;
  update public.expense_categories set is_active=false,archived_at=now(),archived_by=auth.uid()
    where id=p_id and archived_at is null returning * into saved;
  if saved.id is null then raise exception 'Danh mục không tồn tại hoặc đã lưu trữ.'; end if;
  return to_jsonb(saved);
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_featured_business(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  actor public.user_profiles%rowtype;
  before_business public.featured_businesses%rowtype;
  saved_business public.featured_businesses%rowtype;
begin
  if not public.has_user_permission('homepage-content') then raise exception 'Không có quyền quản lý nội dung trang chủ.' using errcode='42501'; end if;
  select * into actor from public.user_profiles where user_id=auth.uid();
  select * into before_business from public.featured_businesses where id=p_id and archived_at is null for update;
  if before_business.id is null then raise exception 'Doanh nghiệp không tồn tại hoặc đã lưu trữ.'; end if;
  update public.featured_businesses set archived_at=now(), archived_by=auth.uid() where id=p_id returning * into saved_business;
  insert into public.audit_logs(actor_id,actor_name,actor_role,actor_type,module,entity,record_id,action,before,after,reason)
  values (auth.uid(),coalesce(actor.display_name,actor.username,'Quản trị viên'),case when actor.is_system_admin then 'system_admin' else 'staff' end,'staff',
    'Homepage','featured_businesses',saved_business.id::text,'archive_featured_business',to_jsonb(before_business),to_jsonb(saved_business),saved_business.name);
  return to_jsonb(saved_business);
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_payment(payment_id_input bigint, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
begin
  actor := private.assert_payment_permission();

  if nullif(trim(reason_input), '') is null then
    raise exception 'Lý do hủy là bắt buộc.';
  end if;

  select * into payment_record
  from public.payments
  where id = payment_id_input
  for update;

  if not found or lower(payment_record.payment_status) <> 'pending' then
    raise exception 'Chỉ thanh toán Pending mới được hủy.';
  end if;

  before_record := payment_record;
  perform set_config('app.payment_workflow_action', 'cancel', true);

  update public.payments
  set payment_status = 'cancelled'
  where id = payment_record.id
  returning * into payment_record;

  perform private.write_payment_audit(
    'cancel',
    to_jsonb(before_record),
    to_jsonb(payment_record),
    reason_input,
    actor
  );

  return to_jsonb(payment_record);
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_ttc_campaign(campaign_id_input bigint, reason_input text, idempotency_key_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  campaign_record public.ttc_campaigns%rowtype;
  before_campaign public.ttc_campaigns%rowtype;
  actor public.user_roles%rowtype;
  is_staff boolean := false;
  refundable_amount numeric(14, 2);
  ledger_result jsonb := null;
  normalized_key text := nullif(trim(idempotency_key_input), '');
  affected_tasks integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để hủy chiến dịch.' using errcode = '42501';
  end if;
  if nullif(trim(reason_input), '') is null then
    raise exception 'Lý do hủy chiến dịch là bắt buộc.' using errcode = '22023';
  end if;
  if normalized_key is null then
    raise exception 'idempotency_key là bắt buộc.' using errcode = '22023';
  end if;

  select *
  into before_campaign
  from public.ttc_campaigns
  where id = campaign_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy chiến dịch TTC.' using errcode = '22023';
  end if;
  if before_campaign.status = 'cancelled' then
    return jsonb_build_object('campaign', to_jsonb(before_campaign), 'already_processed', true);
  end if;

  begin
    actor := private.assert_ttc_staff('admin-ttc');
    is_staff := true;
  exception when insufficient_privilege then
    is_staff := false;
  end;

  if not is_staff and before_campaign.owner_user_id <> auth.uid() then
    raise exception 'Không có quyền hủy chiến dịch này.' using errcode = '42501';
  end if;
  if before_campaign.status in ('completed', 'failed') then
    raise exception 'Chiến dịch ở trạng thái kết thúc không thể hủy.' using errcode = '22023';
  end if;

  with affected as (
    select id, status
    from public.ttc_tasks
    where campaign_id = before_campaign.id
      and status in ('available', 'assigned', 'submitted', 'verifying')
    for update
  ),
  updated as (
    update public.ttc_tasks t
    set
      status = case
        when affected.status in ('submitted', 'verifying') then 'rejected'
        else 'expired'
      end,
      verified_at = case
        when affected.status in ('submitted', 'verifying') then now()
        else t.verified_at
      end,
      verified_by = case
        when affected.status in ('submitted', 'verifying') and is_staff then actor.user_id
        else t.verified_by
      end,
      rejection_reason = case
        when affected.status in ('submitted', 'verifying') then trim(reason_input)
        else t.rejection_reason
      end,
      metadata = coalesce(t.metadata, '{}'::jsonb) || jsonb_build_object('cancelled_with_campaign', true)
    from affected
    where t.id = affected.id
    returning t.id, affected.status as before_status, t.status as after_status
  ),
  logged as (
    insert into public.ttc_task_check_logs(
      task_id,
      campaign_id,
      actor_id,
      check_type,
      result,
      before_status,
      after_status,
      reason,
      metadata
    )
    select
      updated.id,
      before_campaign.id,
      auth.uid(),
      'system',
      case when updated.after_status = 'rejected' then 'failed' else 'pending' end,
      updated.before_status,
      updated.after_status,
      trim(reason_input),
      jsonb_build_object('campaign_cancelled', true)
    from updated
    returning 1
  )
  select count(*) into affected_tasks from logged;

  refundable_amount := greatest(
    before_campaign.reserved_amount - before_campaign.spent_amount - before_campaign.refunded_amount,
    0
  );

  update public.ttc_campaigns
  set
    status = 'cancelled',
    refunded_amount = refunded_amount + refundable_amount
  where id = before_campaign.id
  returning * into campaign_record;

  if refundable_amount > 0 then
    ledger_result := private.post_wallet_ledger(
      campaign_record.owner_user_id,
      refundable_amount,
      'refund_campaign',
      'ttc_campaigns',
      campaign_record.id::text,
      'ttc_campaign:cancel:' || normalized_key,
      'Hoàn xu chiến dịch TTC #' || campaign_record.id,
      reason_input,
      jsonb_build_object('campaign_id', campaign_record.id),
      auth.uid(),
      case when is_staff then 'staff' else 'user' end
    );
  end if;

  perform private.write_ttc_audit(
    'TTC',
    'cancel_campaign',
    'ttc_campaigns',
    campaign_record.id::text,
    to_jsonb(before_campaign),
    to_jsonb(campaign_record) || jsonb_build_object('affected_tasks', affected_tasks),
    reason_input
  );

  return jsonb_build_object(
    'campaign', to_jsonb(campaign_record),
    'wallet', ledger_result->'wallet',
    'refunded_amount', refundable_amount,
    'affected_tasks', affected_tasks,
    'already_processed', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.check_duplicate_salary_expense(p_employee_user_id uuid, p_salary_period date, p_exclude_id bigint DEFAULT NULL::bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not public.has_user_permission('expenses') then
    raise exception 'Không có quyền quản lý chi phí.' using errcode = '42501';
  end if;
  if p_employee_user_id is null or p_salary_period is null then return false; end if;
  return exists (
    select 1 from public.expenses e
    where e.category = 'salary'
      and e.employee_user_id = p_employee_user_id
      and e.salary_period = date_trunc('month', p_salary_period)::date
      and e.archived_at is null
      and (p_exclude_id is null or e.id <> p_exclude_id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_ttc_task(campaign_id_input bigint, facebook_account_id_input bigint, idempotency_key_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile_record public.user_profiles%rowtype;
  account_record public.user_facebook_accounts%rowtype;
  campaign_record public.ttc_campaigns%rowtype;
  task_record public.ttc_tasks%rowtype;
  normalized_key text := nullif(trim(idempotency_key_input), '');
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để nhận nhiệm vụ.' using errcode = '42501';
  end if;
  if normalized_key is null then
    raise exception 'idempotency_key là bắt buộc.' using errcode = '22023';
  end if;

  select *
  into task_record
  from public.ttc_tasks
  where assignee_user_id = auth.uid()
    and campaign_id = campaign_id_input
    and metadata->>'claim_idempotency_key' = normalized_key;
  if found then
    return jsonb_build_object('task', to_jsonb(task_record), 'already_processed', true);
  end if;

  select *
  into profile_record
  from public.user_profiles
  where user_id = auth.uid()
    and status = 'active';
  if not found then
    raise exception 'Hồ sơ user chưa sẵn sàng để nhận nhiệm vụ TTC.' using errcode = '42501';
  end if;

  select *
  into account_record
  from public.user_facebook_accounts
  where id = facebook_account_id_input
    and user_id = auth.uid()
    and facebook_id is not null
    and facebook_id_status in ('resolved', 'manual_verified')
  for update;
  if not found then
    raise exception 'Tài khoản Facebook chưa được xác minh.' using errcode = '42501';
  end if;

  select *
  into campaign_record
  from public.ttc_campaigns
  where id = campaign_id_input
    and status in ('queued', 'running')
  for update;
  if not found then
    raise exception 'Chiến dịch không còn nhiệm vụ khả dụng.' using errcode = '22023';
  end if;
  if campaign_record.owner_user_id = auth.uid() then
    raise exception 'Không được tự làm nhiệm vụ của chiến dịch mình tạo.' using errcode = '23514';
  end if;
  if exists (
    select 1
    from public.ttc_tasks existing
    where existing.campaign_id = campaign_id_input
      and existing.worker_facebook_id = account_record.facebook_id
      and existing.status in ('assigned', 'submitted', 'verifying', 'completed')
  ) then
    raise exception 'Facebook ID này đã nhận hoặc hoàn thành nhiệm vụ trong chiến dịch.' using errcode = '23505';
  end if;

  select *
  into task_record
  from public.ttc_tasks
  where campaign_id = campaign_id_input
    and status = 'available'
  order by sequence_no
  limit 1
  for update skip locked;
  if not found then
    raise exception 'Không còn nhiệm vụ trống trong chiến dịch này.' using errcode = '22023';
  end if;

  update public.ttc_tasks
  set
    status = 'assigned',
    assignee_user_id = auth.uid(),
    worker_facebook_account_id = account_record.id,
    worker_facebook_id = account_record.facebook_id,
    claimed_at = now(),
    expires_at = case
      when campaign_record.interaction_type_code is not null then now() + make_interval(hours => 24)
      else null
    end,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('claim_idempotency_key', normalized_key)
  where id = task_record.id
  returning * into task_record;

  update public.ttc_campaigns
  set status = case when status = 'queued' then 'running' else status end
  where id = campaign_record.id;

  insert into public.ttc_task_check_logs(task_id, campaign_id, actor_id, check_type, result, before_status, after_status, reason)
  values(task_record.id, campaign_record.id, auth.uid(), 'system', 'pending', 'available', 'assigned', 'User nhận nhiệm vụ');

  return jsonb_build_object('task', to_jsonb(task_record), 'already_processed', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_payment(payment_id_input bigint, reason_input text DEFAULT 'Xác nhận thanh toán'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  package_record public.business_types%rowtype;
  confirmation_timestamp timestamptz := now();
  confirmation_date date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  effective_start_date date;
  calculated_end_date date;
  expected_total numeric;
begin
  actor := private.assert_payment_permission();

  select *
  into payment_record
  from public.payments
  where id = payment_id_input
  for update;

  if not found then
    raise exception 'Không tìm thấy thanh toán.';
  end if;

  if lower(payment_record.payment_status) <> 'pending' then
    raise exception 'Chỉ thanh toán Pending mới được xác nhận.';
  end if;

  if payment_record.transaction_type <> 'standard' then
    raise exception 'Giao dịch điều chỉnh không dùng confirm_payment().';
  end if;

  before_record := payment_record;

  select *
  into customer_record
  from public.customers
  where id = payment_record.customer_id
  for update;

  if not found then
    raise exception 'Khách hàng của thanh toán không tồn tại.';
  end if;

  select *
  into kiosk_record
  from public.kiosks
  where id = payment_record.kiosk_id
  for update;

  if not found then
    raise exception 'Kiosk của thanh toán không tồn tại.';
  end if;

  if kiosk_record.customer_id <> customer_record.id then
    raise exception 'Kiosk không thuộc khách hàng của thanh toán.';
  end if;

  select *
  into package_record
  from public.business_types
  where id = kiosk_record.business_type_id
    and is_active = true;

  if not found then
    raise exception 'Gói dịch vụ không tồn tại hoặc đã ngừng hoạt động.';
  end if;

  if payment_record.months is null or payment_record.months < 1 then
    raise exception 'Số tháng thanh toán không hợp lệ.';
  end if;

  if payment_record.price_per_month is null or payment_record.price_per_month < 0
    or payment_record.discount is null or payment_record.discount < 0
    or payment_record.total_amount is null or payment_record.total_amount <= 0 then
    raise exception 'Giá trị tài chính của thanh toán không hợp lệ.';
  end if;

  expected_total := payment_record.price_per_month * payment_record.months
    - payment_record.discount;

  if payment_record.total_amount <> expected_total then
    raise exception 'Tổng tiền không khớp giá, số tháng và giảm giá.';
  end if;

  if lower(kiosk_record.status) = 'active'
    and kiosk_record.end_date is not null
    and kiosk_record.end_date >= confirmation_date then
    effective_start_date := kiosk_record.end_date + 1;
  else
    effective_start_date := confirmation_date;
  end if;

  calculated_end_date := (
    effective_start_date + make_interval(months => payment_record.months)
  )::date;

  perform set_config('app.payment_workflow_action', 'confirm', true);

  update public.payments
  set
    payment_status = 'completed',
    confirmed_by = actor.user_id,
    confirmed_at = confirmation_timestamp,
    start_date = effective_start_date,
    end_date = calculated_end_date
  where id = payment_record.id
  returning * into payment_record;

  update public.kiosks
  set
    status = 'active',
    start_date = effective_start_date,
    end_date = calculated_end_date
  where id = kiosk_record.id;

  update public.customers
  set
    status = case
      when lower(coalesce(status, '')) = 'pending' then 'active'
      else status
    end,
    total_kiosks = (
      select count(*) from public.kiosks k where k.customer_id = customer_record.id
    )
  where id = customer_record.id;

  perform private.write_payment_audit(
    'confirm',
    to_jsonb(before_record),
    to_jsonb(payment_record),
    reason_input,
    actor
  );

  return jsonb_build_object(
    'payment', to_jsonb(payment_record),
    'kiosk', (
      select to_jsonb(k) from public.kiosks k where k.id = kiosk_record.id
    ),
    'customer', (
      select to_jsonb(c) from public.customers c where c.id = customer_record.id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_payment(payment_id_input bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if private.current_user_role() is distinct from 'admin' then
    raise exception 'Chỉ admin được xác nhận thanh toán trực tiếp.';
  end if;
  perform private.complete_payment(payment_id_input);
end;
$function$

CREATE OR REPLACE FUNCTION public.correct_historical_payment(payment_id_input bigint, start_date_input date, end_date_input date, months_input integer, total_amount_input numeric, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_record public.user_profiles%rowtype;
  before_payment public.payments%rowtype;
  after_payment public.payments%rowtype;
  kiosk_record public.kiosks%rowtype;
  customer_record public.customers%rowtype;
  authoritative_end_date date;
  normalized_reason text := pg_catalog.btrim(coalesce(reason_input, ''));
  kiosk_end_date_before date;
  kiosk_end_date_after date;
begin
  if not public.is_system_admin() then
    raise exception 'Chỉ System Admin được sửa dữ liệu thanh toán lịch sử.'
      using errcode = '42501';
  end if;

  select * into actor_record
  from public.user_profiles
  where user_id = (select auth.uid())
    and status = 'active'
    and web_access_enabled
    and is_system_admin;
  if not found then
    raise exception 'Phiên System Admin không còn hiệu lực.' using errcode = '42501';
  end if;

  if payment_id_input is null or payment_id_input < 1 then
    raise exception 'Thanh toán không hợp lệ.' using errcode = '22023';
  end if;
  if start_date_input is null or end_date_input is null then
    raise exception 'Ngày bắt đầu và ngày kết thúc là bắt buộc.' using errcode = '22023';
  end if;
  if end_date_input < start_date_input then
    raise exception 'Ngày kết thúc không được trước ngày bắt đầu.' using errcode = '22023';
  end if;
  if months_input is null or months_input < 1 then
    raise exception 'Số tháng phải là số nguyên lớn hơn 0.' using errcode = '22023';
  end if;
  if total_amount_input is null or total_amount_input <= 0 then
    raise exception 'Số tiền phải lớn hơn 0.' using errcode = '22023';
  end if;
  if normalized_reason = '' then
    raise exception 'Lý do chỉnh sửa là bắt buộc.' using errcode = '22023';
  end if;
  if pg_catalog.length(normalized_reason) > 1000 then
    raise exception 'Lý do chỉnh sửa không được vượt quá 1000 ký tự.' using errcode = '22023';
  end if;

  select * into before_payment
  from public.payments
  where id = payment_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy thanh toán.' using errcode = 'P0002';
  end if;
  if pg_catalog.lower(coalesce(before_payment.payment_status, '')) <> 'completed'
    or before_payment.confirmed_at is null then
    raise exception 'Chỉ được sửa thanh toán đã hoàn thành và đã ghi nhận thời điểm xác nhận.'
      using errcode = '23514';
  end if;
  if pg_catalog.lower(coalesce(before_payment.transaction_type, 'standard')) = 'adjustment' then
    raise exception 'Không sửa trực tiếp giao dịch điều chỉnh.' using errcode = '23514';
  end if;
  if before_payment.registration_batch_id is not null then
    raise exception 'Thanh toán theo lô phải được đối soát ở cấp lô đăng ký.' using errcode = '23514';
  end if;
  if before_payment.kiosk_id is null then
    raise exception 'Thanh toán không gắn với Kiosk.' using errcode = '23514';
  end if;

  select * into kiosk_record
  from public.kiosks
  where id = before_payment.kiosk_id
  for update;
  if not found then
    raise exception 'Kiosk của thanh toán không tồn tại.' using errcode = 'P0002';
  end if;
  if kiosk_record.customer_id is distinct from before_payment.customer_id then
    raise exception 'Kiosk không thuộc khách hàng của thanh toán.' using errcode = '23514';
  end if;

  select * into customer_record
  from public.customers
  where id = before_payment.customer_id
  for update;
  if not found then
    raise exception 'Khách hàng của thanh toán không tồn tại.' using errcode = 'P0002';
  end if;

  if before_payment.start_date is not distinct from start_date_input
    and before_payment.end_date is not distinct from end_date_input
    and before_payment.months is not distinct from months_input
    and before_payment.total_amount is not distinct from total_amount_input then
    raise exception 'Dữ liệu mới không có thay đổi.' using errcode = '22023';
  end if;

  kiosk_end_date_before := kiosk_record.end_date;
  perform pg_catalog.set_config('app.payment_workflow_action', 'historical_correction', true);

  update public.payments
  set start_date = start_date_input,
      end_date = end_date_input,
      months = months_input,
      total_amount = total_amount_input
  where id = before_payment.id
  returning * into after_payment;

  -- Include both individual renewal payments and completed registration-batch
  -- item periods. This prevents an older corrected payment from shortening a
  -- Kiosk that already has a later completed service period.
  select pg_catalog.max(period_end) into authoritative_end_date
  from (
    select p.end_date as period_end
    from public.payments p
    where p.registration_batch_id is null
      and p.kiosk_id = before_payment.kiosk_id
      and pg_catalog.lower(coalesce(p.payment_status, '')) = 'completed'
      and p.confirmed_at is not null
      and pg_catalog.lower(coalesce(p.transaction_type, 'standard')) <> 'adjustment'
      and p.end_date is not null

    union all

    select i.end_date as period_end
    from public.registration_batch_items i
    join public.registration_batches b on b.id = i.batch_id
    join public.payments p on p.id = b.payment_id
    where i.kiosk_id = before_payment.kiosk_id
      and p.registration_batch_id = b.id
      and pg_catalog.lower(coalesce(p.payment_status, '')) = 'completed'
      and p.confirmed_at is not null
      and i.end_date is not null
  ) completed_periods;

  update public.kiosks k
  set end_date = case
    when k.end_date is not distinct from before_payment.end_date then authoritative_end_date
    when k.end_date is null then authoritative_end_date
    when authoritative_end_date > k.end_date then authoritative_end_date
    else k.end_date
  end
  where k.id = before_payment.kiosk_id
  returning k.end_date into kiosk_end_date_after;

  insert into public.audit_logs (
    actor_id, actor_name, actor_role, actor_type, module, entity, record_id,
    action, before, after, reason
  ) values (
    actor_record.user_id,
    coalesce(actor_record.display_name, actor_record.username, 'System Admin'),
    'system_admin',
    'staff',
    'Payment',
    'payments',
    before_payment.id::text,
    'update',
    pg_catalog.jsonb_build_object(
      'correction_type', 'historical_payment',
      'payment_id', before_payment.id,
      'kiosk_id', before_payment.kiosk_id,
      'customer_id', before_payment.customer_id,
      'start_date', before_payment.start_date,
      'end_date', before_payment.end_date,
      'months', before_payment.months,
      'total_amount', before_payment.total_amount,
      'kiosk_end_date', kiosk_end_date_before
    ),
    pg_catalog.jsonb_build_object(
      'correction_type', 'historical_payment',
      'payment_id', after_payment.id,
      'kiosk_id', after_payment.kiosk_id,
      'customer_id', after_payment.customer_id,
      'start_date', after_payment.start_date,
      'end_date', after_payment.end_date,
      'months', after_payment.months,
      'total_amount', after_payment.total_amount,
      'kiosk_end_date', kiosk_end_date_after
    ),
    normalized_reason
  );

  return pg_catalog.jsonb_build_object(
    'payment', pg_catalog.to_jsonb(after_payment),
    'kiosk', (
      select pg_catalog.to_jsonb(k)
      from public.kiosks k
      where k.id = before_payment.kiosk_id
    ),
    'audit', pg_catalog.jsonb_build_object(
      'reason', normalized_reason,
      'corrected_by', actor_record.user_id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_payment_adjustment(original_payment_id_input bigint, amount_delta_input numeric, service_month_delta_input integer, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  original_record public.payments%rowtype;
  adjustment_record public.payments%rowtype;
  kiosk_record public.kiosks%rowtype;
  confirmation_timestamp timestamptz := now();
  confirmation_date date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  adjusted_start_date date;
  adjusted_end_date date;
  previous_start_date date;
  previous_end_date date;
begin
  actor := private.assert_payment_permission();

  if nullif(trim(reason_input), '') is null then
    raise exception 'Lý do điều chỉnh là bắt buộc.';
  end if;

  if amount_delta_input is null or amount_delta_input = 0 then
    raise exception 'Số tiền điều chỉnh phải khác 0.';
  end if;

  select *
  into original_record
  from public.payments
  where id = original_payment_id_input
  for update;

  if not found
    or lower(original_record.payment_status) <> 'completed'
    or original_record.confirmed_at is null then
    raise exception 'Chỉ được điều chỉnh thanh toán Completed hợp lệ.';
  end if;

  if original_record.transaction_type <> 'standard' then
    raise exception 'Không được tạo điều chỉnh từ một giao dịch điều chỉnh.';
  end if;

  if exists (
    select 1
    from public.payments p
    where p.adjusts_payment_id = original_record.id
      and p.transaction_type = 'adjustment'
      and lower(p.payment_status) = 'completed'
  ) then
    raise exception 'Thanh toán này đã có giao dịch điều chỉnh.';
  end if;

  select *
  into kiosk_record
  from public.kiosks
  where id = original_record.kiosk_id
  for update;

  if not found then
    raise exception 'Kiosk của thanh toán không tồn tại.';
  end if;

  if service_month_delta_input <> 0 and exists (
    select 1
    from public.payments p
    where p.kiosk_id = original_record.kiosk_id
      and lower(p.payment_status) = 'completed'
      and p.confirmed_at is not null
      and p.transaction_type = 'standard'
      and (p.confirmed_at, p.id) > (original_record.confirmed_at, original_record.id)
  ) then
    raise exception 'Chỉ được điều chỉnh kỳ hạn của thanh toán dịch vụ mới nhất.';
  end if;

  if service_month_delta_input < 0
    and abs(service_month_delta_input) > original_record.months then
    raise exception 'Số tháng đảo ngược vượt quá số tháng của thanh toán gốc.';
  end if;

  if service_month_delta_input is null then
    raise exception 'Số tháng điều chỉnh không hợp lệ.';
  end if;

  if service_month_delta_input < 0
    and (original_record.start_date is null or original_record.end_date is null) then
    raise exception 'Thanh toán gốc thiếu kỳ hạn để đảo ngược.';
  end if;

  adjusted_start_date := kiosk_record.start_date;
  adjusted_end_date := kiosk_record.end_date;

  if service_month_delta_input > 0 then
    adjusted_start_date := case
      when lower(kiosk_record.status) = 'active'
        and kiosk_record.end_date is not null
        and kiosk_record.end_date >= confirmation_date
      then kiosk_record.end_date + 1
      else confirmation_date
    end;
    adjusted_end_date := (
      adjusted_start_date + make_interval(months => service_month_delta_input)
    )::date;
  elsif service_month_delta_input < 0 then
    if abs(service_month_delta_input) = original_record.months then
      select p.start_date, p.end_date
      into previous_start_date, previous_end_date
      from public.payments p
      where p.kiosk_id = original_record.kiosk_id
        and lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
        and p.transaction_type = 'standard'
        and (p.confirmed_at, p.id) < (original_record.confirmed_at, original_record.id)
      order by p.confirmed_at desc, p.id desc
      limit 1;

      adjusted_start_date := previous_start_date;
      adjusted_end_date := previous_end_date;
    else
      adjusted_end_date := (
        kiosk_record.end_date
        - make_interval(months => abs(service_month_delta_input))
      )::date;
    end if;
  end if;

  perform set_config('app.payment_workflow_action', 'adjustment', true);

  insert into public.payments(
    customer_id,
    kiosk_id,
    start_date,
    end_date,
    months,
    price_per_month,
    discount,
    discount_reason,
    total_amount,
    payment_method,
    payment_status,
    confirmed_at,
    confirmed_by,
    note,
    transaction_type,
    adjusts_payment_id,
    adjustment_reason,
    service_month_delta
  )
  values(
    original_record.customer_id,
    original_record.kiosk_id,
    adjusted_start_date,
    adjusted_end_date,
    greatest(abs(service_month_delta_input), 1),
    0,
    0,
    null,
    amount_delta_input,
    original_record.payment_method,
    'completed',
    confirmation_timestamp,
    actor.user_id,
    trim(reason_input),
    'adjustment',
    original_record.id,
    trim(reason_input),
    service_month_delta_input
  )
  returning * into adjustment_record;

  update public.kiosks
  set
    start_date = case
      when service_month_delta_input <> 0 then adjusted_start_date
      else start_date
    end,
    end_date = adjusted_end_date,
    status = case
      when service_month_delta_input > 0 then 'active'
      when service_month_delta_input < 0 and adjusted_end_date is null then 'expired'
      when adjusted_end_date is not null and adjusted_end_date < confirmation_date then 'expired'
      when service_month_delta_input < 0 then 'active'
      else status
    end
  where id = original_record.kiosk_id;

  perform private.write_payment_audit(
    'adjustment',
    to_jsonb(original_record),
    to_jsonb(adjustment_record),
    reason_input,
    actor
  );

  return jsonb_build_object(
    'originalPayment', to_jsonb(original_record),
    'adjustment', to_jsonb(adjustment_record),
    'kiosk', (
      select to_jsonb(k) from public.kiosks k where k.id = original_record.kiosk_id
    ),
    'customer', (
      select to_jsonb(c) from public.customers c where c.id = original_record.customer_id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_ttc_campaign(interaction_type_input text, target_url_input text, target_quantity_input integer, idempotency_key_input text, target_facebook_id_input text DEFAULT NULL::text, target_label_input text DEFAULT NULL::text, comment_options_input jsonb DEFAULT '[]'::jsonb, metadata_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile_record public.user_profiles%rowtype;
  type_record public.ttc_interaction_types%rowtype;
  campaign_record public.ttc_campaigns%rowtype;
  ledger_result jsonb;
  task_index integer;
  normalized_key text := nullif(trim(idempotency_key_input), '');
  total_cost numeric(14, 2);
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để tạo chiến dịch.' using errcode = '42501';
  end if;
  if normalized_key is null then
    raise exception 'idempotency_key là bắt buộc.' using errcode = '22023';
  end if;

  select *
  into campaign_record
  from public.ttc_campaigns
  where owner_user_id = auth.uid()
    and idempotency_key = normalized_key;
  if found then
    return jsonb_build_object('campaign', to_jsonb(campaign_record), 'already_processed', true);
  end if;

  select *
  into profile_record
  from public.user_profiles
  where user_id = auth.uid()
    and status = 'active';
  if not found then
    raise exception 'Hồ sơ user chưa sẵn sàng để tạo chiến dịch TTC.' using errcode = '42501';
  end if;

  select *
  into type_record
  from public.ttc_interaction_types
  where code = interaction_type_input
    and is_active = true;
  if not found then
    raise exception 'Loại tương tác TTC không hợp lệ hoặc đã tắt.' using errcode = '22023';
  end if;
  if target_quantity_input < type_record.min_quantity or target_quantity_input > type_record.max_quantity then
    raise exception 'Số lượng nhiệm vụ không nằm trong giới hạn cấu hình.' using errcode = '22023';
  end if;
  if nullif(trim(target_url_input), '') is null then
    raise exception 'Link mục tiêu là bắt buộc.' using errcode = '22023';
  end if;
  if target_facebook_id_input is not null and target_facebook_id_input !~ '^[0-9]+$' then
    raise exception 'Facebook ID mục tiêu chỉ được chứa chữ số.' using errcode = '22023';
  end if;

  total_cost := type_record.unit_cost * target_quantity_input;

  insert into public.ttc_campaigns(
    owner_user_id,
    interaction_type_code,
    target_url,
    target_facebook_id,
    target_label,
    comment_options,
    target_quantity,
    unit_cost,
    worker_reward,
    reserved_amount,
    status,
    idempotency_key,
    metadata
  )
  values(
    auth.uid(),
    type_record.code,
    trim(target_url_input),
    nullif(trim(target_facebook_id_input), ''),
    nullif(trim(target_label_input), ''),
    coalesce(comment_options_input, '[]'::jsonb),
    target_quantity_input,
    type_record.unit_cost,
    type_record.worker_reward,
    total_cost,
    'queued',
    normalized_key,
    coalesce(metadata_input, '{}'::jsonb)
  )
  returning * into campaign_record;

  ledger_result := private.post_wallet_ledger(
    auth.uid(),
    -total_cost,
    'spend_campaign',
    'ttc_campaigns',
    campaign_record.id::text,
    'ttc_campaign:create:' || normalized_key,
    'Tạo chiến dịch TTC #' || campaign_record.id,
    'Tạo chiến dịch TTC',
    jsonb_build_object('campaign_id', campaign_record.id, 'interaction_type', type_record.code),
    auth.uid(),
    'user'
  );

  for task_index in 1..target_quantity_input loop
    insert into public.ttc_tasks(campaign_id, sequence_no)
    values (campaign_record.id, task_index);
  end loop;

  perform private.write_ttc_audit(
    'TTC',
    'create_campaign',
    'ttc_campaigns',
    campaign_record.id::text,
    null,
    to_jsonb(campaign_record),
    'Tạo chiến dịch TTC'
  );

  return jsonb_build_object(
    'campaign', to_jsonb(campaign_record),
    'wallet', ledger_result->'wallet',
    'task_count', target_quantity_input,
    'already_processed', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_ttc_verify_job(task_id_input bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  task_record public.ttc_tasks%rowtype;
  campaign_record public.ttc_campaigns%rowtype;
  facebook_account_record public.user_facebook_accounts%rowtype;
  profile_record public.user_profiles%rowtype;
  existing_job public.ttc_verify_jobs%rowtype;
  job_record public.ttc_verify_jobs%rowtype;
  normalized_target text;
  batch_key_value text;
  queued_count integer := 0;
  online_checker_count integer := 0;
  estimate_seconds integer := 120;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để gửi auto check.' using errcode = '42501';
  end if;

  select *
  into task_record
  from public.ttc_tasks
  where id = task_id_input
    and assignee_user_id = auth.uid()
  for update;
  if not found then
    raise exception 'Không tìm thấy nhiệm vụ của bạn.' using errcode = '42501';
  end if;

  if task_record.status = 'completed' then
    return jsonb_build_object(
      'queued', false,
      'alreadyProcessed', true,
      'message', 'Nhiệm vụ đã hoàn thành.'
    );
  end if;

  if task_record.status not in ('assigned', 'submitted', 'verifying') then
    raise exception 'Nhiệm vụ chưa ở trạng thái có thể auto check.' using errcode = '22023';
  end if;

  select *
  into campaign_record
  from public.ttc_campaigns
  where id = task_record.campaign_id
  for update;
  if not found then
    raise exception 'Không tìm thấy chiến dịch TTC.' using errcode = '22023';
  end if;

  if campaign_record.status not in ('queued', 'running') then
    raise exception 'Chiến dịch không còn nhận kết quả nhiệm vụ.' using errcode = '22023';
  end if;

  select *
  into existing_job
  from public.ttc_verify_jobs
  where task_id = task_record.id
    and status in ('queued', 'batched', 'claimed', 'verifying')
  order by created_at desc
  limit 1;

  if found then
    update public.ttc_tasks
    set status = 'verifying',
        submitted_at = coalesce(submitted_at, now())
    where id = task_record.id
      and status in ('assigned', 'submitted', 'verifying');

    return jsonb_build_object(
      'queued', true,
      'job', to_jsonb(existing_job),
      'estimatedWaitSeconds', coalesce(existing_job.estimated_wait_seconds, 120),
      'message', 'Nhiệm vụ đã nằm trong hàng chờ kiểm tra.'
    );
  end if;

  select *
  into facebook_account_record
  from public.user_facebook_accounts
  where id = task_record.worker_facebook_account_id;

  select *
  into profile_record
  from public.user_profiles
  where user_id = task_record.assignee_user_id;

  normalized_target := lower(regexp_replace(trim(campaign_record.target_url), '\s+', '', 'g'));
  batch_key_value := md5(normalized_target || ':' || campaign_record.interaction_type_code);

  select count(*)
  into queued_count
  from public.ttc_verify_jobs
  where status in ('queued', 'batched', 'claimed', 'verifying');

  select greatest(count(*), 1)
  into online_checker_count
  from public.ttc_checker_accounts
  where status in ('online', 'busy');

  estimate_seconds := greatest(30, least(900, 30 * ceil((queued_count + 1)::numeric / online_checker_count)::integer));

  update public.ttc_tasks
  set
    status = 'verifying',
    submitted_at = coalesce(submitted_at, now()),
    evidence = case
      when coalesce(evidence, '{}'::jsonb) = '{}'::jsonb
        then jsonb_build_object('submitted_from', 'verify_queue', 'queued_at', now())
      else evidence || jsonb_build_object('queued_at', now())
    end
  where id = task_record.id
  returning * into task_record;

  insert into public.ttc_verify_jobs(
    task_id,
    campaign_id,
    assignee_user_id,
    action_type,
    target_url,
    target_facebook_id,
    target_label,
    worker_facebook_id,
    worker_facebook_urls,
    worker_facebook_usernames,
    worker_facebook_names,
    batch_key,
    estimated_wait_seconds
  )
  values(
    task_record.id,
    task_record.campaign_id,
    task_record.assignee_user_id,
    regexp_replace(campaign_record.interaction_type_code, '^facebook_', ''),
    campaign_record.target_url,
    campaign_record.target_facebook_id,
    campaign_record.target_label,
    task_record.worker_facebook_id,
    array_remove(array[
      facebook_account_record.facebook_url_original,
      facebook_account_record.facebook_url_normalized,
      case
        when facebook_account_record.facebook_id is not null then 'https://www.facebook.com/profile.php?id=' || facebook_account_record.facebook_id
        else null
      end
    ], null),
    array_remove(array[
      nullif(lower(regexp_replace(coalesce(facebook_account_record.facebook_url_normalized, ''), '^https?://(www\.)?facebook\.com/([^/?#]+).*$','\2')), ''),
      nullif(lower(regexp_replace(coalesce(facebook_account_record.facebook_url_original, ''), '^https?://(www\.)?facebook\.com/([^/?#]+).*$','\2')), '')
    ], null),
    array_remove(array[
      nullif(facebook_account_record.metadata->>'facebook_name', ''),
      nullif(facebook_account_record.metadata->>'name', ''),
      nullif(profile_record.display_name, ''),
      nullif(profile_record.metadata->>'display_name', ''),
      nullif(profile_record.metadata->>'facebook_name', ''),
      nullif(profile_record.metadata->>'name', '')
    ], null),
    batch_key_value,
    estimate_seconds
  )
  returning * into job_record;

  insert into public.ttc_task_check_logs(task_id, campaign_id, actor_id, check_type, result, before_status, after_status, reason, metadata)
  values(
    task_record.id,
    task_record.campaign_id,
    auth.uid(),
    'auto',
    'pending',
    'submitted',
    'verifying',
    'User gửi nhiệm vụ vào hàng chờ auto check Facebook',
    jsonb_build_object('job_id', job_record.id, 'batch_key', job_record.batch_key)
  );

  return jsonb_build_object(
    'queued', true,
    'job', to_jsonb(job_record),
    'estimatedWaitSeconds', estimate_seconds,
    'message', 'Đang xếp hàng kiểm tra Facebook.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_my_user_profile(display_name_input text DEFAULT NULL::text, phone_input text DEFAULT NULL::text, email_input text DEFAULT NULL::text, metadata_input jsonb DEFAULT '{}'::jsonb, username_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile_record public.user_profiles%rowtype;
  wallet_record public.wallets%rowtype;
  normalized_display_name text := nullif(trim(display_name_input), '');
  normalized_phone text := nullif(trim(phone_input), '');
  normalized_email text := nullif(lower(trim(email_input)), '');
  normalized_username text := nullif(lower(trim(username_input)), '');
  next_status text;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để tạo hồ sơ.' using errcode = '42501';
  end if;
  if normalized_phone is not null and normalized_phone !~ '^\+?[0-9 .()-]{9,20}$' then
    raise exception 'Số điện thoại không hợp lệ.' using errcode = '22023';
  end if;
  if normalized_username is not null and normalized_username !~ '^[a-z0-9._-]{3,40}$' then
    raise exception 'Username không hợp lệ.' using errcode = '22023';
  end if;

  select *
  into profile_record
  from public.user_profiles
  where user_id = auth.uid()
  for update;

  if found and profile_record.status = 'locked' then
    raise exception 'Tài khoản user đã bị khóa.' using errcode = '42501';
  end if;

  next_status := case
    when normalized_display_name is not null and normalized_phone is not null then 'active'
    else 'pending_profile'
  end;

  insert into public.user_profiles(
    user_id,
    username,
    display_name,
    phone,
    email,
    status,
    metadata
  )
  values(
    auth.uid(),
    normalized_username,
    normalized_display_name,
    normalized_phone,
    normalized_email,
    next_status,
    coalesce(metadata_input, '{}'::jsonb)
  )
  on conflict (user_id) do update
  set
    username = coalesce(excluded.username, public.user_profiles.username),
    display_name = coalesce(excluded.display_name, public.user_profiles.display_name),
    phone = coalesce(excluded.phone, public.user_profiles.phone),
    email = coalesce(excluded.email, public.user_profiles.email),
    status = case
      when public.user_profiles.status = 'locked' then public.user_profiles.status
      when coalesce(excluded.display_name, public.user_profiles.display_name) is not null
        and coalesce(excluded.phone, public.user_profiles.phone) is not null then 'active'
      else 'pending_profile'
    end,
    metadata = coalesce(public.user_profiles.metadata, '{}'::jsonb) || coalesce(excluded.metadata, '{}'::jsonb),
    updated_at = now()
  returning * into profile_record;

  wallet_record := private.ensure_wallet(auth.uid());

  perform private.write_ttc_audit(
    'User',
    'ensure_profile',
    'user_profiles',
    profile_record.user_id::text,
    null,
    jsonb_build_object(
      'user_id', profile_record.user_id,
      'status', profile_record.status,
      'has_username', profile_record.username is not null,
      'has_phone', profile_record.phone is not null,
      'has_email', profile_record.email is not null
    ),
    'User cập nhật hồ sơ'
  );

  return jsonb_build_object(
    'profile', to_jsonb(profile_record),
    'wallet', to_jsonb(wallet_record)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_my_user_profile(display_name_input text DEFAULT NULL::text, phone_input text DEFAULT NULL::text, email_input text DEFAULT NULL::text, metadata_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile_record public.user_profiles%rowtype;
  wallet_record public.wallets%rowtype;
  normalized_display_name text := nullif(trim(display_name_input), '');
  normalized_phone text := nullif(trim(phone_input), '');
  normalized_email text := nullif(lower(trim(email_input)), '');
  next_status text;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để tạo hồ sơ.' using errcode = '42501';
  end if;
  if normalized_phone is not null and normalized_phone !~ '^\+?[0-9 .()-]{9,20}$' then
    raise exception 'Số điện thoại không hợp lệ.' using errcode = '22023';
  end if;

  select *
  into profile_record
  from public.user_profiles
  where user_id = auth.uid()
  for update;

  if found and profile_record.status = 'locked' then
    raise exception 'Tài khoản user đã bị khóa.' using errcode = '42501';
  end if;

  next_status := case
    when normalized_display_name is not null and normalized_phone is not null then 'active'
    else 'pending_profile'
  end;

  insert into public.user_profiles(
    user_id,
    display_name,
    phone,
    email,
    status,
    metadata
  )
  values(
    auth.uid(),
    normalized_display_name,
    normalized_phone,
    normalized_email,
    next_status,
    coalesce(metadata_input, '{}'::jsonb)
  )
  on conflict (user_id) do update
  set
    display_name = coalesce(excluded.display_name, public.user_profiles.display_name),
    phone = coalesce(excluded.phone, public.user_profiles.phone),
    email = coalesce(excluded.email, public.user_profiles.email),
    status = case
      when public.user_profiles.status = 'locked' then public.user_profiles.status
      when coalesce(excluded.display_name, public.user_profiles.display_name) is not null
        and coalesce(excluded.phone, public.user_profiles.phone) is not null then 'active'
      else 'pending_profile'
    end,
    metadata = coalesce(public.user_profiles.metadata, '{}'::jsonb) || coalesce(excluded.metadata, '{}'::jsonb),
    updated_at = now()
  returning * into profile_record;

  wallet_record := private.ensure_wallet(auth.uid());

  perform private.write_ttc_audit(
    'User',
    'ensure_profile',
    'user_profiles',
    profile_record.user_id::text,
    null,
    jsonb_build_object(
      'user_id', profile_record.user_id,
      'status', profile_record.status,
      'has_phone', profile_record.phone is not null,
      'has_email', profile_record.email is not null
    ),
    'User cập nhật hồ sơ'
  );

  return jsonb_build_object(
    'profile', to_jsonb(profile_record),
    'wallet', to_jsonb(wallet_record)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_registration_payos_order(payment_id_input bigint, order_code_input bigint, failure_stage_input text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare changed integer;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'Chỉ API server được cập nhật PayOS order đăng ký.' using errcode = '42501';
  end if;
  update public.payos_orders o set status = 'failed', active_slot = null,
    error = left(coalesce(failure_stage_input, 'PAYOS_FAILURE'), 100),
    processed_at = coalesce(o.processed_at, pg_catalog.now()), updated_at = pg_catalog.now()
  where o.payment_id = payment_id_input and o.order_code = order_code_input
    and o.purpose = 'crm_payment' and o.status = 'pending' and o.active_slot is true
    and o.checkout_url is null and exists (select 1 from public.payments p
      where p.id = o.payment_id and p.payment_status = 'pending');
  get diagnostics changed = row_count;
  return changed = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_current_app_profile()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  staff_record public.user_roles%rowtype;
  user_record public.user_profiles%rowtype;
  wallet_record public.wallets%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập.' using errcode = '42501';
  end if;

  select *
  into staff_record
  from public.user_roles ur
  where ur.user_id = auth.uid();

  if found then
    return jsonb_build_object(
      'profile_type', 'staff',
      'user_id', staff_record.user_id,
      'username', staff_record.username,
