CREATE OR REPLACE FUNCTION public.prepare_registration_payment_for_payos(request_id_input bigint, phone_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request_record public.registration_requests%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  payment_record public.payments%rowtype;
  business_type_record public.business_types%rowtype;
  normalized_phone_input text;
  normalized_request_phone text;
  group_member_base_url text;
begin
  normalized_phone_input := regexp_replace(coalesce(phone_input, ''), '[^0-9+]', '', 'g');
  if normalized_phone_input = '' then
    raise exception 'Số điện thoại xác nhận không hợp lệ.' using errcode = '22023';
  end if;

  select *
  into request_record
  from public.registration_requests
  where id = request_id_input
  for update;

  if not found then
    raise exception 'Không tìm thấy yêu cầu đăng ký.';
  end if;

  normalized_request_phone := regexp_replace(coalesce(request_record.phone, ''), '[^0-9+]', '', 'g');
  if normalized_request_phone <> normalized_phone_input then
    raise exception 'Số điện thoại không khớp yêu cầu đăng ký.' using errcode = '42501';
  end if;

  if lower(coalesce(request_record.status, 'pending')) not in ('pending', 'approved') then
    raise exception 'Yêu cầu đăng ký không còn ở trạng thái có thể thanh toán.' using errcode = '22023';
  end if;

  if request_record.payment_id is not null then
    select *
    into payment_record
    from public.payments
    where id = request_record.payment_id
    for update;

    if not found then
      raise exception 'Không tìm thấy thanh toán của yêu cầu đăng ký.';
    end if;

    return jsonb_build_object(
      'request', to_jsonb(request_record),
      'payment', to_jsonb(payment_record)
    );
  end if;

  if request_record.customer_id is not null then
    select *
    into customer_record
    from public.customers
    where id = request_record.customer_id
    for update;
  end if;

  if customer_record.id is null and nullif(request_record.facebook_id, '') is not null then
    select *
    into customer_record
    from public.customers c
    where c.facebook_id = request_record.facebook_id
    order by c.id
    limit 1
    for update;
  end if;

  if customer_record.id is null then
    insert into public.customers(
      facebook_name, facebook_id, facebook_link, phone, address,
      status, total_kiosks, total_paid, note
    )
    values(
      request_record.facebook_name,
      nullif(request_record.facebook_id, ''),
      request_record.facebook_link,
      request_record.phone,
      request_record.address,
      'pending',
      0,
      0,
      request_record.note
    )
    returning * into customer_record;
  end if;

  select *
  into business_type_record
  from public.business_types
  where id = request_record.business_type_id
    and is_active = true;
  if not found then
    raise exception 'Loại hình kinh doanh không tồn tại hoặc đã ngừng hoạt động.' using errcode = '22023';
  end if;

  select case
    when nullif(trim(s.value), '') ~ '^[0-9]+$'
      then 'https://www.facebook.com/groups/' || trim(s.value) || '/user/'
    else null
  end
  into group_member_base_url
  from public.settings s
  where s.key = 'facebook_group_id';

  if request_record.kiosk_id is not null then
    select *
    into kiosk_record
    from public.kiosks
    where id = request_record.kiosk_id
    for update;
  end if;

  if kiosk_record.id is null and nullif(request_record.facebook_id, '') is not null then
    select *
    into kiosk_record
    from public.kiosks k
    where k.facebook_id = request_record.facebook_id
    order by k.id
    limit 1
    for update;
  end if;

  if kiosk_record.id is null then
    insert into public.kiosks(
      customer_id, facebook_name, facebook_id, facebook_link,
      facebook_group_link, category_id, business_type_id, service_name,
      start_date, end_date, status, auto_approve,
      total_paid, kiosk_total_paid, last_payment_date, note, is_primary
    )
    values(
      customer_record.id,
      request_record.facebook_name,
      nullif(request_record.facebook_id, ''),
      request_record.facebook_link,
      case
        when group_member_base_url is null or nullif(request_record.facebook_id, '') is null then null
        else group_member_base_url || request_record.facebook_id || '/'
      end,
      business_type_record.category_id,
      business_type_record.id,
      business_type_record.name,
      null,
      null,
      'pending',
      false,
      0,
      0,
      null,
      request_record.note,
      not exists (
        select 1 from public.kiosks existing
        where existing.customer_id = customer_record.id and existing.is_primary
      )
    )
    returning * into kiosk_record;
  elsif kiosk_record.customer_id <> customer_record.id then
    raise exception 'Facebook ID kiosk đã thuộc về một khách hàng khác.' using errcode = '23505';
  end if;

  insert into public.payments(
    customer_id, kiosk_id, start_date, end_date, months,
    price_per_month, discount, discount_reason, total_amount,
    payment_method, payment_status, transaction_type, note
  )
  values(
    customer_record.id,
    kiosk_record.id,
    null,
    null,
    request_record.months,
    coalesce(request_record.price_per_month, business_type_record.price_per_month),
    coalesce(request_record.discount, 0),
    request_record.discount_reason,
    request_record.total_amount,
    coalesce(nullif(request_record.payment_method, ''), 'transfer'),
    'pending',
    'standard',
    request_record.note
  )
  returning * into payment_record;

  update public.registration_requests
  set
    customer_id = customer_record.id,
    kiosk_id = kiosk_record.id,
    payment_id = payment_record.id,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'materialized_for_payos_at', pg_catalog.now()
    )
  where id = request_record.id
  returning * into request_record;

  update public.customers c
  set total_kiosks = (
    select count(*)::integer
    from public.kiosks k
    where k.customer_id = c.id
  )
  where c.id = customer_record.id
  returning * into customer_record;

  return jsonb_build_object(
    'request', to_jsonb(request_record),
    'customer', to_jsonb(customer_record),
    'kiosk', to_jsonb(kiosk_record),
    'payment', to_jsonb(payment_record)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_registration_payment_v2(request_ids_input bigint[], phone_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_phone text := pg_catalog.regexp_replace(coalesce(phone_input, ''), '[^0-9+]', '', 'g');
  request_count integer;
  request_record public.registration_requests%rowtype;
  batch_record public.registration_batches%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  package_record public.business_types%rowtype;
  payment_record public.payments%rowtype;
  first_kiosk_id bigint;
  authoritative_total numeric := 0;
  item_total numeric;
  group_member_base_url text;
  result_items jsonb := '[]'::jsonb;
  batch_key text;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'Chỉ API server được chuẩn bị thanh toán đăng ký.' using errcode = '42501';
  end if;

  request_count := coalesce(pg_catalog.array_length(request_ids_input, 1), 0);
  if request_count < 1 or request_count > 20 then
    raise exception 'Lô đăng ký phải có từ 1 đến 20 Kiosk.' using errcode = '22023';
  end if;
  if normalized_phone = '' then
    raise exception 'Số điện thoại xác nhận không hợp lệ.' using errcode = '22023';
  end if;
  if (select pg_catalog.count(distinct value) from pg_catalog.unnest(request_ids_input) value) <> request_count then
    raise exception 'Danh sách yêu cầu đăng ký bị trùng.' using errcode = '22023';
  end if;

  batch_key := 'registration-batch:' || (
    select pg_catalog.string_agg(value::text, ',' order by value)
    from pg_catalog.unnest(request_ids_input) value
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(batch_key, 0));

  perform 1
  from public.registration_requests
  where id = any(request_ids_input)
  order by id
  for update;

  select pg_catalog.count(*)
  into request_count
  from public.registration_requests
  where id = any(request_ids_input);

  if request_count <> pg_catalog.array_length(request_ids_input, 1) then
    raise exception 'Không tìm thấy đầy đủ yêu cầu đăng ký.' using errcode = 'P0002';
  end if;
  if exists (
    select 1
    from public.registration_requests
    where id = any(request_ids_input)
      and pg_catalog.regexp_replace(coalesce(phone, ''), '[^0-9+]', '', 'g') <> normalized_phone
  ) then
    raise exception 'Số điện thoại không khớp lô đăng ký.' using errcode = '42501';
  end if;
  if exists (
    select 1
    from public.registration_requests
    where id = any(request_ids_input)
      and pg_catalog.lower(coalesce(status, 'pending')) not in ('awaiting_payment', 'pending', 'approved')
  ) then
    raise exception 'Lô đăng ký không còn có thể thanh toán.' using errcode = '22023';
  end if;

  select b.*
  into batch_record
  from public.registration_batches b
  join public.registration_requests r on r.registration_batch_id = b.id
  where r.id = any(request_ids_input)
  order by b.id
  limit 1
  for update of b;

  if found then
    if exists (
      select 1
      from public.registration_requests
      where id = any(request_ids_input)
        and registration_batch_id is distinct from batch_record.id
    ) then
      raise exception 'Yêu cầu đã thuộc lô đăng ký khác.' using errcode = '23505';
    end if;
    select * into payment_record from public.payments where id = batch_record.payment_id for update;
    return pg_catalog.jsonb_build_object(
      'batch', pg_catalog.to_jsonb(batch_record),
      'payment', pg_catalog.to_jsonb(payment_record),
      'items', (
        select coalesce(
          pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'requestId', i.registration_request_id,
            'kioskId', i.kiosk_id,
            'name', k.facebook_name,
            'months', i.months,
            'pricePerMonth', i.price_per_month,
            'discount', i.discount,
            'totalAmount', i.total_amount
          ) order by i.id),
          '[]'::jsonb
        )
        from public.registration_batch_items i
        join public.kiosks k on k.id = i.kiosk_id
        where i.batch_id = batch_record.id
      ),
      'reused', true
    );
  end if;

  select *
  into customer_record
  from public.customers
  where pg_catalog.regexp_replace(coalesce(phone, ''), '[^0-9+]', '', 'g') = normalized_phone
  order by id
  limit 1
  for update;

  if not found then
    select *
    into request_record
    from public.registration_requests
    where id = any(request_ids_input)
    order by id
    limit 1;
    insert into public.customers(
      facebook_name, facebook_id, facebook_link, phone, address,
      status, total_kiosks, total_paid, note
    ) values (
      request_record.facebook_name,
      nullif(request_record.facebook_id, ''),
      request_record.facebook_link,
      request_record.phone,
      request_record.address,
      'pending', 0, 0, request_record.note
    ) returning * into customer_record;
  end if;

  insert into public.registration_batches(customer_id, phone, status, total_amount)
  values (customer_record.id, normalized_phone, 'pending', 0)
  returning * into batch_record;

  select case
    when nullif(pg_catalog.btrim(s.value), '') ~ '^[0-9]+$'
      then 'https://www.facebook.com/groups/' || pg_catalog.btrim(s.value) || '/user/'
    else null
  end
  into group_member_base_url
  from public.settings s
  where s.key = 'facebook_group_id';

  for request_record in
    select *
    from public.registration_requests
    where id = any(request_ids_input)
    order by id
    for update
  loop
    select *
    into package_record
    from public.business_types
    where id = request_record.business_type_id
      and is_active = true
    for share;

    if not found or package_record.price_per_month is null or package_record.price_per_month < 0 then
      raise exception 'Loại hình kinh doanh không tồn tại, không hoạt động hoặc thiếu giá.' using errcode = '22023';
    end if;
    if request_record.months is null
      or request_record.months < 1
      or coalesce(request_record.discount, 0) <> 0 then
      raise exception 'Thời hạn không hợp lệ hoặc đăng ký công khai chứa giảm giá không được phép.' using errcode = '22023';
    end if;

    item_total := package_record.price_per_month * request_record.months;
    if item_total <= 0 or request_record.total_amount is distinct from item_total then
      raise exception 'Tổng tiền Kiosk không khớp giá hiện hành.' using errcode = '22023';
    end if;

    if request_record.kiosk_id is not null then
      select * into kiosk_record from public.kiosks where id = request_record.kiosk_id for update;
    else
      kiosk_record := null;
    end if;

    if kiosk_record.id is null then
      insert into public.kiosks(
        customer_id, facebook_name, facebook_id, facebook_link, facebook_group_link,
        category_id, business_type_id, service_name, start_date, end_date,
        status, auto_approve, total_paid, kiosk_total_paid, last_payment_date,
        note, is_primary
      ) values (
        customer_record.id,
        request_record.facebook_name,
        nullif(request_record.facebook_id, ''),
        request_record.facebook_link,
        case
          when group_member_base_url is null or nullif(request_record.facebook_id, '') is null then null
          else group_member_base_url || request_record.facebook_id || '/'
        end,
        package_record.category_id,
        package_record.id,
        package_record.name,
        null, null, 'pending', false, 0, 0, null,
        request_record.note,
        not exists (
          select 1 from public.kiosks k where k.customer_id = customer_record.id and k.is_primary
        )
      ) returning * into kiosk_record;
    elsif kiosk_record.customer_id <> customer_record.id then
      raise exception 'Kiosk không thuộc khách hàng của lô đăng ký.' using errcode = '23505';
    end if;

    first_kiosk_id := coalesce(first_kiosk_id, kiosk_record.id);

    insert into public.registration_batch_items(
      batch_id, registration_request_id, kiosk_id, business_type_id,
      months, paid_months, bonus_months, effective_service_months,
      price_per_month, discount, total_amount, promotion_eligible
    ) values (
      batch_record.id, request_record.id, kiosk_record.id, package_record.id,
      request_record.months, request_record.months, 0, request_record.months,
      package_record.price_per_month, 0, item_total, false
    );

    update public.registration_requests
    set customer_id = customer_record.id,
        kiosk_id = kiosk_record.id,
        registration_batch_id = batch_record.id,
        metadata = coalesce(metadata, '{}'::jsonb)
          || pg_catalog.jsonb_build_object('materialized_for_batch_payos_at', pg_catalog.now())
    where id = request_record.id;

    authoritative_total := authoritative_total + item_total;
    result_items := result_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'requestId', request_record.id,
      'kioskId', kiosk_record.id,
      'name', kiosk_record.facebook_name,
      'months', request_record.months,
      'pricePerMonth', package_record.price_per_month,
      'discount', 0,
      'totalAmount', item_total
    ));
  end loop;

  if authoritative_total <= 0 then
    raise exception 'Tổng tiền lô đăng ký không hợp lệ.' using errcode = '22023';
  end if;

  insert into public.payments(
    customer_id, kiosk_id, start_date, end_date, months, price_per_month,
    discount, total_amount, payment_method, payment_status, transaction_type,
    note, payment_intent_key, registration_batch_id
  ) values (
    customer_record.id, first_kiosk_id, null, null, 1, authoritative_total,
    0, authoritative_total, 'transfer', 'pending', 'standard',
    'Public registration batch #' || batch_record.id,
    'registration-batch:' || batch_record.id,
    batch_record.id
  ) returning * into payment_record;

  update public.registration_batches
  set payment_id = payment_record.id,
      total_amount = authoritative_total,
      updated_at = pg_catalog.now()
  where id = batch_record.id
  returning * into batch_record;

  update public.registration_requests
  set payment_id = payment_record.id
  where registration_batch_id = batch_record.id;

  update public.customers c
  set total_kiosks = (
    select pg_catalog.count(*) from public.kiosks k where k.customer_id = c.id
  )
  where c.id = customer_record.id;

  return pg_catalog.jsonb_build_object(
    'batch', pg_catalog.to_jsonb(batch_record),
    'payment', pg_catalog.to_jsonb(payment_record),
    'items', result_items,
    'reused', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.preview_renewal_promotion(kiosk_id_input bigint, months_input integer, promotion_code_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k public.kiosks%rowtype; bt public.business_types%rowtype; evaluation jsonb; service_start date;
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then perform private.assert_payment_permission(); end if;
 if months_input is null or months_input<1 or months_input>120 then raise exception 'Số tháng không hợp lệ.'; end if;
 select * into k from public.kiosks where id=kiosk_id_input;
 if not found or not exists(select 1 from public.registered_kiosks where id=k.id) then raise exception 'Kiosk chưa đủ điều kiện gia hạn.'; end if;
 select * into bt from public.business_types where id=k.business_type_id and is_active;
 if not found or bt.price_per_month<=0 then raise exception 'Giá gia hạn không hợp lệ.'; end if;
 evaluation:=private.evaluate_registration_promotion(promotion_code_input,k.customer_id,jsonb_build_array(jsonb_build_object(
   'months',months_input,'totalAmount',bt.price_per_month*months_input,'businessTypeId',bt.id,'categoryId',bt.category_id)));
 service_start:=greatest(coalesce(k.end_date+1,(now() at time zone 'Asia/Ho_Chi_Minh')::date),(now() at time zone 'Asia/Ho_Chi_Minh')::date);
 return evaluation||jsonb_build_object('proposedExpiry',(service_start+make_interval(months=>months_input+coalesce((evaluation->>'totalBonusMonths')::integer,0))-interval '1 day')::date);
end $function$

CREATE OR REPLACE FUNCTION public.record_payos_payment_link(purpose_input text, payment_id_input bigint, wallet_user_id_input uuid, order_code_input bigint, amount_input numeric, description_input text, checkout_url_input text DEFAULT NULL::text, qr_code_input text DEFAULT NULL::text, payment_link_id_input text DEFAULT NULL::text, provider_payload_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  order_record public.payos_orders%rowtype;
  payment_record public.payments%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để tạo thanh toán PayOS.' using errcode = '42501';
  end if;

  if purpose_input = 'crm_payment' then
    if not private.current_staff_has_payos_access() then
      raise exception 'Không có quyền tạo thanh toán CRM qua PayOS.' using errcode = '42501';
    end if;

    select *
    into payment_record
    from public.payments
    where id = payment_id_input;

    if not found then
      raise exception 'Không tìm thấy thanh toán CRM.' using errcode = '22023';
    end if;
    if lower(coalesce(payment_record.payment_status, '')) <> 'pending' then
      raise exception 'Chỉ tạo PayOS cho thanh toán Pending.' using errcode = '22023';
    end if;
    if coalesce(payment_record.total_amount, 0) <> amount_input then
      raise exception 'Số tiền PayOS không khớp thanh toán CRM.' using errcode = '22023';
    end if;
  elsif purpose_input = 'wallet_topup' then
    if wallet_user_id_input <> auth.uid() and not private.current_staff_has_payos_access() then
      raise exception 'Không có quyền tạo thanh toán nạp xu cho user khác.' using errcode = '42501';
    end if;
    if not exists (
      select 1 from public.user_profiles up where up.user_id = wallet_user_id_input
    ) then
      raise exception 'Không tìm thấy hồ sơ user nhận xu.' using errcode = '22023';
    end if;
  else
    raise exception 'Mục đích PayOS không hợp lệ.' using errcode = '22023';
  end if;

  insert into public.payos_orders(
    order_code,
    purpose,
    payment_id,
    wallet_user_id,
    amount,
    description,
    checkout_url,
    qr_code,
    payment_link_id,
    provider_payload,
    created_by
  )
  values(
    order_code_input,
    purpose_input,
    payment_id_input,
    wallet_user_id_input,
    amount_input,
    nullif(trim(description_input), ''),
    nullif(trim(checkout_url_input), ''),
    nullif(trim(qr_code_input), ''),
    nullif(trim(payment_link_id_input), ''),
    coalesce(provider_payload_input, '{}'::jsonb),
    auth.uid()
  )
  on conflict (order_code) do update
  set
    checkout_url = excluded.checkout_url,
    qr_code = excluded.qr_code,
    payment_link_id = excluded.payment_link_id,
    provider_payload = excluded.provider_payload,
    updated_at = now()
  where public.payos_orders.status = 'pending'
  returning * into order_record;

  return to_jsonb(order_record);
end;
$function$

