CREATE OR REPLACE FUNCTION public.register_public_renewal_authorization(kiosk_id_input bigint, nonce_hash_input text, expires_at_input timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
