CREATE OR REPLACE FUNCTION public.reject_payment(payment_id_input bigint, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
begin
  actor := private.assert_payment_permission();

  if nullif(trim(reason_input), '') is null then
    raise exception 'Lý do từ chối là bắt buộc.';
  end if;

  select * into payment_record
  from public.payments
  where id = payment_id_input
  for update;

  if not found or lower(payment_record.payment_status) <> 'pending' then
    raise exception 'Chỉ thanh toán Pending mới được từ chối.';
  end if;

  before_record := payment_record;
  perform set_config('app.payment_workflow_action', 'reject', true);

  update public.payments
  set payment_status = 'rejected'
  where id = payment_record.id
  returning * into payment_record;

  perform private.write_payment_audit(
    'reject',
    to_jsonb(before_record),
    to_jsonb(payment_record),
    reason_input,
    actor
  );

  return to_jsonb(payment_record);
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_registration_request(request_id_input bigint, reason_input text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_role text;
begin
  actor_role := private.current_user_role();
  if actor_role is null or actor_role not in ('admin', 'reviewer') then
    raise exception 'Bạn không có quyền từ chối đơn.';
  end if;
  if length(trim(coalesce(reason_input, ''))) < 3 then
    raise exception 'Cần nhập lý do từ chối.';
  end if;

  update public.registration_requests
  set
    status = 'rejected',
    reviewed_at = now(),
    reviewed_by = auth.uid(),
    rejection_reason = trim(reason_input)
  where id = request_id_input
    and status = 'pending';

  if not found then
    raise exception 'Không tìm thấy đơn chờ xử lý.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_payos_checkout_claim(payment_id_input bigint, claim_token_input uuid, next_state_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  payment_record public.payments%rowtype;
begin
  if current_user <> 'service_role'
    and coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'RPC này chỉ dành cho server.'
      using errcode = '42501';
  end if;

  if next_state_input is null
    or next_state_input not in ('reserved', 'failed', 'expired') then
    raise exception 'Trạng thái release không hợp lệ.'
      using errcode = '22023';
  end if;

  select p.*
  into payment_record
  from public.payments p
  where p.id = payment_id_input
  for update;

  if not found then
    raise exception 'Không tìm thấy thanh toán.'
      using errcode = 'P0002';
  end if;

  if payment_record.payos_checkout_state = 'ready' then
    return jsonb_build_object(
      'payment_id', payment_record.id,
      'checkout_state', payment_record.payos_checkout_state
    );
  end if;

  if payment_record.payos_claim_token is distinct from claim_token_input then
    raise exception 'Checkout claim không còn hiệu lực.'
      using errcode = 'P1002';
  end if;

  perform set_config('app.payos_metadata_write', 'allowed', true);

  update public.payments p
  set
    payos_checkout_state = next_state_input,
    payos_claim_token = null,
    payos_claim_expires_at = null
  where p.id = payment_id_input
  returning p.* into payment_record;

  return jsonb_build_object(
    'payment_id', payment_record.id,
    'checkout_state', payment_record.payos_checkout_state,
    'order_code', payment_record.payos_order_code,
    'amount_snapshot', payment_record.payos_amount_snapshot,
    'expires_at', payment_record.payos_expire_at
  );
end;
$function$

