CREATE OR REPLACE FUNCTION public.review_public_legacy_registration_request(request_id_input bigint, action_input text, reason_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  request_record public.registration_requests%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  payment_record public.payments%rowtype;
  customer_payload jsonb;
  request_code_value text;
  customer_facebook_id_value text;
  customer_phone_value text;
  customer_name_value text;
  customer_link_value text;
  next_status text;
  amount_value numeric;
  confirmed_timestamp timestamptz;
begin
  actor := private.assert_registration_permission();

  select *
  into request_record
  from public.registration_requests r
  where r.id = request_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy yêu cầu bổ sung.';
  end if;
  if request_record.metadata->>'request_type' <> 'legacy' then
    raise exception 'Yêu cầu này không thuộc luồng bổ sung khách hàng cũ.' using errcode = '22023';
  end if;

  if lower(trim(action_input)) = 'approve' then
    next_status := 'approved';
    if request_record.status = 'approved'
      and request_record.customer_id is not null
      and request_record.kiosk_id is not null
      and (
        request_record.payment_id is not null
        or coalesce(request_record.total_amount, 0) <= 0
      ) then
      return jsonb_build_object(
        'request', to_jsonb(request_record),
        'customer_id', request_record.customer_id,
        'kiosk_id', request_record.kiosk_id,
        'payment_id', request_record.payment_id,
        'already_processed', true
      );
    end if;
    if request_record.status not in ('pending', 'approved') then
      raise exception 'Yêu cầu đã bị từ chối và không thể duyệt.';
    end if;
  elsif lower(trim(action_input)) = 'cancel' then
    if request_record.status <> 'pending' then
      raise exception 'Chỉ yêu cầu đang chờ mới có thể được hủy.';
    end if;
    if nullif(trim(reason_input), '') is null then
      raise exception 'Lý do hủy là bắt buộc.' using errcode = '22023';
    end if;
    next_status := 'rejected';
  else
    raise exception 'Thao tác xử lý không hợp lệ.' using errcode = '22023';
  end if;

  if next_status = 'approved' then
    customer_payload := coalesce(request_record.metadata->'customer', '{}'::jsonb);
    request_code_value := nullif(request_record.metadata->>'request_code', '');
    customer_facebook_id_value := nullif(
      regexp_replace(coalesce(customer_payload->>'facebook_id', ''), '[^0-9]', '', 'g'),
      ''
    );
    customer_phone_value := nullif(trim(coalesce(customer_payload->>'phone', request_record.phone)), '');
    customer_name_value := nullif(trim(coalesce(customer_payload->>'facebook_name', request_record.facebook_name)), '');
    customer_link_value := nullif(trim(customer_payload->>'facebook_link'), '');
    amount_value := greatest(coalesce(request_record.total_amount, 0), 0);

    if customer_name_value is null or customer_phone_value is null then
      raise exception 'Hồ sơ thiếu tên hoặc số điện thoại khách hàng.' using errcode = '22023';
    end if;
    if request_record.category_id is null
      or request_record.business_type_id is null
      or request_record.requested_start_date is null
      or request_record.requested_end_date is null then
      raise exception 'Hồ sơ thiếu dữ liệu bắt buộc để tạo kiosk.' using errcode = '22023';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('legacy-approval:' || coalesce(request_code_value, request_record.id::text), 0)
    );

    if request_record.customer_id is not null then
      select * into customer_record
      from public.customers c
      where c.id = request_record.customer_id
      for update;
    end if;

    if customer_record.id is null and request_code_value is not null then
      select c.*
      into customer_record
      from public.registration_requests sibling
      join public.customers c on c.id = sibling.customer_id
      where sibling.metadata->>'request_type' = 'legacy'
        and sibling.metadata->>'request_code' = request_code_value
      order by sibling.id
      limit 1
      for update of c;
    end if;

    if customer_record.id is null then
      select *
      into customer_record
      from public.customers c
      where (customer_facebook_id_value is not null and c.facebook_id = customer_facebook_id_value)
         or c.phone = customer_phone_value
      order by
        case when customer_facebook_id_value is not null
          and c.facebook_id = customer_facebook_id_value then 0 else 1 end,
        c.id
      limit 1
      for update;
    end if;

    if customer_record.id is null then
      insert into public.customers(
        facebook_name, facebook_id, facebook_link, phone, status,
        total_paid, last_payment_date, note
      )
      values(
        customer_name_value,
        customer_facebook_id_value,
        customer_link_value,
        customer_phone_value,
        'active',
        0,
        null,
        'Bổ sung từ hồ sơ khách hàng cũ #' || request_record.id
      )
      returning * into customer_record;
    else
      update public.customers
      set
        facebook_name = coalesce(nullif(trim(facebook_name), ''), customer_name_value),
        facebook_id = coalesce(facebook_id, customer_facebook_id_value),
        facebook_link = coalesce(facebook_link, customer_link_value),
        phone = coalesce(phone, customer_phone_value),
        status = case when status = 'inactive' then status else 'active' end,
        updated_at = pg_catalog.now()
      where id = customer_record.id
      returning * into customer_record;
    end if;

    if request_record.kiosk_id is not null then
      select * into kiosk_record
      from public.kiosks k
      where k.id = request_record.kiosk_id
      for update;
    end if;

    if kiosk_record.id is null and request_record.facebook_id is not null then
      select * into kiosk_record
      from public.kiosks k
      where k.facebook_id = request_record.facebook_id
      for update;
    end if;

    if kiosk_record.id is null then
      insert into public.kiosks(
        customer_id, facebook_name, facebook_id, facebook_link,
        category_id, business_type_id, service_name,
        start_date, end_date, status, auto_approve,
        total_paid, kiosk_total_paid, last_payment_date, note, is_primary
      )
      values(
        customer_record.id,
        request_record.facebook_name,
        request_record.facebook_id,
        request_record.facebook_link,
        request_record.category_id,
        request_record.business_type_id,
        request_record.service_name,
        request_record.requested_start_date,
        request_record.requested_end_date,
        case
          when request_record.requested_end_date < current_date then 'expired'
          else 'active'
        end,
        false,
        0,
        0,
        null,
        request_record.note,
        not exists (
          select 1 from public.kiosks existing
          where existing.customer_id = customer_record.id and existing.is_primary
        )
      )
      returning * into kiosk_record;
    elsif kiosk_record.customer_id <> customer_record.id then
      raise exception 'Facebook ID kiosk đã thuộc về một khách hàng khác.' using errcode = '23505';
    end if;

    if amount_value > 0 and request_record.payment_id is null then
      confirmed_timestamp := (
        request_record.requested_start_date::timestamp at time zone 'Asia/Ho_Chi_Minh'
      );
      perform set_config('app.payment_workflow_action', 'adjustment', true);

      insert into public.payments(
        customer_id, kiosk_id, start_date, end_date, months,
        price_per_month, discount, discount_reason, total_amount,
        payment_method, payment_status, transaction_type, confirmed_at, note
      )
      values(
        customer_record.id,
        kiosk_record.id,
        request_record.requested_start_date,
        request_record.requested_end_date,
        greatest(coalesce(request_record.months, 1), 1),
        amount_value,
        0,
        null,
        amount_value,
        coalesce(nullif(request_record.payment_method, ''), 'legacy'),
        'completed',
        'standard',
        confirmed_timestamp,
        concat_ws(' - ', 'Doanh thu bổ sung dữ liệu cũ', nullif(trim(request_record.note), ''))
      )
      returning * into payment_record;
    end if;

    update public.registration_requests
    set
      status = 'approved',
      reviewed_at = pg_catalog.now(),
      reviewed_by = actor.user_id,
      rejection_reason = null,
      customer_id = customer_record.id,
      kiosk_id = kiosk_record.id,
      payment_id = coalesce(payment_record.id, payment_id),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'legacy_review_action', 'approve',
        'legacy_reviewed_by', actor.user_id,
        'legacy_reviewed_at', pg_catalog.now(),
        'materialized_at', pg_catalog.now(),
        'revenue_source', 'payments'
      )
    where id = request_record.id
    returning * into request_record;
  else
    update public.registration_requests
    set
      status = next_status,
      reviewed_at = pg_catalog.now(),
      reviewed_by = actor.user_id,
      rejection_reason = trim(reason_input),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'legacy_review_action', 'cancel',
        'legacy_reviewed_by', actor.user_id,
        'legacy_reviewed_at', pg_catalog.now()
      )
    where id = request_record.id
    returning * into request_record;
  end if;

  insert into public.audit_logs(
    actor_id, actor_name, actor_type, actor_role, module, entity,
    record_id, action, before, after, reason
  )
  values(
    actor.user_id,
    coalesce(actor.display_name, actor.username, 'System'),
    'staff',
    actor.role,
    'Registration',
    'registration_requests',
    request_record.id::text,
    'review_legacy_' || lower(trim(action_input)),
    jsonb_build_object('status', case when next_status = 'approved' then 'pending_or_incomplete' else 'pending' end),
    jsonb_build_object(
      'status', request_record.status,
      'customer_id', request_record.customer_id,
      'kiosk_id', request_record.kiosk_id,
      'payment_id', request_record.payment_id
    ),
    nullif(trim(reason_input), '')
  );

  return jsonb_build_object(
    'request', to_jsonb(request_record),
    'customer_id', request_record.customer_id,
    'kiosk_id', request_record.kiosk_id,
    'payment_id', request_record.payment_id,
    'already_processed', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_employee(p_id bigint, p_full_name text, p_phone text DEFAULT NULL::text, p_job_title text DEFAULT NULL::text, p_start_date date DEFAULT NULL::date, p_employment_status text DEFAULT 'active'::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.employees%rowtype; saved public.employees%rowtype; message text;
begin
  if not public.has_user_permission('expenses') then raise exception 'Không có quyền quản lý nhân viên.' using errcode='42501'; end if;
  if p_full_name is null or length(btrim(p_full_name)) not between 1 and 160 then raise exception 'Họ tên phải có từ 1 đến 160 ký tự.'; end if;
  if p_employment_status is null or p_employment_status not in ('active','left') then raise exception 'Trạng thái làm việc không hợp lệ.'; end if;
  if p_id is null then
    insert into public.employees(full_name,phone,job_title,start_date,employment_status,notes)
    values(btrim(p_full_name),nullif(btrim(p_phone),''),nullif(btrim(p_job_title),''),p_start_date,p_employment_status,nullif(btrim(p_notes),'')) returning * into saved;
    message:='Đã tạo nhân viên '||saved.full_name;
  else
    select * into previous from public.employees where id=p_id for update;
    if previous.id is null then raise exception 'Nhân viên không tồn tại.'; end if;
    if previous.archived_at is not null then raise exception 'Khôi phục nhân viên trước khi chỉnh sửa.'; end if;
    update public.employees set full_name=btrim(p_full_name),phone=nullif(btrim(p_phone),''),job_title=nullif(btrim(p_job_title),''),
      start_date=p_start_date,employment_status=p_employment_status,notes=nullif(btrim(p_notes),'') where id=p_id returning * into saved;
    message:=case when previous.employment_status<>saved.employment_status then saved.full_name||case when saved.employment_status='left' then ' đã nghỉ việc' else ' đã làm việc trở lại' end else 'Đã cập nhật nhân viên '||saved.full_name end;
  end if;
  perform private.log_employee_change(previous,saved,message);
  return to_jsonb(saved);
end $function$

CREATE OR REPLACE FUNCTION public.save_employee_expense(p_id bigint, p_category text, p_amount numeric, p_expense_date date, p_employee_id bigint, p_salary_period date, p_payment_method text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.user_profiles%rowtype; previous public.expenses%rowtype; saved public.expenses%rowtype;
  category_row public.expense_categories%rowtype; normalized_category text:=lower(btrim(coalesce(p_category,'')));
  normalized_method text:=lower(btrim(coalesce(p_payment_method,''))); normalized_note text:=nullif(btrim(coalesce(p_note,'')),'');
  normalized_period date:=case when p_salary_period is null then null else date_trunc('month',p_salary_period)::date end;
  duplicate_salary boolean:=false; log_action text;
begin
  if not public.has_user_permission('expenses') then raise exception 'Không có quyền quản lý chi phí.' using errcode='42501'; end if;
  if p_id is not null then
    select * into previous from public.expenses where id=p_id and archived_at is null for update;
    if previous.id is null then raise exception 'Khoản chi không tồn tại hoặc đã hủy.'; end if;
  end if;
  select * into category_row from public.expense_categories where code=normalized_category and (is_active or id=previous.category_id);
  if category_row.id is null then raise exception 'Danh mục chi phí không hợp lệ hoặc đã lưu trữ.'; end if;
  if p_amount is null or p_amount<=0 or p_amount::text in ('NaN','Infinity','-Infinity') then raise exception 'Số tiền phải lớn hơn 0.'; end if;
  if p_expense_date is null then raise exception 'Ngày chi là bắt buộc.'; end if;
  if normalized_method='' or length(normalized_method)>50 then raise exception 'Phương thức chi không hợp lệ.'; end if;
  if category_row.is_salary and (normalized_period is null or (p_employee_id is null and not (previous.id is not null and previous.employee_id is null and previous.employee_user_id is not null))) then
    raise exception 'Lương cần có nhân viên và kỳ lương.';
  end if;
  if not category_row.is_salary then normalized_period:=null; end if;
  select * into actor from public.user_profiles where user_id=auth.uid();
  if actor.user_id is null then raise exception 'Không tìm thấy tài khoản thực hiện.' using errcode='42501'; end if;
  duplicate_salary:=category_row.is_salary and public.check_employee_salary_duplicate(p_employee_id,normalized_period,p_id);
  if p_id is null then
    insert into public.expenses(category,category_id,amount,expense_date,employee_id,salary_period,payment_method,note,created_by)
    values(category_row.code,category_row.id,p_amount,p_expense_date,p_employee_id,normalized_period,normalized_method,normalized_note,auth.uid()) returning * into saved;
    log_action:=case when category_row.is_salary then 'create_salary_expense' else 'create_expense' end;
  else
    update public.expenses set category=category_row.code,category_id=category_row.id,amount=p_amount,expense_date=p_expense_date,
      employee_id=p_employee_id,salary_period=normalized_period,payment_method=normalized_method,note=normalized_note
      where id=p_id returning * into saved;
    log_action:='update_expense';
  end if;
  insert into public.audit_logs(actor_id,actor_name,actor_role,actor_type,module,entity,record_id,action,before,after,reason)
  values(auth.uid(),coalesce(actor.display_name,actor.username,'Quản trị viên'),case when actor.is_system_admin then 'system_admin' else 'staff' end,'staff',
    'Expense','expenses',saved.id::text,log_action,case when previous.id is null then null else to_jsonb(previous) end,
    to_jsonb(saved)||jsonb_build_object('employee_name',saved.employee_name_snapshot,'category_name',category_row.name),
    case when category_row.is_salary then 'Ghi nhận lương '||to_char(normalized_period,'MM/YYYY')||' cho '||coalesce(saved.employee_name_snapshot,'nhân viên')||' – '||trim(to_char(p_amount,'FM999G999G999G990'))||'đ'
      when log_action='update_expense' then 'Sửa chi phí '||trim(to_char(p_amount,'FM999G999G999G990'))||'đ – '||category_row.name
      else 'Thêm chi phí '||trim(to_char(p_amount,'FM999G999G999G990'))||'đ – '||category_row.name end);
  return jsonb_build_object('expense',to_jsonb(saved),'duplicateSalary',duplicate_salary);
end $function$

CREATE OR REPLACE FUNCTION public.save_expense(p_id bigint, p_category text, p_amount numeric, p_expense_date date, p_employee_user_id uuid, p_salary_period date, p_payment_method text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor public.user_profiles%rowtype; before_expense public.expenses%rowtype; saved_expense public.expenses%rowtype;
  selected_category public.expense_categories%rowtype; normalized_category text:=lower(btrim(coalesce(p_category,'')));
  normalized_method text:=lower(btrim(coalesce(p_payment_method,''))); normalized_note text:=nullif(btrim(coalesce(p_note,'')),'');
  normalized_period date:=case when p_salary_period is null then null else date_trunc('month',p_salary_period)::date end;
  duplicate_salary boolean:=false; employee_name text; log_action text;
begin
  if not public.has_user_permission('expenses') then raise exception 'Không có quyền quản lý chi phí.' using errcode='42501'; end if;
  select * into selected_category from public.expense_categories where code=normalized_category and is_active;
  if selected_category.id is null then raise exception 'Danh mục chi phí không hợp lệ hoặc đã lưu trữ.'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'Số tiền phải lớn hơn 0.'; end if;
  if p_expense_date is null then raise exception 'Ngày chi là bắt buộc.'; end if;
  if normalized_method='' or length(normalized_method)>50 then raise exception 'Phương thức chi không hợp lệ.'; end if;
  if selected_category.is_salary and (p_employee_user_id is null or normalized_period is null) then raise exception 'Lương cần có nhân viên và kỳ lương.'; end if;
  if not selected_category.is_salary then normalized_period:=null; end if;
  if p_employee_user_id is not null and not exists(select 1 from public.user_profiles where user_id=p_employee_user_id) then raise exception 'Nhân viên không tồn tại.'; end if;
  select * into actor from public.user_profiles where user_id=auth.uid();
  if actor.user_id is null then raise exception 'Không tìm thấy tài khoản thực hiện.' using errcode='42501'; end if;
  duplicate_salary:=selected_category.is_salary and exists(select 1 from public.expenses e join public.expense_categories c on c.id=e.category_id
    where c.is_salary and e.employee_user_id=p_employee_user_id and e.salary_period=normalized_period and e.archived_at is null and (p_id is null or e.id<>p_id));
  if p_id is null then
    insert into public.expenses(category,category_id,amount,expense_date,employee_user_id,salary_period,payment_method,note,created_by)
    values(selected_category.code,selected_category.id,p_amount,p_expense_date,p_employee_user_id,normalized_period,normalized_method,normalized_note,auth.uid())
    returning * into saved_expense; log_action:=case when selected_category.is_salary then 'create_salary_expense' else 'create_expense' end;
  else
    select * into before_expense from public.expenses where id=p_id and archived_at is null for update;
    if before_expense.id is null then raise exception 'Khoản chi không tồn tại hoặc đã hủy.'; end if;
    update public.expenses set category=selected_category.code,category_id=selected_category.id,amount=p_amount,expense_date=p_expense_date,
      employee_user_id=p_employee_user_id,salary_period=normalized_period,payment_method=normalized_method,note=normalized_note
      where id=p_id returning * into saved_expense; log_action:='update_expense';
  end if;
  select coalesce(up.display_name,up.username,'Nhân viên') into employee_name from public.user_profiles up where up.user_id=saved_expense.employee_user_id;
  insert into public.audit_logs(actor_id,actor_name,actor_role,actor_type,module,entity,record_id,action,before,after,reason)
  values(auth.uid(),coalesce(actor.display_name,actor.username,'Quản trị viên'),case when actor.is_system_admin then 'system_admin' else 'staff' end,'staff',
    'Expense','expenses',saved_expense.id::text,log_action,case when before_expense.id is null then null else to_jsonb(before_expense) end,
    to_jsonb(saved_expense)||jsonb_build_object('employee_name',employee_name,'category_name',selected_category.name),
    case when selected_category.is_salary then 'Ghi nhận lương '||to_char(normalized_period,'MM/YYYY')||' cho '||coalesce(employee_name,'nhân viên')||' – '||trim(to_char(p_amount,'FM999G999G999G990'))||'đ'
      when log_action='update_expense' then 'Sửa chi phí '||trim(to_char(p_amount,'FM999G999G999G990'))||'đ – '||selected_category.name
      else 'Thêm chi phí '||trim(to_char(p_amount,'FM999G999G999G990'))||'đ – '||selected_category.name end);
  return jsonb_build_object('expense',to_jsonb(saved_expense),'duplicateSalary',duplicate_salary);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_expense_category(p_id bigint, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare saved public.expense_categories%rowtype; normalized_name text:=btrim(coalesce(p_name,'')); generated_code text;
begin
  if not public.has_user_permission('expenses') then raise exception 'Không có quyền quản lý chi phí.' using errcode='42501'; end if;
  if length(normalized_name) not between 1 and 120 then raise exception 'Tên danh mục phải có từ 1 đến 120 ký tự.'; end if;
  if exists(select 1 from public.expense_categories where lower(name)=lower(normalized_name) and (p_id is null or id<>p_id)) then raise exception 'Tên danh mục đã tồn tại.'; end if;
  if p_id is null then
    generated_code:='custom-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSUS');
    insert into public.expense_categories(code,name,created_by) values(generated_code,normalized_name,auth.uid()) returning * into saved;
  else
    update public.expense_categories set name=normalized_name where id=p_id and archived_at is null returning * into saved;
    if saved.id is null then raise exception 'Danh mục không tồn tại hoặc đã lưu trữ.'; end if;
  end if;
  return to_jsonb(saved);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_featured_business(p_business jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  actor public.user_profiles%rowtype;
  before_business public.featured_businesses%rowtype;
  saved_business public.featured_businesses%rowtype;
  business_id bigint := nullif(p_business->>'id', '')::bigint;
  start_at timestamptz := nullif(p_business->>'visibilityStart', '')::timestamptz;
  end_at timestamptz := nullif(p_business->>'visibilityEnd', '')::timestamptz;
  action_name text;
begin
  if not public.has_user_permission('homepage-content') then
    raise exception 'Không có quyền quản lý nội dung trang chủ.' using errcode = '42501';
  end if;
  if nullif(btrim(p_business->>'name'), '') is null or nullif(btrim(p_business->>'category'), '') is null then
    raise exception 'Tên và danh mục doanh nghiệp là bắt buộc.';
  end if;
  if start_at is not null and end_at is not null and start_at > end_at then raise exception 'Khoảng hiển thị không hợp lệ.'; end if;
  select * into actor from public.user_profiles where user_id = auth.uid();
  if business_id is null then
    insert into public.featured_businesses(name,image_url,category,short_description,address,facebook_url,zalo_contact,phone,badge,enabled,display_order,visibility_start,visibility_end,created_by)
    values (left(btrim(p_business->>'name'),160),nullif(btrim(p_business->>'imageUrl'),''),left(btrim(p_business->>'category'),100),
      nullif(left(btrim(p_business->>'shortDescription'),500),''),nullif(btrim(p_business->>'address'),''),nullif(btrim(p_business->>'facebookUrl'),''),
      nullif(btrim(p_business->>'zaloContact'),''),nullif(btrim(p_business->>'phone'),''),nullif(left(btrim(p_business->>'badge'),50),''),
      coalesce((p_business->>'enabled')::boolean,true),greatest(coalesce((p_business->>'displayOrder')::integer,0),0),start_at,end_at,auth.uid())
    returning * into saved_business;
    action_name := 'create_featured_business';
  else
    select * into before_business from public.featured_businesses where id = business_id and archived_at is null for update;
    if before_business.id is null then raise exception 'Doanh nghiệp không tồn tại hoặc đã lưu trữ.'; end if;
    update public.featured_businesses set
      name=left(btrim(p_business->>'name'),160), image_url=nullif(btrim(p_business->>'imageUrl'),''), category=left(btrim(p_business->>'category'),100),
      short_description=nullif(left(btrim(p_business->>'shortDescription'),500),''), address=nullif(btrim(p_business->>'address'),''),
      facebook_url=nullif(btrim(p_business->>'facebookUrl'),''), zalo_contact=nullif(btrim(p_business->>'zaloContact'),''), phone=nullif(btrim(p_business->>'phone'),''),
      badge=nullif(left(btrim(p_business->>'badge'),50),''), enabled=coalesce((p_business->>'enabled')::boolean,true),
      display_order=greatest(coalesce((p_business->>'displayOrder')::integer,0),0), visibility_start=start_at, visibility_end=end_at
    where id=business_id returning * into saved_business;
    action_name := 'update_featured_business';
  end if;
  insert into public.audit_logs(actor_id,actor_name,actor_role,actor_type,module,entity,record_id,action,before,after,reason)
  values (auth.uid(),coalesce(actor.display_name,actor.username,'Quản trị viên'),case when actor.is_system_admin then 'system_admin' else 'staff' end,'staff',
    'Homepage','featured_businesses',saved_business.id::text,action_name,case when before_business.id is null then null else to_jsonb(before_business) end,to_jsonb(saved_business),saved_business.name);
  return to_jsonb(saved_business);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_homepage_content(p_content jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  actor public.user_profiles%rowtype;
  before_content public.homepage_content%rowtype;
  saved_content public.homepage_content%rowtype;
  links jsonb := coalesce(p_content->'communityLinks', '[]'::jsonb);
  zalo jsonb := coalesce(p_content->'zaloContacts', '[]'::jsonb);
  visibility jsonb := coalesce(p_content->'sectionVisibility', '{}'::jsonb);
  normalized_section_order text[];
begin
  if not public.has_user_permission('homepage-content') then
    raise exception 'Không có quyền quản lý nội dung trang chủ.' using errcode = '42501';
  end if;
  if jsonb_typeof(links) <> 'array' or jsonb_array_length(links) > 12 then raise exception 'Danh sách liên kết không hợp lệ.'; end if;
  if jsonb_typeof(zalo) <> 'array' or jsonb_array_length(zalo) > 5 then raise exception 'Danh sách Zalo không hợp lệ.'; end if;
  if jsonb_typeof(visibility) <> 'object' then raise exception 'Cấu hình hiển thị không hợp lệ.'; end if;
  select coalesce(array_agg(value), array[]::text[]) into normalized_section_order
  from jsonb_array_elements_text(coalesce(p_content->'sectionOrder', '[]'::jsonb));
  if cardinality(normalized_section_order) <> 5 or normalized_section_order @> array['featured_businesses','kiosk_services','posting_rules','community_links','contact']::text[] is false then
    raise exception 'Thứ tự section không hợp lệ.';
  end if;
  if nullif(btrim(p_content->>'heroTitle'), '') is null or nullif(btrim(p_content->>'heroSubtitle'), '') is null then
    raise exception 'Tiêu đề và mô tả Hero là bắt buộc.';
  end if;
  if coalesce(p_content->>'heroKioskCtaRoute', '') !~ '^#/[a-z0-9-]+$' then raise exception 'Route CTA Kiosk không hợp lệ.'; end if;

  select * into actor from public.user_profiles where user_id = auth.uid();
  select * into before_content from public.homepage_content where id = 1 for update;
  update public.homepage_content set
    hero_title = left(btrim(p_content->>'heroTitle'), 180),
    hero_subtitle = left(btrim(p_content->>'heroSubtitle'), 600),
    hero_image_url = nullif(btrim(p_content->>'heroImageUrl'), ''),
    hero_group_cta_label = left(btrim(p_content->>'heroGroupCtaLabel'), 80),
    hero_group_cta_url = btrim(p_content->>'heroGroupCtaUrl'),
    hero_kiosk_cta_label = left(btrim(p_content->>'heroKioskCtaLabel'), 80),
    hero_kiosk_cta_route = btrim(p_content->>'heroKioskCtaRoute'),
    posting_rules = left(coalesce(p_content->>'postingRules', ''), 5000),
    zalo_contacts = zalo,
    hotline_label = left(btrim(p_content->>'hotlineLabel'), 60),
    hotline_number = left(regexp_replace(coalesce(p_content->>'hotlineNumber',''), '[^0-9+]', '', 'g'), 20),
    fanpage_label = left(btrim(p_content->>'fanpageLabel'), 80),
    fanpage_url = btrim(p_content->>'fanpageUrl'),
    community_links = links,
    section_visibility = visibility,
    section_order = normalized_section_order,
    updated_by = auth.uid()
  where id = 1 returning * into saved_content;
  insert into public.audit_logs(actor_id, actor_name, actor_role, actor_type, module, entity, record_id, action, before, after, reason)
  values (auth.uid(), coalesce(actor.display_name, actor.username, 'Quản trị viên'),
    case when actor.is_system_admin then 'system_admin' else 'staff' end, 'staff',
    'Homepage', 'homepage_content', '1', 'update_homepage_content',
    to_jsonb(before_content), to_jsonb(saved_content), 'Cập nhật nội dung trang chủ');
  return to_jsonb(saved_content);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_employee_lifecycle(p_id bigint, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.employees%rowtype; saved public.employees%rowtype; message text;
begin
  if not public.has_user_permission('expenses') then raise exception 'Không có quyền quản lý nhân viên.' using errcode='42501'; end if;
  select * into previous from public.employees where id=p_id for update;
  if previous.id is null then raise exception 'Nhân viên không tồn tại.'; end if;
  if p_action is null or p_action not in ('archive','restore','left','reactivate') then raise exception 'Thao tác không hợp lệ.'; end if;
  if previous.archived_at is not null and p_action not in ('restore','archive') then raise exception 'Khôi phục nhân viên trước khi đổi trạng thái.'; end if;
  if (p_action='archive' and previous.archived_at is not null) or (p_action='restore' and previous.archived_at is null)
    or (p_action='left' and previous.employment_status='left') or (p_action='reactivate' and previous.employment_status='active') then return to_jsonb(previous); end if;
  update public.employees set archived_at=case when p_action='archive' then now() when p_action='restore' then null else archived_at end,
    employment_status=case when p_action='left' then 'left' when p_action='reactivate' then 'active' else employment_status end
    where id=p_id returning * into saved;
  message:=case p_action when 'archive' then 'Đã lưu trữ nhân viên '||saved.full_name when 'restore' then 'Đã khôi phục nhân viên '||saved.full_name
    when 'left' then saved.full_name||' đã nghỉ việc' else saved.full_name||' đã làm việc trở lại' end;
  perform private.log_employee_change(previous,saved,message);
  return to_jsonb(saved);
end $function$

CREATE OR REPLACE FUNCTION public.submit_public_legacy_registration(customer_input jsonb, kiosks_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  kiosk_item jsonb;
  business_type_record public.business_types%rowtype;
  request_record public.registration_requests%rowtype;
  request_ids jsonb := '[]'::jsonb;
  resolved_ids text[] := array[]::text[];
  customer_name text := nullif(trim(customer_input->>'facebook_name'), '');
  customer_phone text := nullif(trim(customer_input->>'phone'), '');
  customer_facebook_id text := nullif(regexp_replace(coalesce(customer_input->>'facebook_id', ''), '[^0-9]', '', 'g'), '');
  facebook_id_value text;
  facebook_link_value text;
  start_date_value date;
  end_date_value date;
  amount_value numeric;
  category_id_value bigint;
  item_number integer := 0;
  request_code uuid := gen_random_uuid();
begin
  if customer_input is null or jsonb_typeof(customer_input) <> 'object'
    or customer_name is null or customer_phone is null then
    raise exception 'Tên Facebook và số điện thoại khách hàng là bắt buộc.' using errcode = '22023';
  end if;
  if customer_phone !~ '^\+?[0-9 .()-]{9,20}$' then
    raise exception 'Số điện thoại không hợp lệ.' using errcode = '22023';
  end if;
  if kiosks_input is null or jsonb_typeof(kiosks_input) <> 'array'
    or jsonb_array_length(kiosks_input) < 1 or jsonb_array_length(kiosks_input) > 20 then
    raise exception 'Cần bổ sung từ 1 đến 20 kiosk.' using errcode = '22023';
  end if;

  for kiosk_item in select value from jsonb_array_elements(kiosks_input)
  loop
    item_number := item_number + 1;
    facebook_id_value := nullif(regexp_replace(coalesce(kiosk_item->>'facebook_id', ''), '[^0-9]', '', 'g'), '');
    facebook_link_value := nullif(trim(kiosk_item->>'facebook_link'), '');
    if facebook_id_value is null or trim(kiosk_item->>'facebook_id') !~ '^[0-9]{5,30}$'
      or facebook_link_value is null then
      raise exception 'Kiosk số % cần Facebook ID dạng số và link Facebook.', item_number using errcode = '22023';
    end if;
    if facebook_id_value = any(resolved_ids) then
      raise exception 'Facebook ID bị trùng trong cùng yêu cầu.' using errcode = '23505';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('public-legacy:' || facebook_id_value, 0));
    if exists (select 1 from public.kiosks k where k.facebook_id = facebook_id_value)
      or exists (select 1 from public.customers c where c.facebook_id = facebook_id_value)
      or exists (
        select 1 from public.registration_requests r
        where r.facebook_id = facebook_id_value and r.status = 'pending'
      ) then
      raise exception 'Facebook ID đã được sử dụng hoặc đang chờ Ban quản trị xử lý.' using errcode = '23505';
    end if;

    begin
      category_id_value := (kiosk_item->>'category_id')::bigint;
      start_date_value := (kiosk_item->>'start_date')::date;
      end_date_value := (kiosk_item->>'end_date')::date;
      amount_value := (kiosk_item->>'amount')::numeric;
      select * into business_type_record
      from public.business_types bt
      where bt.id = (kiosk_item->>'business_type_id')::bigint
        and bt.category_id = category_id_value
        and bt.is_active = true;
    exception when invalid_text_representation or datetime_field_overflow then
      raise exception 'Danh mục, dịch vụ, ngày hoặc số tiền của kiosk số % không hợp lệ.', item_number using errcode = '22023';
    end;
    if not found then
      raise exception 'Dịch vụ của kiosk số % không thuộc danh mục đã chọn hoặc không còn hoạt động.', item_number using errcode = '22023';
    end if;
    if amount_value < 0 or end_date_value < start_date_value then
      raise exception 'Số tiền hoặc thời hạn của kiosk số % không hợp lệ.', item_number using errcode = '22023';
    end if;

    resolved_ids := array_append(resolved_ids, facebook_id_value);
    insert into public.registration_requests(
      facebook_name, facebook_id, facebook_link, phone, service_name,
      category_id, business_type_id, requested_start_date, requested_end_date,
      total_amount, note, status, metadata
    ) values (
      coalesce(nullif(trim(kiosk_item->>'facebook_name'), ''), customer_name),
      facebook_id_value, facebook_link_value, customer_phone, business_type_record.name,
      business_type_record.category_id, business_type_record.id, start_date_value, end_date_value,
      amount_value, nullif(trim(kiosk_item->>'note'), ''), 'pending',
      jsonb_build_object(
        'request_type', 'legacy',
        'request_code', request_code::text,
        'customer', jsonb_build_object(
          'facebook_name', customer_name,
          'facebook_id', customer_facebook_id,
          'facebook_link', nullif(trim(customer_input->>'facebook_link'), ''),
          'phone', customer_phone,
          'note', nullif(trim(customer_input->>'note'), '')
        ),
        'bill_confirmed_via_zalo', true
      )
    ) returning * into request_record;
    request_ids := request_ids || jsonb_build_array(request_record.id);
  end loop;

  return jsonb_build_object(
    'request_code', request_code::text,
    'request_ids', request_ids,
    'count', jsonb_array_length(request_ids),
    'status', 'pending'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_public_registration(customer_input jsonb, kiosks_input jsonb, bill_input jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  kiosk_item jsonb; bt public.business_types%rowtype; request_id_value bigint;
  used_request_ids bigint[] := array[]::bigint[]; result_items jsonb := '[]'::jsonb;
  item_number integer := 0; months_value integer; discount_value numeric;
  start_on date; end_on date; total_value numeric;
  customer_name text := nullif(trim(customer_input->>'facebook_name'), '');
  customer_phone text := nullif(trim(customer_input->>'phone'), '');
begin
  if customer_input is null or jsonb_typeof(customer_input) <> 'object'
    or customer_name is null or customer_phone is null then
    raise exception 'Tên Facebook và số điện thoại là bắt buộc.' using errcode = '22023';
  end if;
  if kiosks_input is null or jsonb_typeof(kiosks_input) <> 'array'
    or jsonb_array_length(kiosks_input) < 1 or jsonb_array_length(kiosks_input) > 20 then
    raise exception 'Cần đăng ký từ 1 đến 20 kiosk.' using errcode = '22023';
  end if;
  for kiosk_item in select value from jsonb_array_elements(kiosks_input) loop
    item_number := item_number + 1;
    if nullif(trim(kiosk_item->>'facebook_name'), '') is null
      or nullif(trim(kiosk_item->>'facebook_link'), '') is null then
      raise exception 'Kiosk số % cần tên Facebook và link Facebook.', item_number using errcode = '22023';
    end if;
    if nullif(trim(kiosk_item->>'facebook_id'), '') is not null
      and trim(kiosk_item->>'facebook_id') !~ '^[0-9]+$' then
      raise exception 'Facebook ID của kiosk số % chỉ được chứa chữ số.', item_number using errcode = '22023';
    end if;
    if nullif(pg_catalog.regexp_replace(coalesce(kiosk_item->>'facebook_id', ''), '[^0-9]', '', 'g'), '') is null
      or trim(kiosk_item->>'facebook_id') !~ '^[0-9]{5,30}$' then
      raise exception 'Kiosk số % cần Facebook ID dạng số hợp lệ.', item_number using errcode = '22023';
    end if;
    begin
      months_value := (kiosk_item->>'months')::integer;
      discount_value := coalesce((kiosk_item->>'discount')::numeric, 0);
      select * into bt from public.business_types
      where id = (kiosk_item->>'business_type_id')::bigint and is_active = true;
    exception when invalid_text_representation then
      raise exception 'Thông tin dịch vụ của kiosk số % không hợp lệ.', item_number using errcode = '22023';
    end;
    if not found then raise exception 'Dịch vụ của kiosk số % không hoạt động.', item_number using errcode = '22023'; end if;
    request_id_value := null;
    select r.id into request_id_value from public.registration_requests r
    where r.status = 'awaiting_payment' and r.id <> all(used_request_ids)
      and pg_catalog.regexp_replace(coalesce(r.phone, ''), '[^0-9+]', '', 'g')
        = pg_catalog.regexp_replace(customer_phone, '[^0-9+]', '', 'g')
      and r.facebook_id = trim(kiosk_item->>'facebook_id')
      and r.business_type_id = bt.id and r.months = months_value
      and r.total_amount = (bt.price_per_month * months_value) - discount_value
      and (r.payment_id is null or exists (select 1 from public.payments p
        where p.id = r.payment_id and p.payment_status = 'pending'))
    order by r.id desc limit 1 for update;
    if not found then
      request_id_value := public.submit_registration_request(
        kiosk_item->>'facebook_name', customer_phone, trim(kiosk_item->>'facebook_id'),
        kiosk_item->>'facebook_link', customer_input->>'address',
        coalesce(kiosk_item->>'note', customer_input->>'note'), bt.category_id, bt.id,
        months_value, discount_value, kiosk_item->>'discount_reason');
    end if;
    used_request_ids := array_append(used_request_ids, request_id_value);
    update public.registration_requests set status = 'awaiting_payment',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('workflow', 'public_payos')
    where id = request_id_value;
    start_on := (pg_catalog.now() at time zone 'Europe/Berlin')::date;
    end_on := (start_on + pg_catalog.make_interval(months => months_value))::date;
    total_value := (bt.price_per_month * months_value) - discount_value;
    result_items := result_items || jsonb_build_array(jsonb_build_object(
      'request', jsonb_build_object('id', request_id_value, 'status', 'awaiting_payment'),
      'preview', jsonb_build_object('startDate', start_on, 'endDate', end_on, 'months', months_value,
        'pricePerMonth', bt.price_per_month, 'discount', discount_value, 'totalAmount', total_value),
      'businessType', jsonb_build_object('id', bt.id, 'name', bt.name)));
  end loop;
  return jsonb_build_object('customer', jsonb_build_object('facebook_name', customer_name,
    'facebook_link', nullif(trim(customer_input->>'facebook_link'), ''), 'phone', customer_phone),
    'kiosks', result_items, 'status', 'awaiting_payment',
    'bill_received', bill_input is not null and bill_input <> 'null'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_registration_request(facebook_name_input text, phone_input text, facebook_id_input text, facebook_link_input text, address_input text, note_input text, category_id_input bigint, business_type_id_input bigint, months_input integer, discount_input numeric, discount_reason_input text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bt public.business_types%rowtype;
  request_id bigint;
  start_on date;
  end_on date;
  subtotal numeric;
  final_total numeric;
begin
  if length(trim(coalesce(facebook_name_input, ''))) < 1 then raise exception 'Tên Facebook là bắt buộc.'; end if;
  if length(trim(coalesce(phone_input, ''))) < 6 then raise exception 'Số điện thoại không hợp lệ.'; end if;
  if months_input is null or months_input < 1 or months_input > 60 then raise exception 'Số tháng phải từ 1 đến 60.'; end if;
  if coalesce(discount_input, 0) < 0 then raise exception 'Giảm giá không hợp lệ.'; end if;
  select * into bt from public.business_types where id = business_type_id_input and is_active = true;
  if not found then raise exception 'Loại hình kinh doanh không hoạt động.'; end if;
  if bt.category_id is distinct from category_id_input then raise exception 'Danh mục và loại hình kinh doanh không khớp.'; end if;
  subtotal := bt.price_per_month * months_input;
  final_total := subtotal - coalesce(discount_input, 0);
  if final_total < 0 then raise exception 'Giảm giá không được lớn hơn tạm tính.'; end if;
  if coalesce(discount_input, 0) > 0 and length(trim(coalesce(discount_reason_input, ''))) < 1 then
    raise exception 'Cần nhập lý do giảm giá.';
  end if;
  start_on := (pg_catalog.now() at time zone 'Europe/Berlin')::date;
  end_on := (start_on + pg_catalog.make_interval(months => months_input))::date;
  insert into public.registration_requests(facebook_name, facebook_id, facebook_link, phone, address, note,
    service_name, category_id, business_type_id, requested_start_date, requested_end_date,
    months, price_per_month, discount, discount_reason, total_amount, payment_method, status)
  values(trim(facebook_name_input), nullif(trim(coalesce(facebook_id_input, '')), ''),
    nullif(trim(coalesce(facebook_link_input, '')), ''), trim(phone_input),
    nullif(trim(coalesce(address_input, '')), ''), nullif(trim(coalesce(note_input, '')), ''),
    bt.name, bt.category_id, bt.id, start_on, end_on, months_input, bt.price_per_month,
    coalesce(discount_input, 0), nullif(trim(coalesce(discount_reason_input, '')), ''),
    final_total, 'transfer', 'awaiting_payment') returning id into request_id;
  return request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_ttc_task(task_id_input bigint, evidence_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  task_record public.ttc_tasks%rowtype;
  campaign_record public.ttc_campaigns%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để gửi nhiệm vụ.' using errcode = '42501';
  end if;

  select *
  into task_record
  from public.ttc_tasks
  where id = task_id_input
    and assignee_user_id = auth.uid()
  for update;
  if not found then
    raise exception 'Không tìm thấy nhiệm vụ của bạn.' using errcode = '42501';
  end if;

  select *
  into campaign_record
  from public.ttc_campaigns
  where id = task_record.campaign_id
  for update;

  if campaign_record.status not in ('queued', 'running') then
    raise exception 'Chiến dịch không còn nhận kết quả nhiệm vụ.' using errcode = '22023';
  end if;
  if task_record.status not in ('assigned', 'submitted') then
    raise exception 'Nhiệm vụ không ở trạng thái có thể gửi.' using errcode = '22023';
  end if;

  update public.ttc_tasks
  set
    status = 'submitted',
    submitted_at = coalesce(submitted_at, now()),
    evidence = coalesce(evidence_input, '{}'::jsonb)
  where id = task_record.id
  returning * into task_record;

  insert into public.ttc_task_check_logs(task_id, campaign_id, actor_id, check_type, result, before_status, after_status, reason, metadata)
  values(task_record.id, task_record.campaign_id, auth.uid(), 'user_submit', 'pending', 'assigned', 'submitted', 'User gửi bằng chứng nhiệm vụ', coalesce(evidence_input, '{}'::jsonb));

  return jsonb_build_object('task', to_jsonb(task_record), 'credited', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_payos_order_status(order_code_input bigint, provider_input jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.payos_orders%rowtype; provider_status text;
begin
  if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Chỉ API server được đồng bộ PayOS.' using errcode='42501'; end if;
  select * into o from public.payos_orders where order_code=order_code_input;
  if not found then raise exception 'Không tìm thấy PayOS order.' using errcode='P0002'; end if;
  if o.payment_id is not null then perform 1 from public.payments where id=o.payment_id for update; end if;
  select * into o from public.payos_orders where id=o.id for update;
  if provider_input is not null then
    if (provider_input->>'orderCode')::bigint is distinct from o.order_code
      or (provider_input->>'amount')::numeric is distinct from o.amount
      or (o.payment_link_id is not null and provider_input->>'id' is distinct from o.payment_link_id) then
      perform private.mark_payos_review(o.id,'PROVIDER_MAPPING_MISMATCH');
    else
      provider_status:=upper(provider_input->>'status');
      update public.payos_orders set provider_payload=provider_payload||jsonb_build_object('_status',provider_input,'_status_checked_at',now()),
        status=case when status='pending' and provider_status in ('EXPIRED','CANCELLED') then lower(provider_status) else status end,
        active_slot=case when provider_status in ('EXPIRED','CANCELLED') then null else active_slot end,
        updated_at=now() where id=o.id;
      if coalesce((provider_input->>'amountPaid')::numeric,0)>0 and provider_status<>'PAID' then
        perform private.mark_payos_review(o.id,'PARTIAL_OR_LATE_PROVIDER_PAYMENT');
      end if;
    end if;
  end if;
  update public.payos_orders set status='expired',active_slot=null,updated_at=now()
    where id=o.id and status='pending' and expires_at<=now()
      and coalesce(provider_status,'')<>'PAID';
  select * into o from public.payos_orders where id=o.id;
  return to_jsonb(o);
end $function$

CREATE OR REPLACE FUNCTION public.update_customer_kiosk_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Xử lý khi THÊM một kiosk mới
  IF (TG_OP = 'INSERT') THEN
    IF NEW.customer_id IS NOT NULL THEN
      UPDATE public.customers
      SET total_kiosks = COALESCE(total_kiosks, 0) + 1
      WHERE id = NEW.customer_id;
    END IF;
  -- Xử lý khi XÓA một kiosk
  ELSIF (TG_OP = 'DELETE') THEN
    IF OLD.customer_id IS NOT NULL THEN
      UPDATE public.customers
      SET total_kiosks = GREATEST(COALESCE(total_kiosks, 1) - 1, 0)
      WHERE id = OLD.customer_id;
    END IF;
  -- Xử lý khi CẬP NHẬT một kiosk (ví dụ: đổi kiosk từ khách hàng A sang B)
  ELSIF (TG_OP = 'UPDATE') THEN
    IF OLD.customer_id IS DISTINCT FROM NEW.customer_id THEN
      -- Giảm số đếm cho khách hàng cũ (nếu có)
      IF OLD.customer_id IS NOT NULL THEN
        UPDATE public.customers
        SET total_kiosks = GREATEST(COALESCE(total_kiosks, 1) - 1, 0)
        WHERE id = OLD.customer_id;
      END IF;
      -- Tăng số đếm cho khách hàng mới (nếu có)
      IF NEW.customer_id IS NOT NULL THEN
        UPDATE public.customers
        SET total_kiosks = COALESCE(total_kiosks, 0) + 1
        WHERE id = NEW.customer_id;
      END IF;
    END IF;
  END IF;

  IF (TG_OP = 'DELETE') THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_organization_settings(settings_input jsonb, reason_input text DEFAULT 'Cập nhật cài đặt tổ chức'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  allowed_keys constant text[] := array[
    'official_group_name',
    'group_url',
    'sub_group_url',
    'recruitment_group_url',
    'fanpage_url',
    'zalo_url',
    'support_phone',
    'facebook_group_id',
    'warning_days',
    'company_info',
    'business_info',
    'system_settings'
  ];
  url_keys constant text[] := array[
    'group_url',
    'sub_group_url',
    'recruitment_group_url',
    'fanpage_url'
  ];
  setting_key text;
  setting_value text;
  old_values jsonb;
  new_values jsonb;
  warning_days integer;
begin
  actor := private.assert_active_admin();
  if settings_input is null or jsonb_typeof(settings_input) <> 'object' then
    raise exception 'Dữ liệu cài đặt không hợp lệ.' using errcode = '22023';
  end if;

  if exists (
    select 1 from jsonb_object_keys(settings_input) supplied_key
    where supplied_key <> all(allowed_keys)
  ) then
    raise exception 'Có khóa cài đặt không được phép.' using errcode = '22023';
  end if;

  if nullif(trim(settings_input ->> 'official_group_name'), '') is null then
    raise exception 'Tên nhóm chính thức là bắt buộc.' using errcode = '22023';
  end if;

  foreach setting_key in array url_keys loop
    setting_value := nullif(trim(settings_input ->> setting_key), '');
    if setting_value is not null and setting_value !~* '^https?://[^[:space:]]+$' then
      raise exception '% phải là URL HTTP hoặc HTTPS hợp lệ.', setting_key using errcode = '22023';
    end if;
  end loop;

  setting_value := nullif(trim(settings_input ->> 'facebook_group_id'), '');
  if setting_value is not null and setting_value !~ '^[0-9]+$' then
    raise exception 'Facebook Group ID chỉ được chứa chữ số.' using errcode = '22023';
  end if;

  begin
    warning_days := (settings_input ->> 'warning_days')::integer;
  exception when others then
    raise exception 'Số ngày cảnh báo phải là số nguyên.' using errcode = '22023';
  end;
  if warning_days < 1 or warning_days > 365 then
    raise exception 'Số ngày cảnh báo phải từ 1 đến 365.' using errcode = '22023';
  end if;

  select coalesce(jsonb_object_agg(s.key, coalesce(s.value, '')), '{}'::jsonb)
  into old_values
  from public.settings s
  where s.key = any(allowed_keys);

  for setting_key, setting_value in
    select entry.key, trim(coalesce(entry.value, ''))
    from jsonb_each_text(settings_input) entry
    where entry.key = any(allowed_keys)
  loop
    insert into public.settings(key, value)
    values(setting_key, setting_value)
    on conflict (key) do update set value = excluded.value;
  end loop;

  select coalesce(jsonb_object_agg(s.key, coalesce(s.value, '')), '{}'::jsonb)
  into new_values
  from public.settings s
  where s.key = any(allowed_keys);

  insert into public.audit_logs(
    actor_id, actor_name, actor_type, actor_role, module, entity,
    record_id, action, before, after, reason
  )
  values(
    actor.user_id,
    coalesce(actor.display_name, actor.username, 'Admin'),
    'staff',
    actor.role,
    'Settings',
    'settings',
    'organization',
    'update',
    old_values,
    new_values,
    coalesce(nullif(trim(reason_input), ''), 'Cập nhật cài đặt tổ chức')
  );

  return new_values;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_payment_note(payment_id_input bigint, note_input text, reason_input text DEFAULT 'Cập nhật ghi chú thanh toán'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
begin
  actor := private.assert_payment_permission();

  select *
  into payment_record
  from public.payments
  where id = payment_id_input
  for update;

  if not found then
    raise exception 'Không tìm thấy thanh toán.';
  end if;

  before_record := payment_record;

  update public.payments
  set note = nullif(trim(note_input), '')
  where id = payment_record.id
  returning * into payment_record;

  perform private.write_payment_audit(
    'update_note',
    to_jsonb(before_record),
    to_jsonb(payment_record),
    reason_input,
    actor
  );

  return to_jsonb(payment_record);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_pending_payment(payment_id_input bigint, months_input integer, discount_input numeric, payment_method_input text, discount_reason_input text DEFAULT NULL::text, note_input text DEFAULT NULL::text, reason_input text DEFAULT 'Cập nhật thanh toán Pending'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
  kiosk_record public.kiosks%rowtype;
  package_record public.business_types%rowtype;
  calculated_total numeric;
begin
  actor := private.assert_payment_permission();

  select *
  into payment_record
  from public.payments
  where id = payment_id_input
  for update;

  if not found then
    raise exception 'Không tìm thấy thanh toán.';
  end if;

  if lower(payment_record.payment_status) <> 'pending' then
    raise exception 'Chỉ thanh toán Pending mới được sửa.';
  end if;

  before_record := payment_record;

  if months_input is null or months_input < 1 then
    raise exception 'Số tháng phải là số nguyên lớn hơn 0.';
  end if;

  if discount_input is null or discount_input < 0 then
    raise exception 'Giảm giá không hợp lệ.';
  end if;

  if nullif(trim(payment_method_input), '') is null then
    raise exception 'Phương thức thanh toán là bắt buộc.';
  end if;

  select *
  into kiosk_record
  from public.kiosks
  where id = payment_record.kiosk_id;

  if not found or kiosk_record.customer_id <> payment_record.customer_id then
    raise exception 'Liên kết Khách hàng/Kiosk của thanh toán không hợp lệ.';
  end if;

  select *
  into package_record
  from public.business_types
  where id = kiosk_record.business_type_id
    and is_active = true;

  if not found or package_record.price_per_month is null or package_record.price_per_month < 0 then
    raise exception 'Gói dịch vụ không hợp lệ.';
  end if;

  calculated_total := package_record.price_per_month * months_input - discount_input;
  if calculated_total < 0 then
    raise exception 'Giảm giá không được lớn hơn tạm tính.';
  end if;

  perform set_config('app.payment_workflow_action', 'edit', true);

  update public.payments
  set
    months = months_input,
    price_per_month = package_record.price_per_month,
    discount = discount_input,
    discount_reason = nullif(trim(discount_reason_input), ''),
    total_amount = calculated_total,
    payment_method = trim(payment_method_input),
    start_date = null,
    end_date = null,
    note = nullif(trim(note_input), '')
  where id = payment_record.id
  returning * into payment_record;

  perform private.write_payment_audit(
    'update_pending',
    to_jsonb(before_record),
    to_jsonb(payment_record),
    reason_input,
    actor
  );

  return to_jsonb(payment_record);
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_my_facebook_account(account_id_input bigint DEFAULT NULL::bigint, facebook_url_original_input text DEFAULT NULL::text, facebook_url_normalized_input text DEFAULT NULL::text, facebook_id_input text DEFAULT NULL::text, facebook_id_status_input text DEFAULT NULL::text, is_primary_input boolean DEFAULT false, note_input text DEFAULT NULL::text, metadata_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile_record public.user_profiles%rowtype;
  existing_record public.user_facebook_accounts%rowtype;
  account_record public.user_facebook_accounts%rowtype;
  normalized_url_original text := nullif(trim(facebook_url_original_input), '');
  normalized_url text := nullif(trim(facebook_url_normalized_input), '');
  normalized_facebook_id text := nullif(regexp_replace(coalesce(facebook_id_input, ''), '[^0-9]', '', 'g'), '');
  normalized_status text := nullif(trim(facebook_id_status_input), '');
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để cập nhật Facebook.' using errcode = '42501';
  end if;

  select *
  into profile_record
  from public.user_profiles
  where user_id = auth.uid()
    and status <> 'locked'
  for update;
  if not found then
    raise exception 'Vui lòng tạo hồ sơ user trước.' using errcode = '42501';
  end if;

  if normalized_url_original is null then
    raise exception 'Link Facebook là bắt buộc.' using errcode = '22023';
  end if;
  if normalized_facebook_id is null and normalized_status in ('resolved', 'manual_verified') then
    raise exception 'Facebook ID là bắt buộc khi trạng thái đã xác minh.' using errcode = '22023';
  end if;
  if normalized_facebook_id is not null and normalized_facebook_id !~ '^[0-9]+$' then
    raise exception 'Facebook ID chỉ được chứa chữ số.' using errcode = '22023';
  end if;

  normalized_status := coalesce(
    normalized_status,
    case when normalized_facebook_id is null then 'pending' else 'resolved' end
  );
  if normalized_status not in ('resolved', 'pending', 'failed', 'manual_verified') then
    raise exception 'Trạng thái Facebook ID không hợp lệ.' using errcode = '22023';
  end if;

  if account_id_input is not null then
    select *
    into existing_record
    from public.user_facebook_accounts
    where id = account_id_input
      and user_id = auth.uid()
    for update;
    if not found then
      raise exception 'Không tìm thấy tài khoản Facebook của bạn.' using errcode = '42501';
    end if;
  end if;

  if normalized_facebook_id is not null and exists (
    select 1
    from public.user_facebook_accounts ufa
    where ufa.facebook_id = normalized_facebook_id
      and (account_id_input is null or ufa.id <> account_id_input)
  ) then
    raise exception 'Facebook ID này đã được liên kết với tài khoản khác.' using errcode = '23505';
  end if;

  if is_primary_input then
    update public.user_facebook_accounts
    set is_primary = false
    where user_id = auth.uid()
      and (account_id_input is null or id <> account_id_input);
  end if;

  if account_id_input is null then
    insert into public.user_facebook_accounts(
      user_id,
      facebook_id,
      facebook_url_original,
      facebook_url_normalized,
      facebook_id_status,
      resolved_at,
      resolved_by,
      is_primary,
      note,
      metadata
    )
    values(
      auth.uid(),
      normalized_facebook_id,
      normalized_url_original,
      coalesce(normalized_url, normalized_url_original),
      normalized_status,
      case when normalized_status in ('resolved', 'manual_verified') then now() else null end,
      case when normalized_status = 'manual_verified' then auth.uid() else null end,
      is_primary_input,
      nullif(trim(note_input), ''),
      coalesce(metadata_input, '{}'::jsonb)
    )
    returning * into account_record;
  else
    update public.user_facebook_accounts
    set
      facebook_id = normalized_facebook_id,
      facebook_url_original = normalized_url_original,
      facebook_url_normalized = coalesce(normalized_url, normalized_url_original),
      facebook_id_status = normalized_status,
      resolved_at = case when normalized_status in ('resolved', 'manual_verified') then coalesce(resolved_at, now()) else null end,
      resolved_by = case when normalized_status = 'manual_verified' then auth.uid() else resolved_by end,
      is_primary = is_primary_input,
      note = nullif(trim(note_input), ''),
      metadata = coalesce(metadata, '{}'::jsonb) || coalesce(metadata_input, '{}'::jsonb),
      updated_at = now()
    where id = account_id_input
      and user_id = auth.uid()
    returning * into account_record;
  end if;

  if not exists (
    select 1
    from public.user_facebook_accounts ufa
    where ufa.user_id = auth.uid()
      and ufa.is_primary = true
  ) then
    update public.user_facebook_accounts
    set is_primary = true
    where id = account_record.id
    returning * into account_record;
  end if;

  perform private.write_ttc_audit(
    'User',
    'upsert_facebook_account',
    'user_facebook_accounts',
    account_record.id::text,
    case when existing_record.id is null then null else to_jsonb(existing_record) end,
    jsonb_build_object(
      'id', account_record.id,
      'user_id', account_record.user_id,
      'facebook_id_status', account_record.facebook_id_status,
      'has_facebook_id', account_record.facebook_id is not null,
      'is_primary', account_record.is_primary
    ),
    'User cập nhật Facebook ID'
  );

  return jsonb_build_object('account', to_jsonb(account_record));
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_ttc_task(task_id_input bigint, action_input text, reason_input text DEFAULT NULL::text, metadata_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  task_record public.ttc_tasks%rowtype;
  before_task public.ttc_tasks%rowtype;
  campaign_record public.ttc_campaigns%rowtype;
  before_campaign public.ttc_campaigns%rowtype;
  ledger_result jsonb := null;
  normalized_action text := lower(trim(action_input));
  next_status text;
  log_result text;
begin
  actor := private.assert_ttc_staff('admin-ttc');

  select *
  into before_task
  from public.ttc_tasks
  where id = task_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy nhiệm vụ TTC.' using errcode = '22023';
  end if;
  if before_task.status = 'completed' then
    return jsonb_build_object('task', to_jsonb(before_task), 'already_processed', true);
  end if;
  if before_task.status not in ('submitted', 'verifying') then
    raise exception 'Nhiệm vụ chưa được user gửi hoặc không thể xác minh.' using errcode = '22023';
  end if;

  select *
  into before_campaign
  from public.ttc_campaigns
  where id = before_task.campaign_id
  for update;
  if not found then
    raise exception 'Không tìm thấy chiến dịch của nhiệm vụ.' using errcode = '22023';
  end if;
  if before_campaign.status not in ('queued', 'running') then
    raise exception 'Chiến dịch đã dừng/hủy nên không thể duyệt cộng xu nhiệm vụ.' using errcode = '23514';
  end if;
  if before_campaign.refunded_amount > 0 then
    raise exception 'Chiến dịch đã có hoàn xu nên không thể duyệt nhiệm vụ mới.' using errcode = '23514';
  end if;

  if normalized_action = 'approve' then
    next_status := 'completed';
    log_result := 'success';
  elsif normalized_action = 'reject' then
    if nullif(trim(reason_input), '') is null then
      raise exception 'Lý do từ chối nhiệm vụ là bắt buộc.' using errcode = '22023';
    end if;
    next_status := 'rejected';
    log_result := 'failed';
  elsif normalized_action = 'manual_review' then
    next_status := 'verifying';
    log_result := 'manual_review';
  else
    raise exception 'Thao tác xác minh nhiệm vụ không hợp lệ.' using errcode = '22023';
  end if;

  update public.ttc_tasks
  set
    status = next_status,
    verified_at = case when next_status in ('completed', 'rejected') then now() else verified_at end,
    verified_by = actor.user_id,
    verification_result = coalesce(metadata_input, '{}'::jsonb),
    rejection_reason = case when next_status = 'rejected' then trim(reason_input) else null end
  where id = before_task.id
  returning * into task_record;

  campaign_record := before_campaign;
  if next_status = 'completed' then
    update public.ttc_campaigns
    set
      completed_count = completed_count + 1,
      spent_amount = spent_amount + before_campaign.unit_cost,
      status = case
        when completed_count + 1 >= target_quantity then 'completed'
        else 'running'
      end
    where id = before_campaign.id
      and status in ('queued', 'running')
      and refunded_amount = 0
    returning * into campaign_record;

    if not found then
      raise exception 'Chiến dịch không còn đủ điều kiện cộng xu nhiệm vụ.' using errcode = '23514';
    end if;

    ledger_result := private.post_wallet_ledger(
      task_record.assignee_user_id,
      before_campaign.worker_reward,
      'earn_task',
      'ttc_tasks',
      task_record.id::text,
      'ttc_task:reward:' || task_record.id::text,
      'Thưởng nhiệm vụ TTC #' || task_record.id,
      coalesce(reason_input, 'Nhiệm vụ TTC đã xác minh thành công'),
      jsonb_build_object('task_id', task_record.id, 'campaign_id', before_campaign.id),
      actor.user_id,
      'staff'
    );
  end if;

  insert into public.ttc_task_check_logs(task_id, campaign_id, actor_id, check_type, result, before_status, after_status, reason, metadata)
  values(task_record.id, task_record.campaign_id, actor.user_id, 'manual', log_result, before_task.status, task_record.status, nullif(trim(reason_input), ''), coalesce(metadata_input, '{}'::jsonb));

  perform private.write_ttc_audit(
    'TTC',
    'verify_task_' || normalized_action,
    'ttc_tasks',
    task_record.id::text,
    to_jsonb(before_task),
    to_jsonb(task_record),
    reason_input
  );

  return jsonb_build_object(
    'task', to_jsonb(task_record),
    'campaign', to_jsonb(campaign_record),
    'wallet', ledger_result->'wallet',
    'credited', next_status = 'completed',
    'already_processed', false
  );
end;
$function$
